/* GTCHSK2 (2.0) · 标准教程 HSK2 — sinh tự động bằng _tools/app/convert.js từ bài giảng thư mục "2.4 - HSK2 (2.0) - optimize". Đừng sửa tay. */
window.SWMN_DATA=window.SWMN_DATA||{};window.SWMN_DATA["k2v2"]=[{"id":"k2v2-b01","courseId":"k2v2","order":1,"title":"Đi Bắc Kinh du lịch vào tháng 9 là tốt nhất","titleZh":"九月去北京旅游最好。","titlePy":"jiǔ yuè qù Běijīng lǚyóu zuì hǎo","vocab":[{"stt":1,"hanzi":"旅游","pinyin":"lǚyóu","hanviet":"Lữ Du","pos":"Động từ","meaning":"du lịch, đi du lịch","comps":"去旅游 (đi du lịch), 旅游的人 (khách du lịch)","example":{"zh":"我要去北京旅游。","py":"Wǒ yào qù Běijīng lǚyóu.","vi":"Mình muốn đi Bắc Kinh du lịch."}},{"stt":2,"hanzi":"觉得","pinyin":"juéde","hanviet":"Giác Đắc","pos":"Động từ","meaning":"cảm thấy, thấy rằng","comps":"我觉得 (mình thấy rằng), 觉得好 (thấy tốt)","example":{"zh":"我觉得它很漂亮。","py":"Wǒ juéde tā hěn piàoliang.","vi":"Mình thấy nó rất đẹp."}},{"stt":3,"hanzi":"最","pinyin":"zuì","hanviet":"Tối","pos":"Phó từ","meaning":"nhất, hơn cả","comps":"最好 (tốt nhất), 最喜欢 (thích nhất)","example":{"zh":"我最喜欢踢足球。","py":"Wǒ zuì xǐhuan tī zúqiú.","vi":"Mình thích đá bóng nhất."}},{"stt":4,"hanzi":"为什么","pinyin":"wèi shénme","hanviet":"Vi Thập Ma","pos":"Đại từ nghi vấn","meaning":"vì sao, tại sao","comps":"为什么不 (vì sao không), 为什么去 (vì sao đi)","example":{"zh":"你为什么不去？","py":"Nǐ wèi shénme bú qù?","vi":"Sao bạn không đi vậy?"}},{"stt":5,"hanzi":"也","pinyin":"yě","hanviet":"Dã","pos":"Phó từ","meaning":"cũng","comps":"我也 (mình cũng), 也是 (cũng là)","example":{"zh":"我也要去北京。","py":"Wǒ yě yào qù Běijīng.","vi":"Mình cũng muốn đi Bắc Kinh."}},{"stt":6,"hanzi":"运动","pinyin":"yùndòng","hanviet":"Vận Động","pos":"Động từ","meaning":"vận động; môn thể thao","comps":"喜欢运动 (thích vận động), 什么运动 (môn thể thao gì)","example":{"zh":"你喜欢什么运动？","py":"Nǐ xǐhuan shénme yùndòng?","vi":"Bạn thích môn thể thao nào?"}},{"stt":7,"hanzi":"踢足球","pinyin":"tī zúqiú","hanviet":"Thích Túc Cầu","pos":"Cụm từ","meaning":"đá bóng, chơi bóng đá","comps":"去踢足球 (đi đá bóng), 会踢足球 (biết đá bóng)","example":{"zh":"我们一起去踢足球。","py":"Wǒmen yìqǐ qù tī zúqiú.","vi":"Chúng mình cùng đi đá bóng."}},{"stt":8,"hanzi":"一起","pinyin":"yìqǐ","hanviet":"Nhất Khởi","pos":"Phó từ","meaning":"cùng nhau, cùng","comps":"一起去 (cùng đi), 和…一起 (cùng với…)","example":{"zh":"下午我们一起去。","py":"Xiàwǔ wǒmen yìqǐ qù.","vi":"Chiều nay chúng mình cùng đi."}},{"stt":9,"hanzi":"要","pinyin":"yào","hanviet":"Yếu","pos":"Động từ","meaning":"muốn, định (làm gì)","comps":"要去 (muốn đi), 要不要 (có muốn không)","example":{"zh":"我要买一个新椅子。","py":"Wǒ yào mǎi yí ge xīn yǐzi.","vi":"Mình muốn mua một cái ghế mới."}},{"stt":10,"hanzi":"新","pinyin":"xīn","hanviet":"Tân","pos":"Tính từ","meaning":"mới","comps":"新的 (cái mới), 新椅子 (ghế mới)","example":{"zh":"我们买几个新椅子。","py":"Wǒmen mǎi jǐ ge xīn yǐzi.","vi":"Chúng mình mua vài cái ghế mới."}},{"stt":11,"hanzi":"它","pinyin":"tā","hanviet":"Tha","pos":"Đại từ","meaning":"nó (đồ vật, con vật)","comps":"它的 (của nó), 它们 (chúng nó)","example":{"zh":"它叫花花。","py":"Tā jiào Huāhua.","vi":"Nó tên là Hoa Hoa."}},{"stt":12,"hanzi":"眼睛","pinyin":"yǎnjing","hanviet":"Nhãn Tinh","pos":"Danh từ","meaning":"mắt, đôi mắt","comps":"大眼睛 (mắt to), 我的眼睛 (mắt của mình)","example":{"zh":"它的眼睛很漂亮。","py":"Tā de yǎnjing hěn piàoliang.","vi":"Mắt của nó rất đẹp."}},{"stt":13,"hanzi":"花花","pinyin":"Huāhua","hanviet":"Hoa Hoa","pos":"Danh từ riêng","meaning":"Hoa Hoa (tên con mèo)","comps":"叫花花 (tên là Hoa Hoa), 小花 (Tiểu Hoa)","example":{"zh":"它叫花花，很漂亮。","py":"Tā jiào Huāhua, hěn piàoliang.","vi":"Nó tên là Hoa Hoa, rất đẹp."}}],"hanzi":[{"char":"旅游","pinyin":"lǚyóu","hanviet":"Lữ Du","chars":["旅","游"],"story":"旅 có bộ 方 (lá cờ) bên trái, chữ gốc vẽ đoàn người đi theo cờ hiệu, nên nghĩa là \"đi xa\". 游 có bộ 氵(nước), vốn chỉ việc bơi lội, trôi nổi đây đó. Ghép lại 旅游 = đi xa rong chơi, tức \"du lịch\". Âm Hán Việt là \"Lữ Du\"."},{"char":"觉得","pinyin":"juéde","hanviet":"Giác Đắc","chars":["觉","得"],"story":"觉 có bộ 见 (nhìn thấy) ở dưới, chỉ việc cảm nhận được bằng giác quan — âm Hán Việt là \"Giác\", như trong \"cảm giác\". 得 có bộ 彳 (bước đi) + 寸 (bàn tay), nghĩa gốc là \"được, đạt được\". 觉得 = cảm nhận thấy được, tức \"cảm thấy, thấy rằng\"."},{"char":"最","pinyin":"zuì","hanviet":"Tối","chars":["最"],"story":"最 gồm 曰 (nói) ở trên và 取 (lấy) ở dưới, nghĩa gốc là \"gom lấy được nhiều hơn cả\", từ đó thành phó từ chỉ mức độ cao nhất. Âm Hán Việt là \"Tối\", chính là chữ trong \"tối đa\", \"tối ưu\" — nhớ được nghĩa \"nhất\" ngay."},{"char":"为什么","pinyin":"wèi shénme","hanviet":"Vi Thập Ma","chars":["为","什","么"],"story":"为 (Vi) nghĩa là \"vì, làm cho\"; 什 gồm 亻(người) + 十; 么 chỉ âm đọc. Cụm 什么 các em đã học ở HSK1 là \"cái gì\", nên 为什么 nghĩa đen là \"vì cái gì\" → \"vì sao, tại sao\"."},{"char":"也","pinyin":"yě","hanviet":"Dã","chars":["也"],"story":"也 vốn là chữ tượng hình vẽ một vật có nét cong dài, nay không còn giữ nghĩa gốc mà chỉ dùng làm phó từ \"cũng\". Âm Hán Việt là \"Dã\". Mẹo nhớ: nét cuối kéo ngang bằng nhau, như ý \"tôi cũng vậy, hai bên như nhau\"."},{"char":"运动","pinyin":"yùndòng","hanviet":"Vận Động","chars":["运","动"],"story":"运 có bộ 辶 (bước đi) + 云 (mây, chỉ âm), nghĩa là \"chuyển động, vận chuyển\". 动 nghĩa là \"cử động\". Ghép lại 运动 = làm cho cơ thể chuyển động → \"vận động, thể thao\". Âm Hán Việt \"Vận Động\" trùng khít nghĩa tiếng Việt."},{"char":"踢足球","pinyin":"tī zúqiú","hanviet":"Thích Túc Cầu","chars":["踢","足","球"],"story":"踢 có bộ ⻊ (bàn chân) nên là động tác làm bằng chân, tức \"đá\"; 易 bên phải chỉ âm. 足 là chữ tượng hình vẽ bàn chân. 球 có bộ 王 (ngọc) — vật tròn nhẵn như viên ngọc, tức \"quả bóng\". Cả cụm là \"đá quả bóng bằng chân\"."},{"char":"一起","pinyin":"yìqǐ","hanviet":"Nhất Khởi","chars":["一","起"],"story":"一 là \"một\". 起 có bộ 走 (chạy, đi) bên trái, nghĩa là \"đứng dậy, khởi đầu\" — âm Hán Việt \"Khởi\", như trong \"khởi hành\". 一起 nghĩa đen là \"cùng đứng dậy một lượt\", nên thành \"cùng nhau\"."},{"char":"要","pinyin":"yào","hanviet":"Yếu","chars":["要"],"story":"要 gồm 覀 ở trên và 女 ở dưới, chữ gốc vẽ người phụ nữ chống hai tay lên eo — nghĩa gốc là \"cái eo\" (nay viết thành 腰). Về sau chữ này được mượn dùng cho nghĩa \"muốn, cần\". Âm Hán Việt là \"Yếu\", như trong \"cần yếu, quan trọng\"."},{"char":"新","pinyin":"xīn","hanviet":"Tân","chars":["新"],"story":"新 bên trái là 亲 (chỉ âm) kèm bộ 木 (cây), bên phải là 斤 (cái rìu). Nghĩa gốc là dùng rìu đốn cây lấy củi tươi vừa chặt, từ đó ra nghĩa \"mới\". Âm Hán Việt là \"Tân\", như trong \"tân sinh viên\", \"tân niên\"."},{"char":"它","pinyin":"tā","hanviet":"Tha","chars":["它"],"story":"它 có bộ 宀 (mái nhà) ở trên, dưới là 匕; chữ gốc vẽ con rắn (về sau viết thành 蛇). Ngày nay 它 làm đại từ ngôi thứ ba chỉ đồ vật và con vật, khác 他 (人 — người nam) và 她 (女 — người nữ) đúng ở bộ bên trái."},{"char":"眼睛","pinyin":"yǎnjing","hanviet":"Nhãn Tinh","chars":["眼","睛"],"story":"Cả hai chữ đều có bộ 目 (con mắt) bên trái: 眼 = 目 + 艮 (chỉ âm), 睛 = 目 + 青 (chỉ âm). Đây là cặp hình thanh điển hình — cứ thấy bộ 目 là đoán được chữ nói về mắt và việc nhìn."},{"char":"花花","pinyin":"Huāhua","hanviet":"Hoa Hoa","chars":["花","花"],"story":"花 gồm bộ 艹 (cỏ cây) ở trên + 化 (chỉ âm) ở dưới, nghĩa là \"bông hoa\". Người Trung Quốc hay lặp lại một chữ để đặt tên thân mật cho thú cưng, nên 花花 nghe dễ thương như \"Bông Bông\" trong tiếng Việt."}],"grammar":[{"title":"Động từ năng nguyện 要 (nguyện vọng)","formula":"<div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>要</b><small>muốn, định</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b><small>tân ngữ</small></span></div><div class=\"fx-ex zh\">我要去北京旅游。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不想</b><small>không muốn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>宾语</b><small>tân ngữ</small></span></div><div class=\"fx-ex zh\">我不想去北京旅游。</div>","summary":"<p class=\"gr-lead\">Muốn / định làm việc gì</p><ul><li><b>Vị trí:</b> trước động từ　·　<b>Ý nghĩa:</b> nguyện vọng, ý định — <b>\"muốn, định\"</b></li><li><b>Câu hỏi:</b> <span class=\"zh\">要…吗？</span>　·　<span class=\"zh\">要不要…？</span></li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"hot\">⚠ <span class=\"zh\">不要</span> mang nghĩa <b>\"không cần\"</b></span>　<span class=\"zh\">你要喝茶吗？——不要，谢谢。</span>　(Không cần đâu, cảm ơn.)</p>","note":"<b>Lưu ý:</b> <b>Phủ định:</b> <span class=\"zh\">不想</span> = không muốn　·　<span class=\"zh\">不要</span> = <b>không cần</b>","examples":[{"zh":"王方要学习英语。","py":"Wáng Fāng yào xuéxí Yīngyǔ.","vi":"Vương Phương muốn học tiếng Anh."},{"zh":"我要吃米饭。","py":"Wǒ yào chī mǐfàn.","vi":"Mình muốn ăn cơm."},{"zh":"我们要不要买几个新椅子？","py":"Wǒmen yào bu yào mǎi jǐ ge xīn yǐzi?","vi":"Chúng mình có mua vài cái ghế mới không?"},{"zh":"小王要去，我不想去。","py":"Xiǎo Wáng yào qù, wǒ bù xiǎng qù.","vi":"Tiểu Vương muốn đi, mình không muốn đi."},{"zh":"A：你要吃米饭吗？　B：我不想吃米饭。","py":"Nǐ yào chī mǐfàn ma?  Wǒ bù xiǎng chī mǐfàn.","vi":"Bạn có muốn ăn cơm không? — Mình không muốn ăn cơm."},{"zh":"A：我要去商店买椅子，你去吗？　B：我不去，我不想买椅子。","py":"Wǒ yào qù shāngdiàn mǎi yǐzi, nǐ qù ma?  Wǒ bú qù, wǒ bù xiǎng mǎi yǐzi.","vi":"Mình định ra cửa hàng mua ghế, bạn đi không? — Mình không đi, mình không muốn mua ghế."}],"exercises":[]},{"title":"Phó từ mức độ 最","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>最</b><small>nhất</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词 / 动词</b><small>tính từ / động từ</small></span></div>","summary":"<p class=\"gr-lead\">Diễn tả mức độ cao nhất</p><ul><li><span class=\"zh\">最</span> đứng <b>ngay trước</b> tính từ, hoặc trước động từ chỉ tâm lý như <span class=\"zh\">喜欢、想、爱</span>, để chỉ mức độ <b>cao nhất</b> trong một phạm vi.</li><li>Phạm vi so sánh thường ngầm hiểu, không cần nói ra: <span class=\"zh\">九月去北京旅游最好。</span> (so với các tháng khác trong năm).</li><li>Có thể nằm giữa câu, sau chủ ngữ nhỏ: <span class=\"zh\">我觉得它的眼睛最漂亮。</span></li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">九月去北京旅游最好。</span>　·　<span class=\"zh\">我最喜欢踢足球。</span></p>","note":"<b>Lưu ý:</b> Không nói <span class=\"zh\">很最好</span> hay <span class=\"zh\">最很好</span> — <span class=\"zh\">最</span> đã là mức cao nhất nên <b>không đi kèm</b> phó từ mức độ khác.","examples":[{"zh":"大卫的汉语最好。","py":"Dàwèi de Hànyǔ zuì hǎo.","vi":"Tiếng Trung của David là giỏi nhất."},{"zh":"我最喜欢吃米饭。","py":"Wǒ zuì xǐhuan chī mǐfàn.","vi":"Mình thích ăn cơm nhất."},{"zh":"它的眼睛最漂亮。","py":"Tā de yǎnjing zuì piàoliang.","vi":"Đôi mắt của nó là đẹp nhất."}],"exercises":[]},{"title":"Diễn tả ước lượng với 几 và 多","formula":"","summary":"<p class=\"gr-lead\">Nói số lượng áng chừng</p><div class=\"gr-sub\"><h4><span class=\"zh\">概数 \"几\"</span></h4><p>Số ước lượng dưới 10 — \"vài, mấy\"</p><ul><li><b>Cách dùng:</b> chỉ con số ước lượng <b>dưới 10</b> — dịch là <b>\"vài, mấy\"</b></li></ul><p class=\"gr-key\"><span class=\"zh\">几个新椅子</span> vài cái ghế mới　·　<span class=\"zh\">几本书</span> vài quyển sách　·　<span class=\"zh\">几个人</span> vài người</p></div><div class=\"gr-sub\"><h4><span class=\"zh\">概数 \"多\"</span></h4><p>Số ước lượng — dịch là \"hơn\"</p><ul><li><b>Cách dùng:</b> chỉ con số ước lượng, dịch là <b>\"hơn\"</b></li></ul><div class=\"gr-formula\"><div class=\"fx-lbl\">Số chẵn chục</div><div class=\"fx-row\"><span class=\"fx-p\"><b>整十数</b><small>10, 20, 30…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多</b><small>hơn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>danh từ</small></span></div><div class=\"fx-ex zh\">十多个星期 · 二十多个人</div><div class=\"fx-lbl\">Số không chẵn chục</div><div class=\"fx-row\"><span class=\"fx-p\"><b>数词</b><small>1 – 9…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多</b><small>hơn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>danh từ</small></span></div><div class=\"fx-ex zh\">三个多星期 · 六个多月</div></div></div>","note":"<b>Lưu ý:</b> <b>Lưu ý 1:</b> số không chẵn chục + LT + <span class=\"zh\">多</span> chỉ dùng với danh từ <b>chia nhỏ được</b> (thời gian, tiền…) — ✗<span class=\"zh\">三个多人</span><br><b>Lưu ý 2:</b> <span class=\"zh\">年、天、岁、块</span> tự làm lượng từ → <span class=\"zh\">五年多、三块多钱</span>; <span class=\"zh\">月、星期</span> phải có <span class=\"zh\">个</span> → <span class=\"zh\">六个多月</span>","examples":[{"zh":"车上有几个人。","py":"Chē shang yǒu jǐ ge rén.","vi":"Trên xe có vài người."},{"zh":"我想买几本书。","py":"Wǒ xiǎng mǎi jǐ běn shū.","vi":"Mình muốn mua vài quyển sách."},{"zh":"我们要不要买几个新的椅子？","py":"Wǒmen yào bu yào mǎi jǐ ge xīn de yǐzi?","vi":"Chúng mình có mua vài cái ghế mới không?"},{"zh":"三个多星期","py":"sān ge duō xīngqī","vi":"hơn ba tuần"},{"zh":"五年多","py":"wǔ nián duō","vi":"hơn năm năm"},{"zh":"六个多月","py":"liù ge duō yuè","vi":"hơn sáu tháng"},{"zh":"十多个星期","py":"shí duō ge xīngqī","vi":"hơn mười tuần"},{"zh":"十多个月","py":"shí duō ge yuè","vi":"hơn mười tháng"},{"zh":"十多块钱","py":"shí duō kuài qián","vi":"hơn mười đồng (tệ)"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · HỘI THOẠI","titleVi":"Ở trường — bàn chuyện đi Bắc Kinh","lines":[{"speaker":"甲","name":"Bạn A","zh":"我要去北京旅游，你觉得什么时候去最好？","py":"Wǒ yào qù Běijīng lǚyóu, nǐ juéde shénme shíhou qù zuì hǎo?","vi":"Mình muốn đi Bắc Kinh du lịch, bạn thấy đi lúc nào là tốt nhất?"},{"speaker":"乙","name":"Bạn B","zh":"九月去北京旅游最好。","py":"Jiǔ yuè qù Běijīng lǚyóu zuì hǎo.","vi":"Tháng chín đi Bắc Kinh du lịch là tốt nhất."},{"speaker":"甲","name":"Bạn A","zh":"为什么？","py":"Wèi shénme?","vi":"Vì sao vậy?"},{"speaker":"乙","name":"Bạn B","zh":"九月的北京天气不冷不热。","py":"Jiǔ yuè de Běijīng tiānqì bù lěng bú rè.","vi":"Bắc Kinh tháng chín thời tiết không lạnh cũng không nóng."}]},{"titleZh":"课文二 · HỘI THOẠI","titleVi":"Xem ảnh — nói chuyện thể thao","lines":[{"speaker":"甲","name":"Bạn A","zh":"你喜欢什么运动？","py":"Nǐ xǐhuan shénme yùndòng?","vi":"Bạn thích môn thể thao nào?"},{"speaker":"乙","name":"Bạn B","zh":"我最喜欢踢足球。","py":"Wǒ zuì xǐhuan tī zúqiú.","vi":"Mình thích đá bóng nhất."},{"speaker":"甲","name":"Bạn A","zh":"下午我们一起去踢足球吧。","py":"Xiàwǔ wǒmen yìqǐ qù tī zúqiú ba.","vi":"Chiều nay chúng mình cùng đi đá bóng nhé."},{"speaker":"乙","name":"Bạn B","zh":"好啊！","py":"Hǎo a!","vi":"Được thôi!"}]},{"titleZh":"课文三 · HỘI THOẠI","titleVi":"Ở nhà — bàn chuyện mua ghế mới","lines":[{"speaker":"甲","name":"Bạn A","zh":"我们要不要买几个新椅子？","py":"Wǒmen yào bu yào mǎi jǐ ge xīn yǐzi?","vi":"Chúng mình có mua mấy cái ghế mới không nhỉ?"},{"speaker":"乙","name":"Bạn B","zh":"好啊。什么时候去买？","py":"Hǎo a. Shénme shíhou qù mǎi?","vi":"Được đấy. Khi nào thì đi mua?"},{"speaker":"甲","name":"Bạn A","zh":"明天下午怎么样？","py":"Míngtiān xiàwǔ zěnmeyàng?","vi":"Chiều mai thì thế nào?"},{"speaker":"乙","name":"Bạn B","zh":"你明天几点能回来？","py":"Nǐ míngtiān jǐ diǎn néng huílái?","vi":"Mai mấy giờ bạn về được?"},{"speaker":"甲","name":"Bạn A","zh":"三点多。","py":"Sān diǎn duō.","vi":"Hơn ba giờ."}]},{"titleZh":"课文四 · HỘI THOẠI","titleVi":"Ở nhà — khách nhìn thấy con mèo","lines":[{"speaker":"甲","name":"Bạn A","zh":"桌子下面有个猫。","py":"Zhuōzi xiàmiàn yǒu ge māo.","vi":"Dưới gầm bàn có một con mèo kìa."},{"speaker":"乙","name":"Bạn B","zh":"那是我的猫，它叫花花。","py":"Nà shì wǒ de māo, tā jiào Huāhua.","vi":"Đó là mèo của mình, nó tên là Hoa Hoa."},{"speaker":"甲","name":"Bạn A","zh":"它很漂亮。","py":"Tā hěn piàoliang.","vi":"Nó xinh quá."},{"speaker":"乙","name":"Bạn B","zh":"是啊，我觉得它的眼睛最漂亮。","py":"Shì a, wǒ juéde tā de yǎnjing zuì piàoliang.","vi":"Đúng vậy, mình thấy đôi mắt của nó là đẹp nhất."},{"speaker":"甲","name":"Bạn A","zh":"它多大了？","py":"Tā duō dà le?","vi":"Nó được mấy tháng rồi?"},{"speaker":"乙","name":"Bạn B","zh":"六个多月。","py":"Liù ge duō yuè.","vi":"Hơn sáu tháng rồi."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"双音节词的重音","grpVi":"Trọng âm của từ có hai âm tiết","zh":"中重格式","py":"zhōng zhòng géshì","tag":"Trọng âm","vi":"Cấu trúc \"nhấn vừa + nhấn mạnh\"","listZh":"中重格式","listVi":"Cấu trúc \"nhấn vừa + nhấn mạnh\" — đa số từ hai âm tiết","descZh":"大多数双音节词属中重格式，第二个音节为重音，音长较长。","descVi":"Đa số từ có hai âm tiết thuộc cấu trúc \"nhấn vừa + nhấn mạnh\", trong đó âm tiết thứ hai được đọc nhấn mạnh và kéo dài hơn.","pat":[{"l":"Âm tiết 1","s":"nhấn vừa"},{"l":"Âm tiết 2","s":"nhấn mạnh · kéo dài","st":true}],"tip":"Người Việt hay đọc đều hai âm tiết — hãy <b>kéo dài và nhấn rõ âm tiết sau</b>.","rows":[[{"hz":"冰箱","syl":["bīng","xiāng"],"st":1,"vi":"tủ lạnh"},{"hz":"帮忙","syl":["bāng","máng"],"sp":true,"st":1,"vi":"giúp đỡ"},{"hz":"打扰","syl":["dǎ","rǎo"],"st":1,"vi":"làm phiền"},{"hz":"高兴","syl":["gāo","xìng"],"st":1,"vi":"vui vẻ"}],[{"hz":"旅游","syl":["lǚ","yóu"],"st":1,"vi":"du lịch"},{"hz":"可能","syl":["kě","néng"],"st":1,"vi":"có thể"},{"hz":"开始","syl":["kāi","shǐ"],"st":1,"vi":"bắt đầu"},{"hz":"考试","syl":["kǎo","shì"],"sp":true,"st":1,"vi":"thi, kiểm tra"}]]},{"id":"pa-02","grp":"双音节词的重音","grpVi":"Trọng âm của từ có hai âm tiết","zh":"重轻格式","py":"zhòng qīng géshì","tag":"Trọng âm","vi":"Cấu trúc \"nhấn mạnh + đọc nhẹ\"","listZh":"重轻格式","listVi":"Cấu trúc \"nhấn mạnh + đọc nhẹ\" — một số ít từ hai âm tiết","descZh":"少数双音节词是\"重轻\"格式，第一个音节为重音，音长较长；第二个音节为轻音，音长较短。","descVi":"Một số ít từ có hai âm tiết thuộc cấu trúc \"nhấn mạnh + đọc nhẹ\", trong đó âm tiết thứ nhất được đọc nhấn mạnh và kéo dài hơn còn âm tiết thứ hai được phát âm nhẹ và nhanh.","pat":[{"l":"Âm tiết 1","s":"nhấn mạnh · kéo dài","st":true},{"l":"Âm tiết 2","s":"đọc nhẹ · nhanh","lt":true}],"tip":"Âm tiết đọc nhẹ chính là <b>thanh nhẹ</b> đã học ở HSK1 — pinyin không đánh dấu thanh.","rows":[[{"hz":"东西","syl":["dōng","xi"],"st":0,"lt":1,"vi":"đồ vật"},{"hz":"窗户","syl":["chuāng","hu"],"st":0,"lt":1,"vi":"cửa sổ"},{"hz":"萝卜","syl":["luó","bo"],"st":0,"lt":1,"vi":"củ cải"},{"hz":"时候","syl":["shí","hou"],"st":0,"lt":1,"vi":"lúc, khi"}],[{"hz":"枕头","syl":["zhěn","tou"],"st":0,"lt":1,"vi":"cái gối"},{"hz":"你们","syl":["nǐ","men"],"st":0,"lt":1,"vi":"các bạn"},{"hz":"告诉","syl":["gào","su"],"st":0,"lt":1,"vi":"nói cho biết"},{"hz":"故事","syl":["gù","shi"],"st":0,"lt":1,"vi":"câu chuyện"}]]}],"activity":{"act":[{"tag":"Hoạt động","mean":"","q":{"zh":"谈谈你最想 / 不想去的地方。为什么？","py":"Tántan nǐ zuì xiǎng / bù xiǎng qù de dìfang. Wèi shénme?","vi":"Hãy nói về nơi bạn muốn đến nhất / không muốn đến nhất. Vì sao?"},"items":[{"zh":"我最想去……旅游。","py":"Wǒ zuì xiǎng qù …… lǚyóu.","vi":"Mình muốn đi … du lịch nhất."},{"zh":"我觉得……最……。","py":"Wǒ juéde …… zuì …….","vi":"Mình thấy … là … nhất."},{"zh":"我不想去……，……太……了。","py":"Wǒ bù xiǎng qù ……, …… tài …… le.","vi":"Mình không muốn đến …, … quá … ."},{"lines":[{"who":"A","zh":"你最想去哪儿？为什么？","py":"Nǐ zuì xiǎng qù nǎr? Wèi shénme?","vi":"Bạn muốn đi đâu nhất? Vì sao?"},{"who":"B","zh":"我最想去北京，我觉得九月的北京最漂亮。","py":"Wǒ zuì xiǎng qù Běijīng, wǒ juéde jiǔ yuè de Běijīng zuì piàoliang.","vi":"Mình muốn đi Bắc Kinh nhất, mình thấy Bắc Kinh tháng chín đẹp nhất."}]}]}],"speak":[]}},{"id":"k2v2-b02","courseId":"k2v2","order":2,"title":"Hàng ngày tôi thức dậy lúc 6 giờ","titleZh":"我每天六点起床。","titlePy":"wǒ měi tiān liù diǎn qǐchuáng","vocab":[{"stt":1,"hanzi":"生病","pinyin":"shēngbìng","hanviet":"Sinh Bệnh","pos":"Động từ","meaning":"ốm, bị bệnh","comps":"很少生病 (ít khi ốm), 生病了 (bị ốm rồi)","example":{"zh":"我很少生病。","py":"Wǒ hěn shǎo shēngbìng.","vi":"Mình ít khi bị ốm."}},{"stt":2,"hanzi":"每","pinyin":"měi","hanviet":"Mỗi","pos":"Đại từ","meaning":"mỗi, mọi","comps":"每天 (mỗi ngày), 每个人 (mỗi người)","example":{"zh":"我每天六点起床。","py":"Wǒ měi tiān liù diǎn qǐchuáng.","vi":"Mỗi ngày mình dậy lúc sáu giờ."}},{"stt":3,"hanzi":"早上","pinyin":"zǎoshang","hanviet":"Tảo Thượng","pos":"Danh từ","meaning":"buổi sáng, sáng sớm","comps":"每天早上 (sáng nào cũng), 早上好 (chào buổi sáng)","example":{"zh":"我早上去跑步。","py":"Wǒ zǎoshang qù pǎobù.","vi":"Buổi sáng mình đi chạy bộ."}},{"stt":4,"hanzi":"跑步","pinyin":"pǎobù","hanviet":"Bào Bộ","pos":"Động từ","meaning":"chạy bộ","comps":"去跑步 (đi chạy bộ), 喜欢跑步 (thích chạy bộ)","example":{"zh":"他每天早上跑步。","py":"Tā měi tiān zǎoshang pǎobù.","vi":"Sáng nào cậu ấy cũng chạy bộ."}},{"stt":5,"hanzi":"起床","pinyin":"qǐchuáng","hanviet":"Khởi Sàng","pos":"Động từ","meaning":"ngủ dậy, thức dậy","comps":"几点起床 (mấy giờ dậy), 早点起床 (dậy sớm một chút)","example":{"zh":"你每天几点起床？","py":"Nǐ měi tiān jǐ diǎn qǐchuáng?","vi":"Mỗi ngày bạn dậy lúc mấy giờ?"}},{"stt":6,"hanzi":"药","pinyin":"yào","hanviet":"Dược","pos":"Danh từ","meaning":"thuốc","comps":"吃药 (uống thuốc), 买药 (mua thuốc)","example":{"zh":"你吃药了吗？","py":"Nǐ chī yào le ma?","vi":"Bạn uống thuốc chưa?"}},{"stt":7,"hanzi":"身体","pinyin":"shēntǐ","hanviet":"Thân Thể","pos":"Danh từ","meaning":"cơ thể; sức khoẻ","comps":"身体好 (sức khoẻ tốt), 身体不好 (sức khoẻ kém)","example":{"zh":"你现在身体怎么样？","py":"Nǐ xiànzài shēntǐ zěnmeyàng?","vi":"Giờ sức khoẻ bạn thế nào?"}},{"stt":8,"hanzi":"出院","pinyin":"chūyuàn","hanviet":"Xuất Viện","pos":"Động từ","meaning":"ra viện, xuất viện","comps":"能出院 (được ra viện), 出院了 (đã ra viện)","example":{"zh":"他下个星期出院。","py":"Tā xià ge xīngqī chūyuàn.","vi":"Tuần sau anh ấy ra viện."}},{"stt":9,"hanzi":"出","pinyin":"chū","hanviet":"Xuất","pos":"Động từ","meaning":"ra, đi ra","comps":"出去 (đi ra ngoài), 出来 (ra đây)","example":{"zh":"我早上出去跑步。","py":"Wǒ zǎoshang chūqù pǎobù.","vi":"Buổi sáng mình ra ngoài chạy bộ."}},{"stt":10,"hanzi":"高","pinyin":"gāo","hanviet":"Cao","pos":"Tính từ","meaning":"cao","comps":"多高 (cao bao nhiêu), 很高 (rất cao)","example":{"zh":"他很高，一米八。","py":"Tā hěn gāo, yī mǐ bā.","vi":"Cậu ấy cao lắm, một mét tám."}},{"stt":11,"hanzi":"米","pinyin":"mǐ","hanviet":"Mễ","pos":"Lượng từ","meaning":"mét (đơn vị đo); gạo","comps":"一米八 (một mét tám), 大米 (gạo tẻ)","example":{"zh":"他一米八几。","py":"Tā yī mǐ bā jǐ.","vi":"Cậu ấy cao một mét tám mấy."}},{"stt":12,"hanzi":"知道","pinyin":"zhīdào","hanviet":"Tri Đạo","pos":"Động từ","meaning":"biết, biết được","comps":"我知道 (mình biết), 不知道 (không biết)","example":{"zh":"你怎么知道？","py":"Nǐ zěnme zhīdào?","vi":"Sao bạn biết vậy?"}},{"stt":13,"hanzi":"休息","pinyin":"xiūxi","hanviet":"Hưu Tức","pos":"Động từ","meaning":"nghỉ ngơi","comps":"休息一下 (nghỉ một lát), 在家休息 (nghỉ ở nhà)","example":{"zh":"星期六你休息吗？","py":"Xīngqīliù nǐ xiūxi ma?","vi":"Thứ bảy bạn có nghỉ không?"}},{"stt":14,"hanzi":"忙","pinyin":"máng","hanviet":"Mang","pos":"Tính từ","meaning":"bận, bận rộn","comps":"很忙 (rất bận), 工作忙 (công việc bận)","example":{"zh":"他这几天很忙。","py":"Tā zhè jǐ tiān hěn máng.","vi":"Mấy hôm nay anh ấy rất bận."}},{"stt":15,"hanzi":"时间","pinyin":"shíjiān","hanviet":"Thời Gian","pos":"Danh từ","meaning":"thời gian","comps":"有时间 (có thời gian), 没有时间 (không có thời gian)","example":{"zh":"我没有时间休息。","py":"Wǒ méiyǒu shíjiān xiūxi.","vi":"Mình không có thời gian nghỉ."}}],"hanzi":[{"char":"生病","pinyin":"shēngbìng","hanviet":"Sinh Bệnh","chars":["生","病"],"story":"生 vẽ mầm cây nhú lên khỏi mặt đất, nghĩa gốc là \"mọc ra, sinh ra\". 病 có bộ 疒 (bệnh tật — vốn vẽ người nằm trên giường) + 丙 chỉ âm. 生病 nghĩa đen là \"sinh ra bệnh\", tức \"bị ốm\". Âm Hán Việt là \"Sinh Bệnh\"."},{"char":"每","pinyin":"měi","hanviet":"Mỗi","chars":["每"],"story":"每 có gốc chung với 母 (mẹ), chữ xưa vẽ người phụ nữ cài trâm trên đầu. Ngày nay chữ này không còn giữ nghĩa gốc, chỉ dùng làm đại từ \"mỗi, mọi\". Âm Hán Việt chính là \"Mỗi\" — trùng khít tiếng Việt nên rất dễ nhớ."},{"char":"早上","pinyin":"zǎoshang","hanviet":"Tảo Thượng","chars":["早","上"],"story":"早 gồm 日 (mặt trời) ở trên và 十 ở dưới, vẽ cảnh mặt trời vừa nhô lên khỏi ngọn cây, nên nghĩa là \"sớm\". 上 là chữ chỉ sự: một vạch nằm phía trên vạch mốc, nghĩa là \"trên\". 早上 = quãng thời gian đầu ngày, tức \"buổi sáng\"."},{"char":"跑步","pinyin":"pǎobù","hanviet":"Bào Bộ","chars":["跑","步"],"story":"跑 có bộ ⻊ (bàn chân) + 包 chỉ âm — động tác làm bằng chân, tức \"chạy\". 步 vẽ hai bàn chân nối tiếp nhau, nghĩa là \"bước đi\" (âm Hán Việt là \"Bộ\", như trong \"bộ hành\"). 跑步 = chạy từng bước, tức \"chạy bộ\"."},{"char":"起床","pinyin":"qǐchuáng","hanviet":"Khởi Sàng","chars":["起","床"],"story":"起 có bộ 走 (đi, chạy) nên nghĩa là \"đứng dậy, khởi lên\" — các em đã gặp trong 一起 ở Bài 1. 床 gồm bộ 广 (mái nhà) + 木 (gỗ), tức cái giường gỗ kê trong nhà. 起床 = rời khỏi giường, \"ngủ dậy\"."},{"char":"药","pinyin":"yào","hanviet":"Dược","chars":["药"],"story":"药 có bộ 艹 (cỏ cây) ở trên + 约 chỉ âm ở dưới. Thuốc thời xưa đều bào chế từ cây cỏ nên chữ này mang bộ thảo. Âm Hán Việt là \"Dược\", chính là chữ trong \"dược sĩ\", \"y dược\" — nhớ một lần là nhớ mãi."},{"char":"身体","pinyin":"shēntǐ","hanviet":"Thân Thể","chars":["身","体"],"story":"身 là chữ tượng hình vẽ dáng người có phần bụng nhô ra, nghĩa gốc là \"thân mình\". 体 = 亻(người) + 本 (gốc rễ) — cái gốc của con người chính là thân thể. 身体 vừa có nghĩa \"cơ thể\" vừa có nghĩa \"sức khoẻ\"."},{"char":"出院","pinyin":"chūyuàn","hanviet":"Xuất Viện","chars":["出","院"],"story":"出 vẽ bàn chân bước ra khỏi miệng hang, nghĩa là \"đi ra\". 院 gồm bộ 阝(khu đất có tường bao) + 完 chỉ âm, nghĩa là \"viện, khu nhà có tường\". 出院 = đi ra khỏi bệnh viện. Âm Hán Việt \"Xuất Viện\", dùng y hệt tiếng Việt."},{"char":"出","pinyin":"chū","hanviet":"Xuất","chars":["出"],"story":"出 là chữ tượng hình, vẽ một bàn chân bước lên khỏi miệng hang, nên nghĩa là \"ra, đi ra\". Âm Hán Việt là \"Xuất\", như trong \"xuất phát\", \"xuất hiện\". Ghép với 去 thành 出去 (đi ra ngoài), ghép với 来 thành 出来 (ra đây)."},{"char":"高","pinyin":"gāo","hanviet":"Cao","chars":["高"],"story":"高 là chữ tượng hình, vẽ một toà lầu nhiều tầng có mái nhọn ở trên, cửa ở dưới — hình ảnh của sự cao lớn. Âm Hán Việt là \"Cao\", trùng luôn với nghĩa tiếng Việt nên không cần học thêm gì."},{"char":"米","pinyin":"mǐ","hanviet":"Mễ","chars":["米"],"story":"米 là chữ tượng hình, vẽ những hạt gạo rơi quanh một cành lúa, nghĩa gốc là \"gạo\". Về sau chữ này được mượn làm đơn vị đo chiều dài \"mét\". Âm Hán Việt là \"Mễ\", như trong \"lương mễ\" (lương thực)."},{"char":"知道","pinyin":"zhīdào","hanviet":"Tri Đạo","chars":["知","道"],"story":"知 = 矢 (mũi tên) + 口 (miệng) — nói ra nhanh và trúng như mũi tên bay, tức là đã \"biết rõ\". 道 có bộ 辶 (bước đi) + 首 (cái đầu), nghĩa là \"con đường; đạo lý\". 知道 = biết được đường đi nước bước, tức \"biết\"."},{"char":"休息","pinyin":"xiūxi","hanviet":"Hưu Tức","chars":["休","息"],"story":"休 = 亻(người) + 木 (cây) — hình ảnh người tựa vào gốc cây, đúng là \"nghỉ ngơi\". 息 = 自 (cái mũi) + 心 (quả tim), nghĩa gốc là \"hơi thở\". 休息 = dừng lại thở cho lại sức. Âm Hán Việt \"Hưu Tức\", như trong \"về hưu\"."},{"char":"忙","pinyin":"máng","hanviet":"Mang","chars":["忙"],"story":"忙 bên trái là bộ 忄(dạng đứng của 心 — quả tim), bên phải là 亡 chỉ âm. Lòng dạ rối bời vì quá nhiều việc, nên chữ này nghĩa là \"bận\". Cứ thấy bộ 忄 là biết chữ đó nói về tâm trạng, cảm xúc."},{"char":"时间","pinyin":"shíjiān","hanviet":"Thời Gian","chars":["时","间"],"story":"时 = 日 (mặt trời) + 寸 (tấc) — người xưa đo thời gian bằng bóng nắng dài ngắn. 间 = 门 (cánh cửa) + 日 (mặt trời) — ánh nắng lọt qua khe cửa, nghĩa là \"khoảng, ở giữa\". 时间 = khoảng của thời gian. Âm Hán Việt \"Thời Gian\"."}],"grammar":[{"title":"Câu hỏi với 是不是","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>是不是</b><small>có phải…không</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>谓语</b><small>vị ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi để xác nhận phỏng đoán</p><ul><li><span class=\"zh\">是不是</span> dùng khi người hỏi <b>đã đoán trước</b> câu trả lời và chỉ muốn xác nhận lại — nhẹ nhàng hơn câu hỏi bằng <span class=\"zh\">吗</span>.</li><li>Vị trí linh hoạt: đứng <b>trước vị ngữ</b> (<span class=\"zh\">你是不是喜欢运动？</span>), đứng <b>đầu câu</b> hoặc tách ra <b>cuối câu</b> (<span class=\"zh\">你喜欢运动，是不是？</span>).</li><li>Trả lời: đúng thì nói <span class=\"zh\">是</span> / <span class=\"zh\">是啊</span>, không đúng thì nói <span class=\"zh\">不是</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">你是不是喜欢运动？</span>　·　<span class=\"zh\">你喜欢运动，是不是？</span></p>","note":"<b>Lưu ý:</b> Câu đã có <span class=\"zh\">是不是</span> thì <b>không thêm</b> <span class=\"zh\">吗</span> ở cuối — giống hệt quy tắc của <span class=\"zh\">要不要</span> ở Bài 1.","examples":[{"zh":"你是不是喜欢运动？","py":"Nǐ shì bu shì xǐhuan yùndòng?","vi":"Có phải bạn thích thể thao không?"}],"exercises":[]},{"title":"Đại từ 每","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>每</b><small>mỗi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>danh từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>都 + 动词</b><small>đều + động từ</small></span></div>","summary":"<p class=\"gr-lead\">Mỗi, mọi — thường đi với 都</p><ul><li><span class=\"zh\">每</span> phải đứng trước <b>lượng từ</b> rồi mới đến danh từ: <span class=\"zh\">每个人</span>, <span class=\"zh\">每个星期</span>.</li><li>Riêng <span class=\"zh\">天、年、分钟</span> tự thân đã là lượng từ nên nói thẳng <span class=\"zh\">每天</span>, <span class=\"zh\">每年</span>.</li><li>Vế sau thường có <span class=\"zh\">都</span> để nhấn ý \"lần nào cũng vậy\": <span class=\"zh\">他每天回来都很累。</span></li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">我每天早上都要出去跑步。</span>　·　<span class=\"zh\">他每天回来都很累。</span></p>","note":"<b>Lưu ý:</b> Không nói <span class=\"zh\">每个天</span> hay <span class=\"zh\">每个年</span> — hai chữ này đã kiêm luôn vai trò lượng từ.","examples":[{"zh":"汤姆每年都去中国旅游。","py":"Tāngmǔ měi nián dōu qù Zhōngguó lǚyóu.","vi":"Năm nào Tom cũng đi Trung Quốc du lịch."},{"zh":"你每个星期六都运动吗？","py":"Nǐ měi ge xīngqīliù dōu yùndòng ma?","vi":"Thứ bảy nào bạn cũng tập thể thao à?"},{"zh":"我每天六点起床。","py":"Wǒ měi tiān liù diǎn qǐchuáng.","vi":"Mỗi ngày mình dậy lúc sáu giờ."}],"exercises":[]},{"title":"Đại từ nghi vấn 多","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>多</b><small>bao nhiêu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi mức độ bao nhiêu</p><ul><li>Bài 1 dạy <span class=\"zh\">多</span> là <b>số ước lượng</b> (<span class=\"zh\">三点多</span>); ở đây <span class=\"zh\">多</span> làm <b>từ để hỏi</b>, đứng ngay trước tính từ.</li><li>Hay gặp nhất: <span class=\"zh\">多大</span> (bao nhiêu tuổi), <span class=\"zh\">多高</span> (cao bao nhiêu), <span class=\"zh\">多远</span> (bao xa), <span class=\"zh\">多长</span> (dài bao nhiêu).</li><li>Trả lời bằng con số, có thể kèm <span class=\"zh\">多</span> hoặc <span class=\"zh\">几</span> cho ước lượng: <span class=\"zh\">二十多岁</span>, <span class=\"zh\">一米八几</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">他多大？</span> bao nhiêu tuổi　·　<span class=\"zh\">他多高？</span> cao bao nhiêu</p>","note":"<b>Lưu ý:</b> Chỉ hỏi bằng tính từ <b>vế lớn</b> của cặp đối lập: nói <span class=\"zh\">多高</span> chứ không nói <span class=\"zh\">多矮</span>, nói <span class=\"zh\">多大</span> chứ không nói <span class=\"zh\">多小</span>.","examples":[{"zh":"多大？——……岁","py":"duō dà? —— …… suì","vi":"Hỏi tuổi → trả lời: số + 岁 (tuổi)"},{"zh":"多高？——……米……","py":"duō gāo? —— …… mǐ ……","vi":"Hỏi chiều cao → trả lời: … 米 … (mét)"},{"zh":"多重？——……公斤","py":"duō zhòng? —— …… gōngjīn","vi":"Hỏi cân nặng → trả lời: số + 公斤 (kg)"},{"zh":"多远？——……米 / 公里","py":"duō yuǎn? —— …… mǐ / gōnglǐ","vi":"Hỏi khoảng cách → trả lời: số + 米 (m) / 公里 (km)"},{"zh":"多久 / 多长时间？——……","py":"duō jiǔ / duō cháng shíjiān? —— ……","vi":"Hỏi bao lâu → trả lời: khoảng thời gian (……年 / 个月 / 天 / 个小时 / 分钟)"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · HỘI THOẠI","titleVi":"Ở sân vận động — hỏi thói quen tập","lines":[{"speaker":"甲","name":"Bạn A","zh":"你很少生病，是不是喜欢运动？","py":"Nǐ hěn shǎo shēngbìng, shì bu shì xǐhuan yùndòng?","vi":"Bạn ít khi ốm, có phải vì thích thể thao không?"},{"speaker":"乙","name":"Bạn B","zh":"是啊，我每天早上都要出去跑步。","py":"Shì a, wǒ měi tiān zǎoshang dōu yào chūqù pǎobù.","vi":"Đúng vậy, sáng nào mình cũng ra ngoài chạy bộ."},{"speaker":"甲","name":"Bạn A","zh":"你每天几点起床？","py":"Nǐ měi tiān jǐ diǎn qǐchuáng?","vi":"Mỗi ngày bạn dậy lúc mấy giờ?"},{"speaker":"乙","name":"Bạn B","zh":"我每天六点起床。","py":"Wǒ měi tiān liù diǎn qǐchuáng.","vi":"Mỗi ngày mình dậy lúc sáu giờ."}]},{"titleZh":"课文二 · HỘI THOẠI","titleVi":"Ở bệnh viện — hỏi thăm người ốm","lines":[{"speaker":"甲","name":"Bạn A","zh":"吃药了吗？现在身体怎么样？","py":"Chī yào le ma? Xiànzài shēntǐ zěnmeyàng?","vi":"Uống thuốc chưa? Giờ sức khoẻ thế nào rồi?"},{"speaker":"乙","name":"Bạn B","zh":"吃了。现在好多了。","py":"Chī le. Xiànzài hǎo duō le.","vi":"Uống rồi. Giờ đỡ nhiều rồi."},{"speaker":"甲","name":"Bạn A","zh":"什么时候能出院？","py":"Shénme shíhou néng chūyuàn?","vi":"Khi nào thì được ra viện?"},{"speaker":"乙","name":"Bạn B","zh":"医生说下个星期。","py":"Yīshēng shuō xià ge xīngqī.","vi":"Bác sĩ bảo tuần sau."}]},{"titleZh":"课文三 · HỘI THOẠI","titleVi":"Ở sân trường — nói về bạn David","lines":[{"speaker":"甲","name":"Bạn A","zh":"大卫今年多大？","py":"Dàwèi jīnnián duō dà?","vi":"Năm nay David bao nhiêu tuổi?"},{"speaker":"乙","name":"Bạn B","zh":"二十多岁。","py":"Èrshí duō suì.","vi":"Hơn hai mươi tuổi."},{"speaker":"甲","name":"Bạn A","zh":"他多高？","py":"Tā duō gāo?","vi":"Cậu ấy cao bao nhiêu?"},{"speaker":"乙","name":"Bạn B","zh":"一米八几。","py":"Yī mǐ bā jǐ.","vi":"Một mét tám mấy."},{"speaker":"甲","name":"Bạn A","zh":"你怎么知道这么多啊？","py":"Nǐ zěnme zhīdào zhème duō a?","vi":"Sao bạn biết nhiều thế?"},{"speaker":"乙","name":"Bạn B","zh":"他是我同学。","py":"Tā shì wǒ tóngxué.","vi":"Cậu ấy là bạn cùng lớp mình mà."}]},{"titleZh":"课文四 · HỘI THOẠI","titleVi":"Trong phòng — nói về thầy Trương","lines":[{"speaker":"甲","name":"Bạn A","zh":"张老师星期六也不休息啊？","py":"Zhāng lǎoshī xīngqīliù yě bù xiūxi a?","vi":"Thầy Trương thứ bảy cũng không nghỉ à?"},{"speaker":"乙","name":"Bạn B","zh":"是啊，他这几天很忙，没有时间休息。","py":"Shì a, tā zhè jǐ tiān hěn máng, méiyǒu shíjiān xiūxi.","vi":"Đúng vậy, mấy hôm nay thầy bận lắm, không có thời gian nghỉ."},{"speaker":"甲","name":"Bạn A","zh":"那会很累吧？","py":"Nà huì hěn lèi ba?","vi":"Thế thì chắc mệt lắm nhỉ?"},{"speaker":"乙","name":"Bạn B","zh":"他每天回来都很累。","py":"Tā měi tiān huílái dōu hěn lèi.","vi":"Ngày nào về thầy cũng đều rất mệt."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"三音节词语的重音","grpVi":"Trọng âm của từ ngữ có ba âm tiết","zh":"中轻重格式","py":"zhōng qīng zhòng géshì","tag":"Trọng âm","vi":"Cấu trúc \"nhấn vừa + đọc nhẹ + nhấn mạnh\"","listZh":"(1) 中轻重格式","listVi":"Cấu trúc \"nhấn vừa + đọc nhẹ + nhấn mạnh\" — đa số từ ba âm tiết","descZh":"大多数三音节词属于\"中轻重\"格式，即第一个音节为中音，音长次长；第二个音节为轻音，音长最短；第三个音节为重音，音长最长。","descVi":"Đa số từ ngữ có ba âm tiết thuộc cấu trúc \"nhấn vừa + đọc nhẹ + nhấn mạnh\", tức âm tiết thứ nhất được đọc nhấn giọng và kéo dài vừa phải, âm tiết thứ hai được phát âm nhẹ và nhanh nhất, còn âm tiết thứ ba được đọc nhấn mạnh và kéo dài nhất.","pat":[{"l":"Âm tiết 1","s":"nhấn vừa"},{"l":"Âm tiết 2","s":"nhẹ · ngắn nhất","lt":true},{"l":"Âm tiết 3","s":"mạnh · dài nhất","st":true}],"tip":"Âm tiết giữa vẫn giữ thanh điệu nhưng <b>lướt nhanh</b>; dồn lực và kéo dài <b>âm tiết cuối</b>.","rows":[[{"hz":"收音机","syl":["shōu","yīn","jī"],"st":2,"lt":1,"vi":"đài radio"},{"hz":"新加坡","syl":["Xīn","jiā","pō"],"st":2,"lt":1,"vi":"Singapore"},{"hz":"好莱坞","syl":["Hǎo","lái","wù"],"st":2,"lt":1,"vi":"Hollywood"},{"hz":"电视剧","syl":["diàn","shì","jù"],"st":2,"lt":1,"vi":"phim truyền hình"}]]},{"id":"pa-02","grp":"三音节词语的重音","grpVi":"Trọng âm của từ ngữ có ba âm tiết","zh":"中重轻格式","py":"zhōng zhòng qīng géshì","tag":"Trọng âm","vi":"Cấu trúc \"nhấn vừa + nhấn mạnh + đọc nhẹ\"","listZh":"(2) 中重轻格式","listVi":"Cấu trúc \"nhấn vừa + nhấn mạnh + đọc nhẹ\" — số lượng không nhiều","descZh":"三音节词语属于\"中重轻\"格式的数量不多，即第二个音节为重音，音长最长；第一个音节为中音，音长中长；第三个音节为轻音，音长最短。","descVi":"Từ ngữ có ba âm tiết thuộc cấu trúc \"nhấn vừa + nhấn mạnh + đọc nhẹ\" có số lượng không nhiều. Trong cấu trúc này, âm tiết thứ hai được đọc nhấn mạnh và kéo dài nhất, âm tiết thứ nhất được đọc nhấn giọng và kéo dài vừa phải, còn âm tiết thứ ba được phát âm nhẹ và nhanh nhất.","pat":[{"l":"Âm tiết 1","s":"nhấn vừa"},{"l":"Âm tiết 2","s":"mạnh · dài nhất","st":true},{"l":"Âm tiết 3","s":"nhẹ · ngắn nhất","lt":true}],"tip":"Âm tiết cuối là <b>thanh nhẹ</b> (pinyin không dấu thanh) — đọc lướt ngay sau âm tiết nhấn.","rows":[[{"hz":"胡萝卜","syl":["hú","luó","bo"],"st":1,"lt":2,"vi":"cà rốt"},{"hz":"没关系","syl":["méi","guān","xi"],"st":1,"lt":2,"vi":"không sao"},{"hz":"老狐狸","syl":["lǎo","hú","li"],"sp":[0],"st":1,"lt":2,"vi":"cáo già"},{"hz":"毛孩子","syl":["máo","hái","zi"],"st":1,"lt":2,"vi":"nhóc con"}]]},{"id":"pa-03","grp":"三音节词语的重音","grpVi":"Trọng âm của từ ngữ có ba âm tiết","zh":"重轻轻格式","py":"zhòng qīng qīng géshì","tag":"Trọng âm","vi":"Cấu trúc \"nhấn mạnh + đọc nhẹ + đọc nhẹ\"","listZh":"(3) 重轻轻格式","listVi":"Cấu trúc \"nhấn mạnh + đọc nhẹ + đọc nhẹ\" — rất ít, đa số là khẩu ngữ","descZh":"三音节词语属于\"重轻轻\"格式的很少，多为口语词，它的第一个音节为重音，第二、三个音节都为轻音。","descVi":"Từ ngữ có ba âm tiết thuộc cấu trúc \"nhấn mạnh + đọc nhẹ + đọc nhẹ\" có số lượng rất ít, thường là các từ dùng trong văn nói. Ở cấu trúc này, âm tiết thứ nhất được đọc nhấn mạnh còn âm tiết thứ hai và thứ ba được phát âm nhẹ.","pat":[{"l":"Âm tiết 1","s":"nhấn mạnh","st":true},{"l":"Âm tiết 2","s":"đọc nhẹ","lt":true},{"l":"Âm tiết 3","s":"đọc nhẹ","lt":true}],"tip":"Nhấn rõ <b>âm tiết đầu</b>, hai âm tiết sau đều là thanh nhẹ, đọc liền một hơi.","rows":[[{"hz":"什么的","syl":["shén","me","de"],"st":0,"lt":[1,2],"vi":"vân vân"},{"hz":"怪不得","syl":["guài","bu","de"],"st":0,"lt":[1,2],"vi":"thảo nào"},{"hz":"姑娘家","syl":["gū","niang","jia"],"st":0,"lt":[1,2],"vi":"con gái"},{"hz":"好着呢","syl":["hǎo","zhe","ne"],"sp":true,"st":0,"lt":[1,2],"vi":"tốt lắm"}]]}]},{"id":"k2v2-b03","courseId":"k2v2","order":3,"title":"Cái màu đỏ ở bên trái là của tôi","titleZh":"左边那个红色的是我的。","titlePy":"zuǒbian nàge hóngsè de shì wǒ de","vocab":[{"stt":1,"hanzi":"手表","pinyin":"shǒubiǎo","hanviet":"Thủ Biểu","pos":"Danh từ","meaning":"đồng hồ đeo tay","comps":"一块手表 (một chiếc đồng hồ), 买手表 (mua đồng hồ)","example":{"zh":"这块手表是你的吗？","py":"Zhè kuài shǒubiǎo shì nǐ de ma?","vi":"Chiếc đồng hồ này là của bạn à?"}},{"stt":2,"hanzi":"千","pinyin":"qiān","hanviet":"Thiên","pos":"Số từ","meaning":"nghìn, ngàn","comps":"三千 (ba nghìn), 一千块 (một nghìn tệ)","example":{"zh":"这块手表三千多块。","py":"Zhè kuài shǒubiǎo sān qiān duō kuài.","vi":"Chiếc đồng hồ này hơn ba nghìn tệ."}},{"stt":3,"hanzi":"报纸","pinyin":"bàozhǐ","hanviet":"Báo Chỉ","pos":"Danh từ","meaning":"báo, tờ báo","comps":"看报纸 (đọc báo), 今天的报纸 (báo hôm nay)","example":{"zh":"这是今天的报纸。","py":"Zhè shì jīntiān de bàozhǐ.","vi":"Đây là báo hôm nay."}},{"stt":4,"hanzi":"送","pinyin":"sòng","hanviet":"Tống","pos":"Động từ","meaning":"giao, đưa; tặng, tiễn","comps":"送报纸 (giao báo), 送牛奶 (giao sữa)","example":{"zh":"他每天早上送报纸。","py":"Tā měi tiān zǎoshang sòng bàozhǐ.","vi":"Sáng nào anh ấy cũng giao báo."}},{"stt":5,"hanzi":"一下","pinyin":"yíxià","hanviet":"Nhất Hạ","pos":"Số lượng từ","meaning":"một chút, một lát","comps":"看一下 (xem một chút), 等一下 (đợi một lát)","example":{"zh":"我看一下。","py":"Wǒ kàn yíxià.","vi":"Để mình xem một chút."}},{"stt":6,"hanzi":"牛奶","pinyin":"niúnǎi","hanviet":"Ngưu Nãi","pos":"Danh từ","meaning":"sữa bò, sữa tươi","comps":"喝牛奶 (uống sữa), 送牛奶 (giao sữa)","example":{"zh":"我每天早上喝牛奶。","py":"Wǒ měi tiān zǎoshang hē niúnǎi.","vi":"Sáng nào mình cũng uống sữa."}},{"stt":7,"hanzi":"房间","pinyin":"fángjiān","hanviet":"Phòng Gian","pos":"Danh từ","meaning":"căn phòng, phòng","comps":"我的房间 (phòng của tôi), 这个房间 (căn phòng này)","example":{"zh":"这是谁的房间？","py":"Zhè shì shéi de fángjiān?","vi":"Đây là phòng của ai thế?"}},{"stt":8,"hanzi":"丈夫","pinyin":"zhàngfu","hanviet":"Trượng Phu","pos":"Danh từ","meaning":"chồng","comps":"我丈夫 (chồng tôi), 她丈夫 (chồng cô ấy)","example":{"zh":"这是我和我丈夫的房间。","py":"Zhè shì wǒ hé wǒ zhàngfu de fángjiān.","vi":"Đây là phòng của mình và chồng."}},{"stt":9,"hanzi":"旁边","pinyin":"pángbiān","hanviet":"Bàng Biên","pos":"Danh từ","meaning":"bên cạnh, phía bên","comps":"旁边的 (cái bên cạnh), 在旁边 (ở bên cạnh)","example":{"zh":"旁边那个房间很小。","py":"Pángbiān nàge fángjiān hěn xiǎo.","vi":"Căn phòng bên cạnh rất nhỏ."}},{"stt":10,"hanzi":"真","pinyin":"zhēn","hanviet":"Chân","pos":"Phó từ","meaning":"thật là, quả là","comps":"真漂亮 (đẹp thật), 真好 (tốt thật)","example":{"zh":"你的房间真漂亮！","py":"Nǐ de fángjiān zhēn piàoliang!","vi":"Phòng của bạn đẹp thật đấy!"}},{"stt":11,"hanzi":"粉色","pinyin":"fěnsè","hanviet":"Phấn Sắc","pos":"Danh từ","meaning":"màu hồng","comps":"粉色的 (cái màu hồng), 喜欢粉色 (thích màu hồng)","example":{"zh":"她最喜欢粉色。","py":"Tā zuì xǐhuan fěnsè.","vi":"Cô bé thích màu hồng nhất."}},{"stt":12,"hanzi":"粉","pinyin":"fěn","hanviet":"Phấn","pos":"Danh từ","meaning":"bột, phấn; hồng","comps":"面粉 (bột mì), 粉红色 (màu hồng phấn)","example":{"zh":"我喜欢粉红色。","py":"Wǒ xǐhuan fěnhóngsè.","vi":"Mình thích màu hồng phấn."}},{"stt":13,"hanzi":"颜色","pinyin":"yánsè","hanviet":"Nhan Sắc","pos":"Danh từ","meaning":"màu, màu sắc","comps":"什么颜色 (màu gì), 喜欢的颜色 (màu yêu thích)","example":{"zh":"你最喜欢什么颜色？","py":"Nǐ zuì xǐhuan shénme yánsè?","vi":"Bạn thích màu gì nhất?"}},{"stt":14,"hanzi":"左边","pinyin":"zuǒbian","hanviet":"Tả Biên","pos":"Danh từ","meaning":"bên trái, phía trái","comps":"左边的 (cái bên trái), 在左边 (ở bên trái)","example":{"zh":"左边那个是我的。","py":"Zuǒbian nàge shì wǒ de.","vi":"Cái bên trái là của mình."}},{"stt":15,"hanzi":"红色","pinyin":"hóngsè","hanviet":"Hồng Sắc","pos":"Danh từ","meaning":"màu đỏ","comps":"红色的 (cái màu đỏ), 大红色 (đỏ tươi)","example":{"zh":"红色的杯子是我的。","py":"Hóngsè de bēizi shì wǒ de.","vi":"Cái cốc màu đỏ là của mình."}}],"hanzi":[{"char":"手表","pinyin":"shǒubiǎo","hanviet":"Thủ Biểu","chars":["手","表"],"story":"手 là chữ tượng hình vẽ bàn tay với năm ngón xoè ra. 表 vốn nghĩa \"bên ngoài, biểu lộ\" — âm Hán Việt là \"Biểu\", như trong \"biểu hiện\"; về sau chỉ cái đồng hồ đeo lộ ra ngoài cổ tay. 手表 = đồng hồ đeo ở tay."},{"char":"千","pinyin":"qiān","hanviet":"Thiên","chars":["千"],"story":"千 gồm một nét phẩy đặt trên chữ 十 (mười) — người xưa thêm một vạch để đánh dấu bậc số lớn hơn hẳn. Âm Hán Việt là \"Thiên\", chính là chữ trong \"thiên niên kỷ\" (nghìn năm)."},{"char":"报纸","pinyin":"bàozhǐ","hanviet":"Báo Chỉ","chars":["报","纸"],"story":"报 nghĩa gốc là \"báo tin, thông báo\", âm Hán Việt đúng là \"Báo\". 纸 có bộ 纟(sợi tơ) + 氏 chỉ âm, vì giấy xưa làm từ sợi. 报纸 = tờ giấy đưa tin, tức \"tờ báo\". Thấy bộ 纟 là biết chữ liên quan đến sợi, vải."},{"char":"送","pinyin":"sòng","hanviet":"Tống","chars":["送"],"story":"送 có bộ 辶 (bước đi) — hành động mang cái gì đó đi tới nơi khác. Vì vậy chữ này vừa nghĩa \"giao, đưa tới\", vừa nghĩa \"tặng\" và \"tiễn\". Âm Hán Việt là \"Tống\", như trong \"tống tiễn\"."},{"char":"一下","pinyin":"yíxià","hanviet":"Nhất Hạ","chars":["一","下"],"story":"一 là \"một\". 下 là chữ chỉ sự: một vạch nằm phía dưới vạch mốc, nghĩa là \"dưới\". Ghép lại 一下 nghĩa đen là \"một cái, một lượt\", đặt sau động từ để nói việc làm nhẹ nhàng, ngắn gọn."},{"char":"牛奶","pinyin":"niúnǎi","hanviet":"Ngưu Nãi","chars":["牛","奶"],"story":"牛 là chữ tượng hình vẽ đầu con bò nhìn từ phía trước, thấy rõ hai cái sừng nhô lên. 奶 = 女 (phụ nữ) + 乃 chỉ âm, nghĩa là \"sữa\". 牛奶 = sữa của con bò. Âm Hán Việt \"Ngưu Nãi\"."},{"char":"房间","pinyin":"fángjiān","hanviet":"Phòng Gian","chars":["房","间"],"story":"房 có bộ 户 (cánh cửa một cánh) + 方 chỉ âm, nghĩa là \"gian nhà, buồng\". 间 = 门 (cửa) + 日 (mặt trời) — khoảng ở giữa, các em đã gặp trong 时间 ở Bài 2. 房间 = gian buồng, tức \"căn phòng\"."},{"char":"丈夫","pinyin":"zhàngfu","hanviet":"Trượng Phu","chars":["丈","夫"],"story":"丈 vốn là đơn vị đo chiều dài (một trượng), dùng chỉ người đàn ông cao lớn. 夫 vẽ người trưởng thành cài trâm trên đầu — đàn ông đã đến tuổi. 丈夫 nghĩa gốc là \"người đàn ông trưởng thành\", nay là \"chồng\". Âm Hán Việt \"Trượng Phu\"."},{"char":"旁边","pinyin":"pángbiān","hanviet":"Bàng Biên","chars":["旁","边"],"story":"旁 nghĩa là \"bên, phía bên\", âm Hán Việt là \"Bàng\" như trong \"bàng quan\" (đứng bên ngoài mà nhìn). 边 có bộ 辶 (bước đi), nghĩa là \"bên, mép, rìa\". 旁边 = phía bên cạnh."},{"char":"真","pinyin":"zhēn","hanviet":"Chân","chars":["真"],"story":"真 chữ xưa vẽ cảnh dùng muôi múc thật đầy vào vật đựng, ý là \"đầy đủ, không giả dối\" → \"thật, chân thật\". Âm Hán Việt là \"Chân\", như trong \"chân thành\", \"chân lý\"."},{"char":"粉色","pinyin":"fěnsè","hanviet":"Phấn Sắc","chars":["粉","色"],"story":"粉 = 米 (hạt gạo) + 分 (chia nhỏ) — gạo giã nhỏ thì thành bột. 色 nghĩa là \"màu sắc\". Bột gạo, bột phấn có sắc hồng nhạt nên người Trung Quốc gọi màu hồng là 粉色."},{"char":"粉","pinyin":"fěn","hanviet":"Phấn","chars":["粉"],"story":"粉 gồm bộ 米 (hạt gạo — các em vừa học ở Bài 2) và 分 (chia, tách nhỏ). Gạo được giã và chia nhỏ ra thì thành bột, đó là nghĩa gốc \"bột, phấn\". Âm Hán Việt là \"Phấn\", như trong \"phấn son\"."},{"char":"颜色","pinyin":"yánsè","hanviet":"Nhan Sắc","chars":["颜","色"],"story":"颜 có bộ 页 (cái đầu, khuôn mặt) nên nghĩa gốc là \"sắc mặt, dung nhan\" — âm Hán Việt là \"Nhan\". 色 chữ xưa vẽ nét mặt của người, nghĩa là \"sắc thái, màu\". 颜色 = màu sắc. Âm Hán Việt \"Nhan Sắc\"."},{"char":"左边","pinyin":"zuǒbian","hanviet":"Tả Biên","chars":["左","边"],"story":"左 vẽ bàn tay trái kèm chữ 工, nghĩa là \"bên trái\" — âm Hán Việt là \"Tả\", như trong \"tả ngạn\". 边 nghĩa là \"bên, phía\". 左边 = phía bên trái; chữ đối lại là 右边 (bên phải)."},{"char":"红色","pinyin":"hóngsè","hanviet":"Hồng Sắc","chars":["红","色"],"story":"红 có bộ 纟(sợi tơ) + 工 chỉ âm — vải lụa nhuộm đỏ, nên nghĩa là \"màu đỏ\". Âm Hán Việt là \"Hồng\". 色 là \"màu\". 红色 là màu được coi là may mắn nhất trong văn hoá Trung Hoa."}],"grammar":[{"title":"Cụm từ chữ \"的\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>定语</b><small>phần bổ nghĩa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>trợ từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(名词)</b><small>danh từ — lược bỏ</small></span></div>","summary":"<p class=\"gr-lead\">Lược danh từ, chỉ giữ 的</p><ul><li>Khi người nghe đã biết đang nói về cái gì thì <b>lược bỏ danh từ</b> phía sau <span class=\"zh\">的</span>: <span class=\"zh\">红色的杯子</span> → <span class=\"zh\">红色的</span>.</li><li>Phần đứng trước <span class=\"zh\">的</span> có thể là đại từ (<span class=\"zh\">我的</span>), tính từ (<span class=\"zh\">小的</span>) hoặc cả một cụm động từ (<span class=\"zh\">送牛奶的</span>).</li><li>Cụm <span class=\"zh\">动词 + 的</span> còn dùng để gọi <b>người làm nghề đó</b>: <span class=\"zh\">送报纸的</span> = người giao báo.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">左边那个红色的杯子</span> → <span class=\"zh\">左边那个红色的</span></p>","note":"<b>Lưu ý:</b> Đừng dịch máy móc <span class=\"zh\">的</span> là \"của\" — <span class=\"zh\">小的</span> là \"cái nhỏ\", <span class=\"zh\">送牛奶的</span> là \"người giao sữa\".","examples":[{"zh":"这本书不是我的。","py":"Zhè běn shū bú shì wǒ de.","vi":"Cuốn sách này không phải của mình."},{"zh":"这个杯子是昨天买的。","py":"Zhège bēizi shì zuótiān mǎi de.","vi":"Cái cốc này là (cái) mua hôm qua."},{"zh":"这块手表是你的吗？","py":"Zhè kuài shǒubiǎo shì nǐ de ma?","vi":"Chiếc đồng hồ này là của bạn à?"}],"exercises":[]},{"title":"Cấu trúc động từ + 一下","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>一下</b><small>một chút</small></span></div>","summary":"<p class=\"gr-lead\">Làm gì đó một chút thôi</p><ul><li><span class=\"zh\">一下</span> đặt <b>ngay sau động từ</b>, nghĩa là làm việc đó <b>trong chốc lát</b>, thử một cái.</li><li>Tác dụng lớn nhất là làm câu <b>nhẹ nhàng, lịch sự</b> hơn: <span class=\"zh\">你看一下。</span> dễ nghe hơn hẳn <span class=\"zh\">你看。</span></li><li>Dùng được với hầu hết động từ ngắn: <span class=\"zh\">看一下、听一下、等一下、休息一下</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">我看一下。</span>　·　<span class=\"zh\">你听一下。</span>　·　<span class=\"zh\">等一下。</span></p>","note":"<b>Lưu ý:</b> Nhớ biến điệu: <span class=\"zh\">下</span> là thanh 4 nên <span class=\"zh\">一</span> đọc thành thanh 2 — <b>yíxià</b>, không đọc yīxià.","examples":[{"zh":"我看一下。","py":"Wǒ kàn yíxià.","vi":"Để mình xem một chút."},{"zh":"你休息一下吧。","py":"Nǐ xiūxi yíxià ba.","vi":"Bạn nghỉ một lát đi."},{"zh":"我问一下老师。","py":"Wǒ wèn yíxià lǎoshī.","vi":"Để mình hỏi thầy cô một chút."}],"exercises":[]},{"title":"Phó từ 真","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>真</b><small>thật là</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span></div>","summary":"<p class=\"gr-lead\">Cảm thán: thật là, quá là</p><ul><li><span class=\"zh\">真</span> đứng trước tính từ để <b>cảm thán</b>, bộc lộ cảm xúc người nói — cuối câu thường có dấu <b>!</b></li><li>Khác <span class=\"zh\">很</span> ở chỗ: <span class=\"zh\">很</span> chỉ <b>mô tả</b> mức độ, còn <span class=\"zh\">真</span> mang <b>cảm xúc</b> ngạc nhiên, khen ngợi.</li><li>Cũng dùng được trước động từ chỉ tâm lý: <span class=\"zh\">我真喜欢这个颜色。</span></li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">你女儿的房间真漂亮！</span>　·　So sánh: <span class=\"zh\">房间很漂亮。</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">真</span> chỉ dùng cho câu <b>cảm thán</b>, <b>không dùng</b> trong câu hỏi — không nói <span class=\"zh\">房间真漂亮吗？</span>","examples":[{"zh":"你真好！","py":"Nǐ zhēn hǎo!","vi":"Bạn tốt thật đấy!"},{"zh":"今天天气真好！","py":"Jīntiān tiānqì zhēn hǎo!","vi":"Hôm nay trời đẹp thật!"},{"zh":"你女儿的房间真漂亮！","py":"Nǐ nǚ'ér de fángjiān zhēn piàoliang!","vi":"Phòng con gái chị đẹp thật đấy!"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · HỘI THOẠI","titleVi":"Trong phòng — hỏi về chiếc đồng hồ","lines":[{"speaker":"甲","name":"Bạn A","zh":"这块手表是你的吗？","py":"Zhè kuài shǒubiǎo shì nǐ de ma?","vi":"Chiếc đồng hồ này là của bạn à?"},{"speaker":"乙","name":"Bạn B","zh":"不是我的。是我爸爸的。","py":"Bú shì wǒ de. Shì wǒ bàba de.","vi":"Không phải của mình. Của bố mình đấy."},{"speaker":"甲","name":"Bạn A","zh":"多少钱买的？","py":"Duōshao qián mǎi de?","vi":"Mua bao nhiêu tiền vậy?"},{"speaker":"乙","name":"Bạn B","zh":"三千多块。","py":"Sān qiān duō kuài.","vi":"Hơn ba nghìn tệ."}]},{"titleZh":"课文二 · HỘI THOẠI","titleVi":"Ở nhà — nghe tiếng người giao hàng","lines":[{"speaker":"甲","name":"Bạn A","zh":"这是今天早上的报纸吗？","py":"Zhè shì jīntiān zǎoshang de bàozhǐ ma?","vi":"Đây là báo sáng nay à?"},{"speaker":"乙","name":"Bạn B","zh":"不是，是昨天的。","py":"Bú shì, shì zuótiān de.","vi":"Không phải, báo hôm qua đấy."},{"speaker":"甲","name":"Bạn A","zh":"你听，是不是送报纸的来了？","py":"Nǐ tīng, shì bu shì sòng bàozhǐ de lái le?","vi":"Bạn nghe xem, có phải người giao báo đến rồi không?"},{"speaker":"乙","name":"Bạn B","zh":"我看一下。不是，是送牛奶的。","py":"Wǒ kàn yíxià. Bú shì, shì sòng niúnǎi de.","vi":"Để mình xem một chút. Không phải, là người giao sữa."}]},{"titleZh":"课文三 · HỘI THOẠI","titleVi":"Ở nhà — chủ nhà giới thiệu phòng","lines":[{"speaker":"甲","name":"Bạn A","zh":"这是谁的房间？","py":"Zhè shì shéi de fángjiān?","vi":"Đây là phòng của ai thế?"},{"speaker":"乙","name":"Bạn B","zh":"这是我和我丈夫的，旁边那个小的房间是我女儿的。","py":"Zhè shì wǒ hé wǒ zhàngfu de, pángbiān nàge xiǎo de fángjiān shì wǒ nǚ'ér de.","vi":"Đây là phòng của mình và chồng, căn phòng nhỏ bên cạnh là của con gái mình."},{"speaker":"甲","name":"Bạn A","zh":"你女儿的房间真漂亮！都是粉色的。","py":"Nǐ nǚ'ér de fángjiān zhēn piàoliang! Dōu shì fěnsè de.","vi":"Phòng con gái chị đẹp thật đấy! Toàn màu hồng."},{"speaker":"乙","name":"Bạn B","zh":"是啊！粉色是我女儿最喜欢的颜色。","py":"Shì a! Fěnsè shì wǒ nǚ'ér zuì xǐhuan de yánsè.","vi":"Đúng vậy! Hồng là màu con gái mình thích nhất."}]},{"titleZh":"课文四 · HỘI THOẠI","titleVi":"Ở văn phòng — tìm chiếc cốc","lines":[{"speaker":"甲","name":"Bạn A","zh":"你看见我的杯子了吗？","py":"Nǐ kànjiàn wǒ de bēizi le ma?","vi":"Bạn có thấy cái cốc của mình không?"},{"speaker":"乙","name":"Bạn B","zh":"这里有几个杯子，哪个是你的？","py":"Zhèlǐ yǒu jǐ ge bēizi, nǎge shì nǐ de?","vi":"Ở đây có mấy cái cốc, cái nào là của bạn?"},{"speaker":"甲","name":"Bạn A","zh":"左边那个红色的是我的。","py":"Zuǒbian nàge hóngsè de shì wǒ de.","vi":"Cái màu đỏ bên trái là của mình."},{"speaker":"乙","name":"Bạn B","zh":"给你。","py":"Gěi nǐ.","vi":"Đây, của bạn đây."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"四音节词语的重音","grpVi":"Trọng âm của từ ngữ có bốn âm tiết","zh":"不含轻声音节的四音节词语","py":"","tag":"Trọng âm","vi":"Từ ngữ có bốn âm tiết không mang thanh nhẹ","listZh":"(1) 不含轻声音节的四音节词语","listVi":"Từ ngữ có bốn âm tiết không mang thanh nhẹ — trọng âm ở âm tiết thứ tư","descZh":"四音节词语的重音一般在第四个音节。","descVi":"Trong từ ngữ có bốn âm tiết, trọng âm thường rơi vào âm tiết thứ tư.","pat":[{"l":"Âm tiết 1","s":"nhấn vừa"},{"l":"Âm tiết 2","s":"nhấn vừa"},{"l":"Âm tiết 3","s":"nhấn vừa"},{"l":"Âm tiết 4","s":"mạnh · dài nhất","st":true}],"tip":"Ba âm tiết đầu <b>giữ đủ thanh điệu</b>, đọc đều; dồn lực và kéo dài <b>âm tiết cuối</b>. Thành ngữ bốn chữ (<span class=\"zh\">爱不释手</span>) cũng theo quy tắc này.","rows":[[{"hz":"公共汽车","syl":["gōng","gòng","qì","chē"],"sp":[1],"st":3,"vi":"xe buýt"},{"hz":"高速公路","syl":["gāo","sù","gōng","lù"],"sp":[1],"st":3,"vi":"đường cao tốc"},{"hz":"名胜古迹","syl":["míng","shèng","gǔ","jì"],"sp":[1],"st":3,"vi":"danh lam thắng cảnh"},{"hz":"爱不释手","syl":["ài","bú","shì","shǒu"],"sp":true,"st":3,"vi":"thích mê, không rời tay"}]]},{"id":"pa-02","grp":"四音节词语的重音","grpVi":"Trọng âm của từ ngữ có bốn âm tiết","zh":"含轻声音节的四音节词语","py":"","tag":"Trọng âm","vi":"Từ ngữ có bốn âm tiết mang một thanh nhẹ","listZh":"(2) 含轻声音节的四音节词语","listVi":"Từ ngữ có bốn âm tiết mang một thanh nhẹ — âm tiết 2 đọc nhẹ, âm tiết 4 nhấn mạnh","descZh":"含有轻声音节的四音节词语一般为形容词，第二个音节一般为轻声音节，第四个音节为重读音节。","descVi":"Những từ này thường là tính từ, trong đó âm tiết thứ hai thường là âm tiết mang thanh nhẹ còn âm tiết thứ tư được đọc nhấn mạnh.","pat":[{"l":"Âm tiết 1","s":"nhấn vừa"},{"l":"Âm tiết 2","s":"nhẹ · ngắn nhất","lt":true},{"l":"Âm tiết 3","s":"nhấn vừa"},{"l":"Âm tiết 4","s":"mạnh · dài nhất","st":true}],"tip":"Hay gặp ở dạng láy <b>AABB</b>: chữ <b>A thứ hai</b> đọc thanh nhẹ (pinyin không dấu), chữ <b>B cuối</b> nhấn mạnh, kéo dài.","rows":[[{"hz":"哆哆嗦嗦","syl":["duō","duo","suō","suō"],"st":3,"lt":1,"vi":"run lẩy bẩy"},{"hz":"晃晃悠悠","syl":["huàng","huang","yōu","yōu"],"st":3,"lt":1,"vi":"lắc la lắc lư"},{"hz":"磨磨唧唧","syl":["mò","mo","jī","jī"],"st":3,"lt":1,"vi":"lề mề, chậm chạp"},{"hz":"噼里啪啦","syl":["pī","li","pā","lā"],"st":3,"lt":1,"vi":"lốp bốp, lách tách"}]]}]},{"id":"k2v2-b04","courseId":"k2v2","order":4,"title":"Ông ấy đã giới thiệu giúp tôi công việc này","titleZh":"这个工作是他帮我介绍的。","titlePy":"zhège gōngzuò shì tā bāng wǒ jièshào de","vocab":[{"stt":1,"hanzi":"生日","pinyin":"shēngrì","hanviet":"Sinh nhật","pos":"Danh từ","meaning":"sinh nhật","comps":"生日快乐 (chúc mừng sinh nhật), 过生日 (tổ chức sinh nhật)","example":{"zh":"今天是我的生日。","py":"Jīntiān shì wǒ de shēngrì.","vi":"Hôm nay là sinh nhật của mình."}},{"stt":2,"hanzi":"快乐","pinyin":"kuàilè","hanviet":"Khoái lạc","pos":"Tính từ","meaning":"vui vẻ, vui sướng","comps":"生日快乐 (chúc mừng sinh nhật), 新年快乐 (chúc mừng năm mới)","example":{"zh":"生日快乐！","py":"Shēngrì kuàilè!","vi":"Chúc mừng sinh nhật!"}},{"stt":3,"hanzi":"接","pinyin":"jiē","hanviet":"Tiếp","pos":"Động từ","meaning":"nghe máy; đón; nối","comps":"接电话 (nghe điện thoại), 接人 (đón người)","example":{"zh":"电话是他接的。","py":"Diànhuà shì tā jiē de.","vi":"Điện thoại là anh ấy nghe."}},{"stt":4,"hanzi":"晚上","pinyin":"wǎnshang","hanviet":"Vãn thượng","pos":"Danh từ","meaning":"buổi tối","comps":"今天晚上 (tối nay), 晚上好 (chào buổi tối)","example":{"zh":"我晚上不工作。","py":"Wǒ wǎnshang bù gōngzuò.","vi":"Buổi tối mình không làm việc."}},{"stt":5,"hanzi":"问","pinyin":"wèn","hanviet":"Vấn","pos":"Động từ","meaning":"hỏi","comps":"问一下 (hỏi một chút), 问老师 (hỏi thầy cô)","example":{"zh":"我想问一下老师。","py":"Wǒ xiǎng wèn yíxià lǎoshī.","vi":"Mình muốn hỏi thầy giáo một chút."}},{"stt":6,"hanzi":"非常","pinyin":"fēicháng","hanviet":"Phi thường","pos":"Phó từ","meaning":"rất, vô cùng","comps":"非常好 (rất tốt), 非常喜欢 (rất thích)","example":{"zh":"我非常喜欢踢足球。","py":"Wǒ fēicháng xǐhuan tī zúqiú.","vi":"Mình cực kỳ thích đá bóng."}},{"stt":7,"hanzi":"开始","pinyin":"kāishǐ","hanviet":"Khai thuỷ","pos":"Động từ","meaning":"bắt đầu","comps":"开始工作 (bắt đầu làm việc), 开始学 (bắt đầu học)","example":{"zh":"我们几点开始？","py":"Wǒmen jǐ diǎn kāishǐ?","vi":"Mấy giờ chúng mình bắt đầu?"}},{"stt":8,"hanzi":"已经","pinyin":"yǐjīng","hanviet":"Dĩ kinh","pos":"Phó từ","meaning":"đã, đã… rồi","comps":"已经来了 (đã đến rồi), 已经两年 (đã hai năm)","example":{"zh":"他已经开始工作了。","py":"Tā yǐjīng kāishǐ gōngzuò le.","vi":"Anh ấy đã bắt đầu làm việc rồi."}},{"stt":9,"hanzi":"长","pinyin":"cháng","hanviet":"Trường","pos":"Tính từ","meaning":"dài (độ dài, thời gian)","comps":"多长时间 (bao lâu), 很长 (rất dài)","example":{"zh":"你学了多长时间了？","py":"Nǐ xué le duō cháng shíjiān le?","vi":"Bạn học được bao lâu rồi?"}},{"stt":10,"hanzi":"两","pinyin":"liǎng","hanviet":"Lưỡng","pos":"Số từ","meaning":"hai (trước lượng từ)","comps":"两个 (hai cái), 两年 (hai năm)","example":{"zh":"我买了两本书。","py":"Wǒ mǎi le liǎng běn shū.","vi":"Mình đã mua hai quyển sách."}},{"stt":11,"hanzi":"帮","pinyin":"bāng","hanviet":"Bang","pos":"Động từ","meaning":"giúp, giúp đỡ","comps":"帮我 (giúp tôi), 帮你介绍 (giới thiệu giúp bạn)","example":{"zh":"他帮我介绍工作。","py":"Tā bāng wǒ jièshào gōngzuò.","vi":"Anh ấy giới thiệu việc làm giúp mình."}},{"stt":12,"hanzi":"介绍","pinyin":"jièshào","hanviet":"Giới thiệu","pos":"Động từ","meaning":"giới thiệu","comps":"介绍工作 (giới thiệu việc làm), 自我介绍 (tự giới thiệu)","example":{"zh":"我介绍一下我的同学。","py":"Wǒ jièshào yíxià wǒ de tóngxué.","vi":"Mình giới thiệu một chút về bạn học của mình."}}],"hanzi":[{"char":"生日","pinyin":"shēngrì","hanviet":"Sinh nhật","chars":["生","日"],"story":"生日 gồm 生 (sinh ra) và 日 (mặt trời, ngày). 生 vẽ mầm cây nhú lên khỏi mặt đất nên có nghĩa \"sinh ra, nảy nở\"; ghép với 日 thành \"ngày được sinh ra\" — chính là sinh nhật."},{"char":"快乐","pinyin":"kuàilè","hanviet":"Khoái lạc","chars":["快","乐"],"story":"快 gồm bộ Tâm đứng 忄 (chỉ tình cảm) và 夬 chỉ âm kuài. 乐 vốn vẽ cây đàn có dây căng trên giá gỗ — nghe nhạc thì lòng vui, nên 乐 lè nghĩa là \"vui\"."},{"char":"接","pinyin":"jiē","hanviet":"Tiếp","chars":["接"],"story":"接 gồm bộ Thủ 扌 (bàn tay) và 妾 chỉ âm jiē. Mọi nghĩa của 接 đều là động tác của tay: đón lấy, cầm lấy, nối vào — nên 接电话 là \"cầm máy lên nghe\"."},{"char":"晚上","pinyin":"wǎnshang","hanviet":"Vãn thượng","chars":["晚","上"],"story":"晚 gồm 日 (mặt trời) và 免 chỉ âm wǎn, tả lúc mặt trời đã lặn nên nghĩa là \"muộn, tối\". Ghép với 上 thành cụm chỉ khoảng thời gian, cùng kiểu với 早上 (buổi sáng)."},{"char":"问","pinyin":"wèn","hanviet":"Vấn","chars":["问"],"story":"问 gồm 门 (cánh cửa, vừa chỉ âm mén → wèn) và 口 (cái miệng). Hình ảnh đứng ngoài cửa cất miệng hỏi vọng vào trong nhà, nên 问 nghĩa là \"hỏi\"."},{"char":"非常","pinyin":"fēicháng","hanviet":"Phi thường","chars":["非","常"],"story":"非 nghĩa gốc là \"không phải\", 常 là \"bình thường, thường ngày\". 非常 tức là \"không bình thường\" — vượt hẳn mức thường ngày, nên dịch thành \"rất, vô cùng\"."},{"char":"开始","pinyin":"kāishǐ","hanviet":"Khai thuỷ","chars":["开","始"],"story":"开 vẽ hai bàn tay tháo then cài để mở cửa, nghĩa là \"mở\". 始 gồm 女 (phụ nữ) và 台 chỉ âm shǐ, nghĩa là \"khởi đầu\". Mở ra và khởi đầu ghép lại thành \"bắt đầu\"."},{"char":"已经","pinyin":"yǐjīng","hanviet":"Dĩ kinh","chars":["已","经"],"story":"已 vốn là dạng biến thể của 己, được mượn dùng với nghĩa \"xong rồi, thôi\". 经 gồm bộ Mịch 纟 (sợi tơ) và 巠 chỉ âm, nghĩa là \"trải qua\". 已经 = việc đã trải qua rồi."},{"char":"长","pinyin":"cháng","hanviet":"Trường","chars":["长"],"story":"长 vẽ một người để tóc dài đang chống gậy — tóc dài là dấu hiệu người nhiều tuổi. Từ hình ảnh đó chữ có hai âm: cháng nghĩa là \"dài\", zhǎng nghĩa là \"lớn lên, đứng đầu\"."},{"char":"两","pinyin":"liǎng","hanviet":"Lưỡng","chars":["两"],"story":"两 vốn vẽ cái ách đôi đặt trên cổ hai con ngựa cùng kéo một cỗ xe. Hai vật luôn đi thành cặp, nên 两 nghĩa là \"hai, một đôi\" và đứng ngay trước lượng từ."},{"char":"帮","pinyin":"bāng","hanviet":"Bang","chars":["帮"],"story":"帮 gồm 邦 (xóm làng, nước — chỉ âm bāng) và bộ Cân 巾 (mảnh vải). Người trong cùng một xóm làng che chở đùm bọc nhau, nên 帮 mang nghĩa \"giúp đỡ\"."},{"char":"介绍","pinyin":"jièshào","hanviet":"Giới thiệu","chars":["介","绍"],"story":"介 vẽ người mặc áo giáp đứng ở giữa, nghĩa là \"xen vào giữa\". 绍 gồm bộ Mịch 纟 (sợi tơ) và 召 chỉ âm shào, nghĩa là \"nối lại\". Đứng giữa nối hai bên với nhau chính là \"giới thiệu\"."}],"grammar":[{"title":"Cấu trúc nhấn mạnh 是……的","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>是</b><small>mở phần nhấn mạnh</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>强调部分 + 动词</b><small>ai / khi nào / thế nào</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>chốt cuối câu</small></span></div>","summary":"<p class=\"gr-lead\">Làm rõ ai làm, làm lúc nào</p><ul><li>Dùng khi việc <b>đã xảy ra rồi</b>: người nói không hỏi có hay không, mà muốn làm rõ <span class=\"zh\">谁</span> làm, làm <b>lúc nào</b>, làm <b>bằng cách nào</b>.</li><li>HSK 1 Bài 15 đã học <span class=\"zh\">是……的</span> nhấn cách thức (<span class=\"zh\">我是坐飞机来的</span>); bài này thêm hai trọng tâm: <b>người thực hiện</b> và <b>thời gian</b>.</li><li>Phần cần nhấn đặt ngay <b>sau</b> <span class=\"zh\">是</span>, còn <span class=\"zh\">的</span> luôn nằm <b>cuối câu</b>, sau động từ.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">这本书是我写的。</span> = Quyển sách này là <b>do mình</b> viết.　·　Phủ định: <span class=\"zh\">不是……的</span></p>","note":"<b>Lưu ý:</b> Người Việt hay <b>quên chữ</b> <span class=\"zh\">的</span> ở cuối — thiếu nó câu chỉ còn là kể việc, mất hẳn ý nhấn mạnh.","examples":[{"zh":"这本书是我买的。","py":"Zhè běn shū shì wǒ mǎi de.","vi":"Quyển sách này là mình mua."},{"zh":"晚饭是妈妈做的。","py":"Wǎnfàn shì māma zuò de.","vi":"Bữa tối là mẹ nấu."},{"zh":"电话是谁打的？","py":"Diànhuà shì shéi dǎ de?","vi":"Điện thoại là ai gọi thế?"},{"zh":"这个汉字不是大卫写的。","py":"Zhège Hànzì bú shì Dàwèi xiě de.","vi":"Chữ Hán này không phải David viết."},{"zh":"菜单不是王方买的。","py":"Càidān bú shì Wáng Fāng mǎi de.","vi":"Thực đơn không phải Vương Phương mua."},{"zh":"电话不是我接的。","py":"Diànhuà bú shì wǒ jiē de.","vi":"Điện thoại không phải mình nghe."}],"exercises":[]},{"title":"Cụm chỉ thời gian ……的时候","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>时间 / 动词短语</b><small>việc làm mốc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的时候</b><small>lúc, khi</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>主语 + 动词</b><small>việc xảy ra</small></span></div>","summary":"<p class=\"gr-lead\">Nói \"lúc / khi làm việc gì\"</p><ul><li>Cụm <span class=\"zh\">的时候</span> nêu mốc thời gian, thường đứng <b>đầu câu</b> hoặc ngay sau chủ ngữ, rồi mới đến việc chính.</li><li>Phần đứng trước có thể là từ chỉ thời gian (<span class=\"zh\">小的时候</span>), một cụm động từ (<span class=\"zh\">吃饭的时候</span>) hay cả một câu ngắn (<span class=\"zh\">我11岁的时候</span>).</li><li>Muốn hỏi \"khi nào\" thì dùng <span class=\"zh\">什么时候</span> — chính là <span class=\"zh\">什么</span> ghép với <span class=\"zh\">时候</span>, học ở Bài 3 HSK 1.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">我11岁的时候开始踢足球。</span> = <b>Lúc mình 11 tuổi</b> thì bắt đầu đá bóng.</p>","note":"<b>Lưu ý:</b> Tiếng Việt đặt chữ \"khi\" ở <b>đầu</b>, tiếng Trung để <span class=\"zh\">的时候</span> ở <b>sau</b>: nói <span class=\"zh\">我11岁的时候</span>, không nói <span class=\"zh\">的时候我11岁</span>.","examples":[{"zh":"今天早上八点的时候我没在家。","py":"Jīntiān zǎoshang bā diǎn de shíhou wǒ méi zài jiā.","vi":"Lúc 8 giờ sáng nay mình không ở nhà."},{"zh":"我十八岁的时候一个人来到北京。","py":"Wǒ shíbā suì de shíhou yí ge rén láidào Běijīng.","vi":"Năm 18 tuổi mình một mình đến Bắc Kinh."},{"zh":"我十一岁的时候开始踢足球。","py":"Wǒ shíyī suì de shíhou kāishǐ tī zúqiú.","vi":"Lúc 11 tuổi mình bắt đầu đá bóng."},{"zh":"我睡觉的时候，我妈妈在做饭。","py":"Wǒ shuìjiào de shíhou, wǒ māma zài zuò fàn.","vi":"Lúc mình ngủ thì mẹ mình đang nấu cơm."},{"zh":"麦克到学校的时候下雨了。","py":"Màikè dào xuéxiào de shíhou xià yǔ le.","vi":"Lúc Mike đến trường thì trời đổ mưa."},{"zh":"王老师工作的时候，她丈夫开车去医院了。","py":"Wáng lǎoshī gōngzuò de shíhou, tā zhàngfu kāi chē qù yīyuàn le.","vi":"Lúc cô Vương đang làm việc thì chồng cô lái xe đến bệnh viện."}],"exercises":[]},{"title":"Phó từ 已经","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>已经</b><small>đã</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词 / 形容词</b><small>việc, trạng thái</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b><small>chốt cuối câu</small></span></div>","summary":"<p class=\"gr-lead\">Việc đã xảy ra tính đến giờ</p><ul><li><span class=\"zh\">已经</span> là <b>phó từ</b> nên luôn đứng <b>trước</b> động từ hoặc tính từ, không bao giờ đứng cuối câu.</li><li>Rất hay đi cặp với <span class=\"zh\">了</span> ở cuối câu — <span class=\"zh\">已经……了</span> báo việc đã hoàn thành tính đến lúc nói.</li><li>Ghép với lượng thời gian để nói việc kéo dài bao lâu: <span class=\"zh\">已经踢了10年了</span> (đã đá được 10 năm rồi).</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">已经两年多了。</span> = Đã hơn hai năm rồi.　·　Phủ định: <span class=\"zh\">还没……呢</span></p>","note":"<b>Lưu ý:</b> Phủ định <b>không phải</b> <span class=\"zh\">不已经</span> mà là <span class=\"zh\">还没……呢</span> (vẫn chưa…).","examples":[{"zh":"王老师已经回家了。","py":"Wáng lǎoshī yǐjīng huí jiā le.","vi":"Cô Vương đã về nhà rồi."},{"zh":"我的身体已经好了。","py":"Wǒ de shēntǐ yǐjīng hǎo le.","vi":"Sức khoẻ của mình đã khỏi rồi."},{"zh":"（踢足球）已经踢了十年了。","py":"(Tī zúqiú) yǐjīng tī le shí nián le.","vi":"(Đá bóng) đã đá được mười năm rồi."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · HỘI THOẠI","titleVi":"Trong lớp — A tặng quà sinh nhật","lines":[{"speaker":"甲","name":"Bạn A","zh":"生日快乐！这是送给你的！","py":"Shēngrì kuàilè! Zhè shì sòng gěi nǐ de!","vi":"Chúc mừng sinh nhật! Cái này tặng cậu đấy!"},{"speaker":"乙","name":"Bạn B","zh":"是什么？是一本书吗？","py":"Shì shénme? Shì yì běn shū ma?","vi":"Gì thế? Là một quyển sách à?"},{"speaker":"甲","name":"Bạn A","zh":"对，这本书是我写的。","py":"Duì, zhè běn shū shì wǒ xiě de.","vi":"Đúng rồi, quyển sách này là mình viết đấy."},{"speaker":"乙","name":"Bạn B","zh":"太谢谢你了！","py":"Tài xièxie nǐ le!","vi":"Cảm ơn cậu nhiều lắm!"}]},{"titleZh":"课文二 · HỘI THOẠI","titleVi":"Ở nhà — bố mẹ hỏi về cuộc gọi sáng","lines":[{"speaker":"甲","name":"Bạn A","zh":"早上有你一个电话。","py":"Zǎoshang yǒu nǐ yí ge diànhuà.","vi":"Sáng nay có một cuộc điện thoại gọi cho cậu."},{"speaker":"乙","name":"Bạn B","zh":"电话是谁打的？","py":"Diànhuà shì shéi dǎ de?","vi":"Điện thoại là ai gọi thế?"},{"speaker":"甲","name":"Bạn A","zh":"不知道，是儿子接的。","py":"Bù zhīdào, shì érzi jiē de.","vi":"Không biết nữa, con trai là người nghe máy."},{"speaker":"乙","name":"Bạn B","zh":"好，晚上我问一下儿子。","py":"Hǎo, wǎnshang wǒ wèn yíxià érzi.","vi":"Được, tối mình hỏi con trai một chút."}]},{"titleZh":"课文三 · HỘI THOẠI","titleVi":"Ở sân bóng — nói chuyện đá bóng","lines":[{"speaker":"甲","name":"Bạn A","zh":"你喜欢踢足球吗？","py":"Nǐ xǐhuan tī zúqiú ma?","vi":"Cậu có thích đá bóng không?"},{"speaker":"乙","name":"Bạn B","zh":"非常喜欢。","py":"Fēicháng xǐhuan.","vi":"Thích cực kỳ luôn."},{"speaker":"甲","name":"Bạn A","zh":"你是什么时候开始踢足球的？","py":"Nǐ shì shénme shíhou kāishǐ tī zúqiú de?","vi":"Cậu bắt đầu đá bóng từ khi nào thế?"},{"speaker":"乙","name":"Bạn B","zh":"我11岁的时候开始踢足球，已经踢了10年了。","py":"Wǒ shíyī suì de shíhou kāishǐ tī zúqiú, yǐjīng tī le shí nián le.","vi":"Mình bắt đầu đá bóng lúc 11 tuổi, đá được 10 năm rồi."}]},{"titleZh":"课文四 · HỘI THOẠI","titleVi":"Ở công ty — đồng nghiệp làm quen","lines":[{"speaker":"甲","name":"Bạn A","zh":"你在这儿工作多长时间了？","py":"Nǐ zài zhèr gōngzuò duō cháng shíjiān le?","vi":"Cậu làm việc ở đây bao lâu rồi?"},{"speaker":"乙","name":"Bạn B","zh":"已经两年多了，我是2011年来的。","py":"Yǐjīng liǎng nián duō le, wǒ shì èr líng yī yī nián lái de.","vi":"Hơn hai năm rồi, mình đến đây từ năm 2011."},{"speaker":"甲","name":"Bạn A","zh":"你认识谢先生吗？","py":"Nǐ rènshi Xiè xiānsheng ma?","vi":"Cậu có quen anh Tạ không?"},{"speaker":"乙","name":"Bạn B","zh":"认识，我们是大学同学，这个工作是他帮我介绍的。","py":"Rènshi, wǒmen shì dàxué tóngxué, zhège gōngzuò shì tā bāng wǒ jièshào de.","vi":"Quen chứ, bọn mình là bạn đại học, công việc này là do anh ấy giới thiệu giúp mình."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"语法重音","grpVi":"Trọng âm ngữ pháp của câu","introZh":"在不表达特殊的思想和感情的情况下，根据语法结构的特点而重读的某些句子成分，叫做语法重音。语法重音的位置比较固定，一般规律是：谓语、补语、定语和状语重读。","introVi":"Trong trường hợp không diễn tả suy nghĩ hay tình cảm đặc biệt, một số thành phần trong câu có thể được đọc nhấn mạnh dựa vào đặc điểm cấu trúc ngữ pháp. Các trọng âm đó được gọi là trọng âm ngữ pháp. Vị trí của trọng âm ngữ pháp tương đối cố định, quy tắc chung là đọc nhấn mạnh vị ngữ, bổ ngữ, định ngữ và trạng ngữ.","zh":"谓语重读","py":"wèiyǔ zhòngdú","tag":"Trọng âm câu","vi":"Đọc nhấn mạnh vị ngữ","listZh":"(1) 谓语重读","listVi":"Đọc nhấn mạnh vị ngữ — động từ chính của câu","descZh":"语法重音的位置比较固定：谓语、补语、定语和状语重读。","descVi":"Vị trí trọng âm ngữ pháp tương đối cố định: đọc nhấn mạnh vị ngữ, bổ ngữ, định ngữ và trạng ngữ.","pat":[{"l":"主语","s":"chủ ngữ"},{"l":"谓语","s":"vị ngữ · nhấn mạnh","st":true},{"l":"宾语","s":"tân ngữ"}],"tip":"Câu kể bình thường: dồn lực vào <b>động từ làm vị ngữ</b> (<span class=\"zh\">学习、是、买</span>).","sents":[{"w":[{"hz":"我","py":"Wǒ"},{"hz":"学习","py":"xuéxí","st":true},{"hz":"汉语。","py":"Hànyǔ."}],"vi":"Mình học tiếng Trung."},{"w":[{"hz":"他","py":"Tā"},{"hz":"哥哥","py":"gēge","j":true},{"hz":"是","py":"shì","st":true,"j":true},{"hz":"一","py":"yì","j":true},{"hz":"名","py":"míng","j":true},{"hz":"医生。","py":"yīshēng."}],"vi":"Anh trai cậu ấy là bác sĩ."},{"w":[{"hz":"王","py":"Wáng"},{"hz":"小姐","py":"xiǎojiě"},{"hz":"买","py":"mǎi","st":true},{"hz":"了","py":"le","j":true},{"hz":"几","py":"jǐ"},{"hz":"件","py":"jiàn","j":true},{"hz":"衣服。","py":"yīfu.","j":true}],"vi":"Cô Vương đã mua mấy bộ quần áo."}]},{"id":"pa-02","grp":"语法重音","grpVi":"Trọng âm ngữ pháp của câu","zh":"补语重读","py":"bǔyǔ zhòngdú","tag":"Trọng âm câu","vi":"Đọc nhấn mạnh bổ ngữ","listZh":"(2) 补语重读","listVi":"Đọc nhấn mạnh bổ ngữ — phần đứng sau 得","descZh":"语法重音的位置比较固定：谓语、补语、定语和状语重读。","descVi":"Vị trí trọng âm ngữ pháp tương đối cố định: đọc nhấn mạnh vị ngữ, bổ ngữ, định ngữ và trạng ngữ.","pat":[{"l":"谓语","s":"động / tính từ"},{"l":"得","s":"đọc nhẹ","lt":true},{"l":"补语","s":"bổ ngữ · nhấn mạnh","st":true}],"tip":"<span class=\"zh\">得</span> đọc nhẹ, dồn lực vào <b>bổ ngữ phía sau</b> (<span class=\"zh\">跳了起来、非常好、很好吃</span>).","sents":[{"w":[{"hz":"他们","py":"Tāmen"},{"hz":"高兴","py":"gāoxìng"},{"hz":"得","py":"de"},{"hz":"跳了","py":"tiàole","st":true,"j":true},{"hz":"起来。","py":"qilai.","st":true,"j":true}],"vi":"Họ vui đến mức nhảy cẫng lên."},{"w":[{"hz":"大卫","py":"Dàwèi"},{"hz":"打","py":"dǎ"},{"hz":"篮球","py":"lánqiú","j":true},{"hz":"打得","py":"dǎ de","j":true},{"hz":"非常","py":"fēicháng","st":true},{"hz":"好。","py":"hǎo.","st":true}],"vi":"David chơi bóng rổ rất giỏi."},{"w":[{"hz":"今天","py":"Jīntiān"},{"hz":"的","py":"de"},{"hz":"羊肉","py":"yángròu"},{"hz":"做得","py":"zuò de"},{"hz":"很","py":"hěn","st":true,"j":true},{"hz":"好吃。","py":"hǎochī.","st":true}],"vi":"Thịt cừu hôm nay nấu rất ngon."}]}]},{"id":"k2v2-b05","courseId":"k2v2","order":5,"title":"Mua chiếc áo này đi","titleZh":"就买这件吧。","titlePy":"jiù mǎi zhè jiàn ba","vocab":[{"stt":1,"hanzi":"外面","pinyin":"wàimiàn","hanviet":"Ngoại diện","pos":"Danh từ","meaning":"bên ngoài, phía ngoài","comps":"在外面 (ở bên ngoài), 外面吃 (ăn ở ngoài)","example":{"zh":"我不想去外面吃。","py":"Wǒ bù xiǎng qù wàimiàn chī.","vi":"Mình không muốn ra ngoài ăn."}},{"stt":2,"hanzi":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","pos":"Động từ","meaning":"chuẩn bị; định, dự định","comps":"准备好 (chuẩn bị xong), 准备考试 (ôn thi)","example":{"zh":"那你准备做什么呢？","py":"Nà nǐ zhǔnbèi zuò shénme ne?","vi":"Vậy bạn định nấu món gì?"}},{"stt":3,"hanzi":"就","pinyin":"jiù","hanviet":"Tựu","pos":"Phó từ","meaning":"thì, cứ; ngay, liền","comps":"就是 (chính là), 就买 (thì mua)","example":{"zh":"就买这件吧。","py":"Jiù mǎi zhè jiàn ba.","vi":"Thì mua cái này đi."}},{"stt":4,"hanzi":"鱼","pinyin":"yú","hanviet":"Ngư","pos":"Danh từ","meaning":"cá","comps":"吃鱼 (ăn cá), 做鱼 (làm món cá)","example":{"zh":"就做你爱吃的鱼吧。","py":"Jiù zuò nǐ ài chī de yú ba.","vi":"Thì làm món cá bạn thích nhé."}},{"stt":5,"hanzi":"吧","pinyin":"ba","hanviet":"Ba","pos":"Trợ từ","meaning":"trợ từ cuối câu đề nghị","comps":"走吧 (đi thôi), 好吧 (thôi được)","example":{"zh":"休息一下吧。","py":"Xiūxi yíxià ba.","vi":"Nghỉ một lát đi."}},{"stt":6,"hanzi":"件","pinyin":"jiàn","hanviet":"Kiện","pos":"Lượng từ","meaning":"cái, chiếc (áo, sự việc)","comps":"一件衣服 (một cái áo), 一件事 (một việc)","example":{"zh":"这件衣服怎么样？","py":"Zhè jiàn yīfu zěnmeyàng?","vi":"Cái áo này thế nào?"}},{"stt":7,"hanzi":"还","pinyin":"hái","hanviet":"Hoàn","pos":"Phó từ","meaning":"cũng khá, tạm được","comps":"还可以 (tạm được), 还不错 (cũng khá)","example":{"zh":"颜色还可以。","py":"Yánsè hái kěyǐ.","vi":"Màu sắc cũng tạm được."}},{"stt":8,"hanzi":"可以","pinyin":"kěyǐ","hanviet":"Khả dĩ","pos":"Động từ","meaning":"có thể, được phép","comps":"可以吗？(được không), 不可以 (không được)","example":{"zh":"我可以看一下吗？","py":"Wǒ kěyǐ kàn yíxià ma?","vi":"Mình xem một chút được không?"}},{"stt":9,"hanzi":"不错","pinyin":"búcuò","hanviet":"Bất thác","pos":"Tính từ","meaning":"khá tốt, không tệ","comps":"很不错 (rất khá), 还不错 (cũng khá)","example":{"zh":"这件不错。","py":"Zhè jiàn búcuò.","vi":"Cái này khá đẹp."}},{"stt":10,"hanzi":"考试","pinyin":"kǎoshì","hanviet":"Khảo thí","pos":"Động từ","meaning":"thi; kỳ thi","comps":"考试了 (thi rồi), 汉语考试 (kỳ thi tiếng Hán)","example":{"zh":"昨天的考试怎么样？","py":"Zuótiān de kǎoshì zěnmeyàng?","vi":"Bài thi hôm qua thế nào?"}},{"stt":11,"hanzi":"意思","pinyin":"yìsi","hanviet":"Ý tư","pos":"Danh từ","meaning":"ý nghĩa, ý; ý tứ","comps":"什么意思 (nghĩa là gì), 有意思 (thú vị, hay)","example":{"zh":"很多字我都不知道是什么意思。","py":"Hěn duō zì wǒ dōu bù zhīdào shì shénme yìsi.","vi":"Rất nhiều chữ mình đều không biết nghĩa là gì."}},{"stt":12,"hanzi":"咖啡","pinyin":"kāfēi","hanviet":"Ca phi","pos":"Danh từ","meaning":"cà phê","comps":"喝咖啡 (uống cà phê), 一杯咖啡 (một cốc cà phê)","example":{"zh":"你喝咖啡吗？","py":"Nǐ hē kāfēi ma?","vi":"Bạn uống cà phê không?"}},{"stt":13,"hanzi":"对","pinyin":"duì","hanviet":"Đối","pos":"Giới từ","meaning":"đối với, với; đúng","comps":"对身体好 (tốt cho sức khoẻ), 对我说 (nói với tôi)","example":{"zh":"咖啡喝多了对身体不好。","py":"Kāfēi hē duō le duì shēntǐ bù hǎo.","vi":"Uống nhiều cà phê không tốt cho sức khoẻ."}},{"stt":14,"hanzi":"以后","pinyin":"yǐhòu","hanviet":"Dĩ hậu","pos":"Danh từ","meaning":"sau này, về sau","comps":"下课以后 (sau giờ học), 三天以后 (ba ngày sau)","example":{"zh":"以后我少喝一点。","py":"Yǐhòu wǒ shǎo hē yìdiǎn.","vi":"Sau này mình sẽ uống ít đi."}}],"hanzi":[{"char":"外面","pinyin":"wàimiàn","hanviet":"Ngoại diện","chars":["外","面"],"story":"外 = 夕 (buổi tối) + 卜 (bói toán). Người xưa quen bói vào buổi sáng, bói lúc trời tối là chuyện \"ngoài lệ\" → nghĩa \"bên ngoài\". 面 vốn vẽ khuôn mặt người, sau mở rộng thành \"mặt, phía\"."},{"char":"准备","pinyin":"zhǔnbèi","hanviet":"Chuẩn bị","chars":["准","备"],"story":"准 = 冫 (nước đóng băng, mặt phẳng) + 隹 (chim đuôi ngắn), gốc nghĩa \"ngang bằng, đúng chuẩn\". 备 nghĩa \"sắm sẵn, đầy đủ\". Sắm sẵn cho đúng chuẩn chính là 准备 – \"chuẩn bị\"."},{"char":"就","pinyin":"jiù","hanviet":"Tựu","chars":["就"],"story":"就 = 京 (gò đất cao, kinh đô) + 尤 (đặc biệt). Người xưa tìm tới chỗ đất cao mà ở, nên 就 gốc nghĩa \"đi tới ngay, tiến sát\"; từ đó thành phó từ \"ngay, thì, cứ\"."},{"char":"鱼","pinyin":"yú","hanviet":"Ngư","chars":["鱼"],"story":"鱼 là chữ tượng hình vẽ con cá: nét trên cùng là đầu, ô 田 ở giữa là thân cá có vảy, nét ngang dưới cùng (bản phồn thể là bốn chấm 灬) chính là cái đuôi."},{"char":"吧","pinyin":"ba","hanviet":"Ba","chars":["吧"],"story":"吧 = 口 (miệng) + 巴 bā (chỉ âm đọc). Bộ Khẩu cho biết đây là tiếng thốt ra từ miệng, tức trợ từ ngữ khí. Đây là chữ hình thanh điển hình, cùng kiểu với 吗 và 呢."},{"char":"件","pinyin":"jiàn","hanviet":"Kiện","chars":["件"],"story":"件 = 亻 (người) + 牛 (con bò). Người xưa mổ bò rồi chia thành từng phần, nên 件 mang nghĩa \"từng món, từng cái\", trở thành lượng từ đếm áo quần và sự việc."},{"char":"还","pinyin":"hái","hanviet":"Hoàn","chars":["还"],"story":"还 = 辶 (bộ Sước – bước đi) + 不. Đi rồi mà quay trở lại, nên đọc huán thì nghĩa là \"trả lại, quay về\"; đọc hái thì làm phó từ \"còn, vẫn, tạm được\"."},{"char":"可以","pinyin":"kěyǐ","hanviet":"Khả dĩ","chars":["可","以"],"story":"可 vẽ hơi thở thoát ra khỏi miệng 口 khi người ta gật đầu đồng ý → \"được, có thể\". 以 gốc nghĩa \"dùng, lấy\". Ghép lại 可以 = \"có thể dùng được\" → \"có thể, được phép\"."},{"char":"不错","pinyin":"búcuò","hanviet":"Bất thác","chars":["不","错"],"story":"不 là hình mầm cây không nhú lên khỏi mặt đất → mang nghĩa phủ định. 错 = 钅(kim loại) + 昔 (ngày xưa), gốc là mạ vàng xen lẫn → \"sai, nhầm\". 不错 = \"không sai\" → khá tốt."},{"char":"考试","pinyin":"kǎoshì","hanviet":"Khảo thí","chars":["考","试"],"story":"考 vẽ người già chống gậy (cùng gốc với 老), nghĩa \"khảo xét, tra xét\". 试 = 讠(lời nói) + 式 (khuôn phép) → \"thử theo khuôn phép\". 考试 = khảo xét theo khuôn phép, tức \"thi\"."},{"char":"意思","pinyin":"yìsi","hanviet":"Ý tư","chars":["意","思"],"story":"意 = 音 (âm thanh, lời nói) + 心 (trái tim): tiếng nói phát ra từ trong lòng → \"ý, ý nghĩ\". 思 = 田 (vốn là 囟 – thóp đầu) + 心: nghĩ bằng cả đầu óc lẫn trái tim → \"suy nghĩ\". 意思 = điều trong lòng muốn nói → \"ý nghĩa, ý\"."},{"char":"咖啡","pinyin":"kāfēi","hanviet":"Ca phi","chars":["咖","啡"],"story":"Cả hai chữ đều mang bộ Khẩu 口 vì liên quan tới việc uống, còn 加 jiā và 非 fēi chỉ mượn âm đọc. 咖啡 chính là cách phiên âm chữ \"coffee\" sang tiếng Hán."},{"char":"对","pinyin":"duì","hanviet":"Đối","chars":["对"],"story":"对 = 又 (bàn tay) + 寸 (tấc tay). Hai bàn tay hướng vào nhau nên 对 nghĩa \"đối diện, hướng về\"; khớp với nhau thì là \"đúng\", và làm giới từ \"đối với, với\"."},{"char":"以后","pinyin":"yǐhòu","hanviet":"Dĩ hậu","chars":["以","后"],"story":"以 gốc nghĩa \"dùng, lấy\", ở đây là lấy một mốc để tính. 后 vẽ người bước chậm, đi phía sau → \"phía sau\". 以后 = lấy một mốc rồi tính về sau, tức \"sau này, về sau\"."}],"grammar":[{"title":"Phó từ 就","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b><small>thì, cứ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>吧</b><small>trợ từ đề nghị</small></span></div>","summary":"<p class=\"gr-lead\">Dùng 就 để chốt lại lựa chọn</p><ul><li><span class=\"zh\">就</span> là <b>phó từ</b>, luôn đứng <b>trước động từ</b> — không bao giờ đứng đầu câu hay cuối câu.</li><li>Sau khi đã cân nhắc rồi <b>chốt lại</b> một lựa chọn thì dùng <span class=\"zh\">就</span>: <span class=\"zh\">这件不错，就买这件吧。</span></li><li>Rất hay đi cùng <span class=\"zh\">吧</span> ở cuối câu, khiến lời nói nhẹ đi thành một đề nghị thân mật.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">就买这件吧。</span> = Thì mua cái này đi.　·　<span class=\"zh\">就做你爱吃的鱼吧。</span></p>","note":"<b>Lưu ý:</b> Đừng lẫn với <span class=\"zh\">就是</span> = \"có điều, chỉ mỗi tội\": <span class=\"zh\">颜色还可以，就是有点儿大。</span>","examples":[{"zh":"你不想去，就在家休息吧。","py":"Nǐ bù xiǎng qù, jiù zài jiā xiūxi ba.","vi":"Bạn không muốn đi thì cứ ở nhà nghỉ ngơi đi."},{"zh":"这儿的咖啡不错，就喝咖啡吧。","py":"Zhèr de kāfēi búcuò, jiù hē kāfēi ba.","vi":"Cà phê ở đây khá ngon, thì uống cà phê đi."},{"zh":"就做你爱吃的鱼吧。","py":"Jiù zuò nǐ ài chī de yú ba.","vi":"Thì làm món cá bạn thích ăn nhé."}],"exercises":[]},{"title":"Phó từ 还 (nghĩa 1)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还</b><small>cũng khá</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ / 可以</small></span></div>","summary":"<p class=\"gr-lead\">还 + tính từ = \"cũng khá, tạm được\"</p><ul><li><span class=\"zh\">还</span> ở đây chỉ mức độ <b>\"tạm được, chấp nhận được\"</b> — khen vừa phải, chưa tới mức thật tốt.</li><li>Hai cụm dùng nhiều nhất là <span class=\"zh\">还可以</span> và <span class=\"zh\">还不错</span>, hay dùng để trả lời khi thấy ổn nhưng chưa hoàn hảo.</li><li>Mức độ tăng dần: <span class=\"zh\">还可以</span> &lt; <span class=\"zh\">不错</span> &lt; <span class=\"zh\">很好</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">颜色还可以。</span> = Màu sắc cũng tạm được.　·　<span class=\"zh\">这件还不错。</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">还</span> còn nghĩa \"còn, vẫn\" sẽ học sau; ở nghĩa này luôn đọc <b>hái</b>, <b>không</b> đọc <b>huán</b> (= trả lại).","examples":[{"zh":"A：你身体怎么样？　B：还好。","py":"Nǐ shēntǐ zěnmeyàng?  Hái hǎo.","vi":"Sức khoẻ của bạn thế nào? — Cũng ổn."},{"zh":"A：这件衣服大吗？　B：还行，不太大。","py":"Zhè jiàn yīfu dà ma?  Hái xíng, bú tài dà.","vi":"Cái áo này có rộng không? — Cũng được, không rộng lắm."},{"zh":"A：昨天的考试怎么样？　B：我觉得听和说还可以，读和写不好。","py":"Zuótiān de kǎoshì zěnmeyàng?  Wǒ juéde tīng hé shuō hái kěyǐ, dú hé xiě bù hǎo.","vi":"Bài thi hôm qua thế nào? — Mình thấy nghe và nói cũng tạm được, đọc và viết thì chưa tốt."}],"exercises":[]},{"title":"Phó từ 有点儿","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>有点儿</b><small>hơi…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span></div>","summary":"<p class=\"gr-lead\">Chê nhẹ: \"hơi… một chút\"</p><ul><li><span class=\"zh\">有点儿</span> đứng <b>trước tính từ</b>, chỉ mức độ nhẹ và thường mang ý <b>không vừa lòng</b>: hơi to, hơi đắt, hơi mệt.</li><li>Khẩu ngữ hay nói gọn thành <span class=\"zh\">有点</span>, nghĩa không đổi: <span class=\"zh\">这两天有点累。</span></li><li>Điều mình <b>hài lòng</b> thì không dùng: nói <span class=\"zh\">很漂亮</span>, không nói <span class=\"zh\">有点儿漂亮</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">就是有点儿大。</span> = Chỉ mỗi tội hơi rộng.　·　<span class=\"zh\">这两天有点累。</span></p>","note":"<b>Lưu ý:</b> Đừng lẫn với <span class=\"zh\">一点儿</span>: <span class=\"zh\">有点儿</span> đứng <b>trước</b> tính từ, còn <span class=\"zh\">一点儿</span> đứng <b>sau</b> — <span class=\"zh\">大一点儿</span> (to hơn một chút).","examples":[{"zh":"今天天气有点儿冷。","py":"Jīntiān tiānqì yǒudiǎnr lěng.","vi":"Hôm nay trời hơi lạnh."},{"zh":"我昨天有点儿累。","py":"Wǒ zuótiān yǒudiǎnr lèi.","vi":"Hôm qua mình hơi mệt."},{"zh":"（这件衣服）有点儿大。","py":"(Zhè jiàn yīfu) yǒudiǎnr dà.","vi":"(Cái áo này) hơi rộng."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — hai người bàn ăn tối ở đâu","lines":[{"speaker":"甲","name":"Bạn A","zh":"晚上我们去饭馆吃饭，怎么样？","py":"Wǎnshang wǒmen qù fànguǎn chīfàn, zěnmeyàng?","vi":"Tối nay chúng mình ra quán ăn cơm, thấy thế nào?"},{"speaker":"乙","name":"Bạn B","zh":"我不想去外面吃，我想在家吃。","py":"Wǒ bù xiǎng qù wàimiàn chī, wǒ xiǎng zài jiā chī.","vi":"Mình không muốn ra ngoài ăn, mình muốn ăn ở nhà."},{"speaker":"甲","name":"Bạn A","zh":"那你准备做什么呢？","py":"Nà nǐ zhǔnbèi zuò shénme ne?","vi":"Vậy bạn định nấu món gì thế?"},{"speaker":"乙","name":"Bạn B","zh":"就做你爱吃的鱼吧。","py":"Jiù zuò nǐ ài chī de yú ba.","vi":"Thì làm món cá bạn thích ăn nhé."}]},{"titleZh":"课文二 · 在商店","titleVi":"Trong cửa hàng — hai bạn chọn áo","lines":[{"speaker":"甲","name":"Bạn A","zh":"帮我看一下这件衣服怎么样。","py":"Bāng wǒ kàn yíxià zhè jiàn yīfu zěnmeyàng.","vi":"Xem giúp mình cái áo này thế nào."},{"speaker":"乙","name":"Bạn B","zh":"颜色还可以，就是有点儿大。","py":"Yánsè hái kěyǐ, jiùshì yǒudiǎnr dà.","vi":"Màu thì cũng được, chỉ mỗi tội hơi rộng."},{"speaker":"甲","name":"Bạn A","zh":"这件小的怎么样？","py":"Zhè jiàn xiǎo de zěnmeyàng?","vi":"Cái nhỏ này thì sao?"},{"speaker":"乙","name":"Bạn B","zh":"这件不错就买这件吧。","py":"Zhè jiàn búcuò, jiù mǎi zhè jiàn ba.","vi":"Cái này khá đẹp, mua cái này đi."}]},{"titleZh":"课文三 · 在教室","titleVi":"Trong lớp — nói về bài thi hôm qua","lines":[{"speaker":"甲","name":"Bạn A","zh":"去不去打球？","py":"Qù bu qù dǎ qiú?","vi":"Có đi chơi bóng không?"},{"speaker":"乙","name":"Bạn B","zh":"这两天有点累，不去打球了。","py":"Zhè liǎng tiān yǒudiǎn lèi, bú qù dǎ qiú le.","vi":"Mấy hôm nay hơi mệt, mình không đi chơi bóng nữa."},{"speaker":"甲","name":"Bạn A","zh":"你在做什么呢？是在想昨天考试吗？","py":"Nǐ zài zuò shénme ne? Shì zài xiǎng zuótiān kǎoshì ma?","vi":"Bạn đang làm gì thế? Đang nghĩ về bài thi hôm qua à?"},{"speaker":"乙","name":"Bạn B","zh":"是啊，我觉得听和说还可以，读和写不好，很多字我都不知道是什么意思。","py":"Shì a, wǒ juéde tīng hé shuō hái kěyǐ, dú hé xiě bù hǎo, hěn duō zì wǒ dōu bù zhīdào shì shénme yìsi.","vi":"Ừ, mình thấy nghe với nói thì cũng tạm được, còn đọc và viết thì kém, rất nhiều chữ mình đều không biết nghĩa là gì."}]},{"titleZh":"课文四 · 在公司","titleVi":"Ở công ty — giờ nghỉ, nói về cà phê","lines":[{"speaker":"甲","name":"Bạn A","zh":"休息一下吧，喝咖啡吗？","py":"Xiūxi yíxià ba, hē kāfēi ma?","vi":"Nghỉ một lát đi, uống cà phê không?"},{"speaker":"乙","name":"Bạn B","zh":"不喝了，我已经喝两杯了。","py":"Bù hē le, wǒ yǐjīng hē liǎng bēi le.","vi":"Thôi không uống nữa, mình uống hai cốc rồi."},{"speaker":"甲","name":"Bạn A","zh":"是啊，咖啡喝多了对身体不好。","py":"Shì a, kāfēi hē duō le duì shēntǐ bù hǎo.","vi":"Ừ nhỉ, uống nhiều cà phê không tốt cho sức khoẻ."},{"speaker":"乙","name":"Bạn B","zh":"以后我少喝一点，每天喝一杯。","py":"Yǐhòu wǒ shǎo hē yìdiǎn, měi tiān hē yì bēi.","vi":"Sau này mình sẽ uống ít đi, mỗi ngày một cốc thôi."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"语法重音","grpVi":"Trọng âm ngữ pháp của câu (2)","introZh":"在不表达特殊的思想和感情的情况下，根据语法结构的特点而重读的某些句子成分，叫做语法重音。语法重音的位置比较固定，一般规律是：谓语、补语、定语和状语重读。","introVi":"Trong trường hợp không diễn tả suy nghĩ hay tình cảm đặc biệt, một số thành phần trong câu có thể được đọc nhấn mạnh dựa vào đặc điểm cấu trúc ngữ pháp. Các trọng âm đó được gọi là trọng âm ngữ pháp. Vị trí của trọng âm ngữ pháp tương đối cố định, quy tắc chung là đọc nhấn mạnh vị ngữ, bổ ngữ, định ngữ và trạng ngữ.","zh":"定语重读","py":"dìngyǔ zhòngdú","tag":"Trọng âm câu","vi":"Đọc nhấn mạnh định ngữ","listZh":"(1) 定语重读","listVi":"Đọc nhấn mạnh định ngữ — phần bổ nghĩa đứng trước danh từ","descZh":"定语修饰名词，一般放在名词前面，常带\"的\"。读的时候，定语要重读。","descVi":"Định ngữ bổ nghĩa cho danh từ, thường đứng trước danh từ và hay đi kèm 的. Khi đọc, nhấn mạnh phần định ngữ.","pat":[{"l":"定语（的）","s":"định ngữ · nhấn mạnh","st":true},{"l":"中心语","s":"danh từ trung tâm"}],"tip":"Nhấn vào phần <b>đứng trước danh từ</b> (<span class=\"zh\">我妈妈做的、李老师工作了很多年的、红色的</span>), danh từ phía sau đọc bình thường.","sents":[{"w":[{"hz":"那","py":"Nà"},{"hz":"是","py":"shì"},{"hz":"我","py":"wǒ","st":true,"j":true},{"hz":"妈妈","py":"māma","st":true},{"hz":"做的","py":"zuò de","st":true},{"hz":"中国","py":"Zhōngguó"},{"hz":"菜。","py":"cài."}],"vi":"Đó là món Trung Quốc mẹ mình nấu."},{"w":[{"hz":"那个","py":"Nàge"},{"hz":"学校","py":"xuéxiào"},{"hz":"是","py":"shì"},{"hz":"李老师","py":"Lǐ lǎoshī","st":true,"j":true},{"hz":"工作了","py":"gōngzuòle","st":true},{"hz":"很","py":"hěn","st":true},{"hz":"多","py":"duō","st":true},{"hz":"年","py":"nián","st":true},{"hz":"的","py":"de","st":true},{"hz":"地方。","py":"dìfang."}],"vi":"Ngôi trường đó là nơi thầy Lý đã làm việc nhiều năm."},{"w":[{"hz":"我","py":"Wǒ"},{"hz":"最","py":"zuì"},{"hz":"喜欢","py":"xǐhuan"},{"hz":"红色","py":"hóngsè","st":true},{"hz":"的","py":"de","st":true},{"hz":"衣服。","py":"yīfu.","j":true}],"vi":"Mình thích nhất quần áo màu đỏ."}]},{"id":"pa-02","grp":"语法重音","grpVi":"Trọng âm ngữ pháp của câu (2)","zh":"状语重读","py":"zhuàngyǔ zhòngdú","tag":"Trọng âm câu","vi":"Đọc nhấn mạnh trạng ngữ","listZh":"(2) 状语重读","listVi":"Đọc nhấn mạnh trạng ngữ — phần bổ nghĩa đứng trước động từ","descZh":"状语修饰动词或形容词，一般放在谓语前面，有时带\"地\"。读的时候，状语要重读。","descVi":"Trạng ngữ bổ nghĩa cho động từ hoặc tính từ, thường đứng trước vị ngữ, đôi khi đi kèm 地. Khi đọc, nhấn mạnh phần trạng ngữ.","pat":[{"l":"状语（地）","s":"trạng ngữ · nhấn mạnh","st":true},{"l":"谓语","s":"động / tính từ"}],"tip":"Nhấn vào phần <b>đứng trước động từ</b> (<span class=\"zh\">就、飞一样地、从早到晚</span>), động từ phía sau đọc bình thường.","sents":[{"w":[{"hz":"你","py":"Nǐ"},{"hz":"的","py":"de","j":true},{"hz":"杯子","py":"bēizi","j":true},{"hz":"就","py":"jiù","st":true,"j":true},{"hz":"在","py":"zài","j":true},{"hz":"那儿。","py":"nàr.","j":true}],"vi":"Cốc của bạn ở ngay đằng kia."},{"w":[{"hz":"大卫","py":"Dàwèi"},{"hz":"的","py":"de"},{"hz":"狗","py":"gǒu"},{"hz":"飞","py":"fēi","st":true},{"hz":"一样","py":"yíyàng","st":true},{"hz":"地","py":"de","st":true},{"hz":"跑了","py":"pǎole"},{"hz":"过去。","py":"guoqu."}],"vi":"Con chó của David chạy vụt qua như bay."},{"w":[{"hz":"我","py":"Wǒ"},{"hz":"爸爸","py":"bàba","j":true},{"hz":"是","py":"shì"},{"hz":"医生，","py":"yīshēng,"},{"hz":"每天","py":"měi tiān"},{"hz":"从","py":"cóng","st":true},{"hz":"早","py":"zǎo","st":true},{"hz":"到","py":"dào","st":true},{"hz":"晚","py":"wǎn","st":true},{"hz":"忙","py":"máng"},{"hz":"工作。","py":"gōngzuò."}],"vi":"Bố mình là bác sĩ, ngày nào cũng bận việc từ sáng đến tối."}]}],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"Hỏi · Đáp","q":{"zh":"你喜欢吃什么？喜欢喝什么？","py":"Nǐ xǐhuan chī shénme? Xǐhuan hē shénme?","vi":"Hai bạn hỏi nhau về sở thích ăn uống: thích ăn gì, thích uống gì?"},"items":[{"zh":"我最喜欢吃……，也喜欢喝……。","py":"Wǒ zuì xǐhuan chī ……, yě xǐhuan hē …….","vi":"Mình thích ăn … nhất, cũng thích uống … ."},{"zh":"……还可以，就是有点儿……。","py":"…… hái kěyǐ, jiùshì yǒudiǎnr …….","vi":"… thì cũng được, chỉ mỗi tội hơi … ."},{"zh":"……喝多了对身体不好。","py":"…… hē duō le duì shēntǐ bù hǎo.","vi":"Uống nhiều … không tốt cho sức khoẻ."},{"lines":[{"who":"A","zh":"晚上你想吃什么？","py":"Wǎnshang nǐ xiǎng chī shénme?","vi":"Tối nay bạn muốn ăn gì?"},{"who":"B","zh":"就吃饺子吧，我最喜欢吃饺子。","py":"Jiù chī jiǎozi ba, wǒ zuì xǐhuan chī jiǎozi.","vi":"Thì ăn sủi cảo đi, mình thích sủi cảo nhất."}]}]}],"speak":[]}},{"id":"k2v2-b06","courseId":"k2v2","order":6,"title":"Sao anh không ăn nữa?","titleZh":"你怎么不吃了？","titlePy":"nǐ zěnme bù chī le","vocab":[{"stt":1,"hanzi":"门","pinyin":"mén","hanviet":"Môn","pos":"Danh từ","meaning":"cửa, cổng","comps":"门外 (ngoài cửa), 开门 (mở cửa)","example":{"zh":"我在门外看见他了。","py":"Wǒ zài mén wài kànjiàn tā le.","vi":"Mình nhìn thấy anh ấy ở ngoài cửa."}},{"stt":2,"hanzi":"外","pinyin":"wài","hanviet":"Ngoại","pos":"Danh từ","meaning":"bên ngoài, phía ngoài","comps":"门外 (ngoài cửa), 外面 (bên ngoài)","example":{"zh":"外面下雨了。","py":"Wàimiàn xià yǔ le.","vi":"Bên ngoài mưa rồi."}},{"stt":3,"hanzi":"自行车","pinyin":"zìxíngchē","hanviet":"Tự hành xa","pos":"Danh từ","meaning":"xe đạp","comps":"骑自行车 (đi xe đạp), 买自行车 (mua xe đạp)","example":{"zh":"这是他的自行车。","py":"Zhè shì tā de zìxíngchē.","vi":"Đây là xe đạp của anh ấy."}},{"stt":4,"hanzi":"羊肉","pinyin":"yángròu","hanviet":"Dương nhục","pos":"Danh từ","meaning":"thịt dê, thịt cừu","comps":"吃羊肉 (ăn thịt dê), 羊肉面 (mì thịt dê)","example":{"zh":"今天的羊肉很好吃。","py":"Jīntiān de yángròu hěn hǎochī.","vi":"Thịt dê hôm nay rất ngon."}},{"stt":5,"hanzi":"好吃","pinyin":"hǎochī","hanviet":"Hảo ngật","pos":"Tính từ","meaning":"ngon (đồ ăn)","comps":"很好吃 (rất ngon), 不好吃 (không ngon)","example":{"zh":"这个菜很好吃。","py":"Zhège cài hěn hǎochī.","vi":"Món này rất ngon."}},{"stt":6,"hanzi":"面条","pinyin":"miàntiáo","hanviet":"Diện điều","pos":"Danh từ","meaning":"mì, mì sợi","comps":"吃面条 (ăn mì), 一碗面条 (một bát mì)","example":{"zh":"来一点面条吧。","py":"Lái yìdiǎn miàntiáo ba.","vi":"Cho một ít mì đi."}},{"stt":7,"hanzi":"打篮球","pinyin":"dǎ lánqiú","hanviet":"Đả lam cầu","pos":"Cụm từ","meaning":"chơi bóng rổ","comps":"去打篮球 (đi chơi bóng rổ), 篮球 (bóng rổ)","example":{"zh":"我们去打篮球吧。","py":"Wǒmen qù dǎ lánqiú ba.","vi":"Chúng mình đi chơi bóng rổ đi."}},{"stt":8,"hanzi":"因为","pinyin":"yīnwèi","hanviet":"Nhân vi","pos":"Liên từ","meaning":"bởi vì, vì","comps":"因为下雨 (vì trời mưa), 因为……所以…… (vì… nên…)","example":{"zh":"因为下雨，我没去打篮球。","py":"Yīnwèi xià yǔ, wǒ méi qù dǎ lánqiú.","vi":"Vì trời mưa nên mình không đi chơi bóng rổ."}},{"stt":9,"hanzi":"所以","pinyin":"suǒyǐ","hanviet":"Sở dĩ","pos":"Liên từ","meaning":"cho nên, vì vậy","comps":"所以没去 (nên không đi), 因为……所以…… (vì… nên…)","example":{"zh":"昨天下雨，所以我们都没去。","py":"Zuótiān xià yǔ, suǒyǐ wǒmen dōu méi qù.","vi":"Hôm qua trời mưa nên bọn mình đều không đi."}},{"stt":10,"hanzi":"游泳","pinyin":"yóuyǒng","hanviet":"Du vịnh","pos":"Động từ","meaning":"bơi, bơi lội","comps":"去游泳 (đi bơi), 游泳了 (đã đi bơi)","example":{"zh":"你经常游泳吗？","py":"Nǐ jīngcháng yóuyǒng ma?","vi":"Bạn có hay đi bơi không?"}},{"stt":11,"hanzi":"经常","pinyin":"jīngcháng","hanviet":"Kinh thường","pos":"Phó từ","meaning":"thường xuyên, hay","comps":"经常去 (hay đi), 不经常 (không hay)","example":{"zh":"我经常吃面条。","py":"Wǒ jīngcháng chī miàntiáo.","vi":"Mình hay ăn mì."}},{"stt":12,"hanzi":"公斤","pinyin":"gōngjīn","hanviet":"Công cân","pos":"Lượng từ","meaning":"ki-lô-gam, cân","comps":"两公斤 (hai cân), 七十公斤 (bảy mươi cân)","example":{"zh":"我现在七十公斤了。","py":"Wǒ xiànzài qīshí gōngjīn le.","vi":"Giờ mình bảy mươi cân rồi."}},{"stt":13,"hanzi":"姐姐","pinyin":"jiějie","hanviet":"Tỷ tỷ","pos":"Danh từ","meaning":"chị gái","comps":"我姐姐 (chị tôi), 姐姐的书 (sách của chị)","example":{"zh":"他去看她姐姐。","py":"Tā qù kàn tā jiějie.","vi":"Anh ấy đi thăm chị gái cô ấy."}}],"hanzi":[{"char":"门","pinyin":"mén","hanviet":"Môn","chars":["门"],"story":"门 là chữ tượng hình vẽ cánh cửa. Bản phồn thể 門 thấy rõ hai cánh cửa đối nhau có then ngang; giản thể rút còn ba nét nhưng vẫn giữ dáng khung cửa."},{"char":"外","pinyin":"wài","hanviet":"Ngoại","chars":["外"],"story":"外 = 夕 (buổi tối) + 卜 (bói toán). Người xưa quen bói vào sáng sớm, bói lúc trời tối là chuyện \"ngoài lệ, ngoại lệ\" — từ đó 外 mang nghĩa \"bên ngoài\"."},{"char":"自行车","pinyin":"zìxíngchē","hanviet":"Tự hành xa","chars":["自","行","车"],"story":"自 vốn vẽ cái mũi (người Trung Quốc chỉ vào mũi khi nói \"tôi\") → \"tự mình\". 行 vẽ ngã tư đường → \"đi\". 车 là hình chiếc xe nhìn từ trên xuống. 自行车 = chiếc xe tự mình đi, tức xe đạp."},{"char":"羊肉","pinyin":"yángròu","hanviet":"Dương nhục","chars":["羊","肉"],"story":"羊 vẽ đầu con dê nhìn thẳng, hai chiếc sừng cong ở trên cùng. 肉 vẽ một miếng thịt có vân thớ bên trong. Ghép lại 羊肉 = thịt dê, thịt cừu."},{"char":"好吃","pinyin":"hǎochī","hanviet":"Hảo ngật","chars":["好","吃"],"story":"好 = 女 (phụ nữ) + 子 (đứa con): người xưa thấy mẹ bồng con là hình ảnh tốt đẹp. 吃 = 口 (miệng) + 乞 qǐ (chỉ âm đọc). 好吃 = \"ăn vào thấy tốt\" → ngon."},{"char":"面条","pinyin":"miàntiáo","hanviet":"Diện điều","chars":["面","条"],"story":"面 vốn vẽ khuôn mặt, sau được mượn dùng thay cho chữ 麵 (bột mì). 条 vẽ nhánh cây nhỏ và dài, dùng chỉ vật hình sợi. 面条 = sợi bột dài, chính là mì."},{"char":"打篮球","pinyin":"dǎ lánqiú","hanviet":"Đả lam cầu","chars":["打","篮","球"],"story":"打 = 扌 (bàn tay) + 丁 (chỉ âm) → \"đánh, chơi\". 篮 mang bộ Trúc 竹 vì cái rổ xưa đan bằng tre. 球 = 王 (ngọc) + 求 (chỉ âm) → vật tròn. 打篮球 = ném bóng vào rổ."},{"char":"因为","pinyin":"yīnwèi","hanviet":"Nhân vi","chars":["因","为"],"story":"因 = 囗 (bao quanh) + 大 (người nằm dang tay trên chiếu) — cái chiếu người ta nằm lên chính là chỗ dựa, từ đó thành \"nguyên do\". 为 nghĩa \"làm, vì\". 因为 = \"vì cái cớ ấy\"."},{"char":"所以","pinyin":"suǒyǐ","hanviet":"Sở dĩ","chars":["所","以"],"story":"所 = 户 (một cánh cửa) + 斤 (cái rìu), gốc chỉ nơi chốn, chỗ. 以 nghĩa \"lấy, dùng\". 所以 = \"cái mà lấy đó làm kết quả\" → cho nên, vì vậy."},{"char":"游泳","pinyin":"yóuyǒng","hanviet":"Du vịnh","chars":["游","泳"],"story":"Cả hai chữ đều mang bộ Thuỷ 氵 vì đều nói về nước. 游 có 斿 chỉ âm, nghĩa \"trôi, đi lại\"; 泳 có 永 (dài lâu) chỉ âm. 游泳 = di chuyển trong nước, tức bơi lội."},{"char":"经常","pinyin":"jīngcháng","hanviet":"Kinh thường","chars":["经","常"],"story":"经 = 纟 (sợi tơ) + 巠, gốc chỉ sợi dọc chạy suốt chiều dài tấm vải. 常 nghĩa \"thường, luôn luôn\". 经常 = kéo dài liên tục không đứt → \"thường xuyên, hay\"."},{"char":"公斤","pinyin":"gōngjīn","hanviet":"Công cân","chars":["公","斤"],"story":"公 = 八 (chia ra) + 厶 (riêng tư): đem của riêng chia ra thành của chung, nên 公 nghĩa \"chung, công\". 斤 vẽ cái rìu, xưa mượn làm đơn vị cân. 公斤 = cân theo chuẩn chung, tức ki-lô-gam."},{"char":"姐姐","pinyin":"jiějie","hanviet":"Tỷ tỷ","chars":["姐","姐"],"story":"姐 = 女 (bộ Nữ, cho biết đây là người thân nữ giới) + 且 qiě (chỉ âm đọc). Tiếng Hán hay lặp chữ để gọi người thân trong nhà: 姐姐, 妈妈, 哥哥, 弟弟."}],"grammar":[{"title":"Đại từ nghi vấn 怎么","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>怎么</b><small>sao lại</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi lý do \"sao lại…?\"</p><ul><li><span class=\"zh\">怎么</span> đứng <b>trước động từ</b> để hỏi <b>nguyên nhân</b>, thường kèm chút ngạc nhiên: <span class=\"zh\">你怎么不吃了？</span></li><li>Phân biệt với <span class=\"zh\">怎么样</span> đã học: <span class=\"zh\">怎么</span> hỏi <b>vì sao</b>, còn <span class=\"zh\">怎么样</span> hỏi <b>tình hình ra sao</b>.</li><li><span class=\"zh\">怎么</span> còn dùng hỏi cách thức \"làm thế nào\": <span class=\"zh\">这个字怎么写？</span></li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">你怎么不吃了？</span> = Sao bạn không ăn nữa?　·　<span class=\"zh\">你怎么知道？</span></p>","note":"<b>Lưu ý:</b> Câu đã có <span class=\"zh\">怎么</span> thì <b>không thêm</b> <span class=\"zh\">吗</span> ở cuối — giống quy tắc của 什么 và 哪儿.","examples":[{"zh":"你怎么不高兴？","py":"Nǐ zěnme bù gāoxìng?","vi":"Sao bạn không vui thế?"},{"zh":"今天怎么这么热？","py":"Jīntiān zěnme zhème rè?","vi":"Sao hôm nay nóng thế này?"},{"zh":"昨天怎么都没去打篮球？","py":"Zuótiān zěnme dōu méi qù dǎ lánqiú?","vi":"Sao hôm qua (mọi người) đều không đi chơi bóng rổ?"}],"exercises":[]},{"title":"Lặp lại lượng từ (量词重叠)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>量词</b><small>lặp lại</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(都)</b><small>đều</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>谓语</b><small>vị ngữ</small></span></div>","summary":"<p class=\"gr-lead\">天天, 个个 = \"cái nào cũng…\"</p><ul><li>Lượng từ lặp lại mang nghĩa <b>\"mọi, từng… đều\"</b>, nhấn rằng không sót cái nào: <span class=\"zh\">天天</span> = ngày nào cũng.</li><li>Hay gặp nhất là <span class=\"zh\">天天</span>; ngoài ra còn <span class=\"zh\">个个</span>, <span class=\"zh\">件件</span>, <span class=\"zh\">人人</span>.</li><li>Phía sau thường thêm <span class=\"zh\">都</span> để nhấn mạnh: <span class=\"zh\">天天都吃羊肉</span>, <span class=\"zh\">人人都知道</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">这个星期天天都吃羊肉。</span> = Tuần này ngày nào cũng ăn thịt dê.</p>","note":"<b>Lưu ý:</b> Dạng lặp <b>không đi kèm số đếm</b>: nói <span class=\"zh\">天天</span>, KHÔNG nói <span class=\"zh\">一天天</span>.","examples":[{"zh":"同学们个个都很高兴。","py":"Tóngxuémen gègè dōu hěn gāoxìng.","vi":"Các bạn học ai nấy đều rất vui."},{"zh":"这个商店的衣服件件都很漂亮。","py":"Zhège shāngdiàn de yīfu jiànjiàn dōu hěn piàoliang.","vi":"Quần áo của cửa hàng này bộ nào cũng rất đẹp."},{"zh":"这个星期（我）天天都吃羊肉。","py":"Zhège xīngqī (wǒ) tiāntiān dōu chī yángròu.","vi":"Tuần này ngày nào (mình) cũng ăn thịt dê."}],"exercises":[]},{"title":"Cặp liên từ 因为……，所以……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>因为</b><small>vì</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>原因</b><small>nguyên nhân</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>所以</b><small>nên</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>结果</b><small>kết quả</small></span></div>","summary":"<p class=\"gr-lead\">Nêu nguyên nhân rồi tới kết quả</p><ul><li>Vế <span class=\"zh\">因为</span> nêu <b>nguyên nhân</b> và đứng trước; vế <span class=\"zh\">所以</span> nêu <b>kết quả</b> và đứng sau.</li><li>Có thể <b>lược bớt một vế</b> — bài khoá chỉ giữ <span class=\"zh\">所以</span>: <span class=\"zh\">昨天下雨，所以我们都没去。</span></li><li>Hai vế cùng chủ ngữ thì chủ ngữ đứng <b>trước</b> <span class=\"zh\">因为</span>; khác chủ ngữ thì đứng <b>sau</b>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">因为昨天下雨，所以我们都没去。</span> = Vì hôm qua trời mưa nên bọn mình đều không đi.</p>","note":"<b>Lưu ý:</b> Tiếng Trung <b>dùng được cả hai</b> liên từ trong một câu — không phải bỏ bớt một cái như tiếng Anh.","examples":[{"zh":"因为她生病了，所以没去学校。","py":"Yīnwèi tā shēngbìng le, suǒyǐ méi qù xuéxiào.","vi":"Vì cô ấy bị ốm nên không đến trường."},{"zh":"因为他每天跑步，所以身体很好。","py":"Yīnwèi tā měi tiān pǎobù, suǒyǐ shēntǐ hěn hǎo.","vi":"Vì ngày nào anh ấy cũng chạy bộ nên sức khoẻ rất tốt."},{"zh":"因为昨天下雨，所以我们都没去打篮球。","py":"Yīnwèi zuótiān xià yǔ, suǒyǐ wǒmen dōu méi qù dǎ lánqiú.","vi":"Vì hôm qua trời mưa nên bọn mình đều không đi chơi bóng rổ."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在学校","titleVi":"Ở trường — hỏi Tiểu Vương đến chưa","lines":[{"speaker":"甲","name":"Bạn A","zh":"你知道小王今天什么时候来学校吗？","py":"Nǐ zhīdào Xiǎo Wáng jīntiān shénme shíhou lái xuéxiào ma?","vi":"Bạn có biết hôm nay Tiểu Vương mấy giờ đến trường không?"},{"speaker":"乙","name":"Bạn B","zh":"他已经来了。","py":"Tā yǐjīng lái le.","vi":"Cậu ấy đến rồi."},{"speaker":"甲","name":"Bạn A","zh":"你怎么知道他来了？","py":"Nǐ zěnme zhīdào tā lái le?","vi":"Sao bạn biết cậu ấy đến rồi?"},{"speaker":"乙","name":"Bạn B","zh":"我在门外看见他的自行车了。","py":"Wǒ zài mén wài kànjiàn tā de zìxíngchē le.","vi":"Mình nhìn thấy xe đạp của cậu ấy ở ngoài cửa."}]},{"titleZh":"课文二 · 在饭馆","titleVi":"Ở quán ăn — sao bỗng không ăn nữa","lines":[{"speaker":"甲","name":"Bạn A","zh":"今天的羊肉很好吃，你怎么不吃了？","py":"Jīntiān de yángròu hěn hǎochī, nǐ zěnme bù chī le?","vi":"Thịt dê hôm nay ngon lắm, sao bạn không ăn nữa?"},{"speaker":"乙","name":"Bạn B","zh":"这个星期天天都吃羊肉，不想吃了。","py":"Zhège xīngqī tiāntiān dōu chī yángròu, bù xiǎng chī le.","vi":"Tuần này ngày nào cũng ăn thịt dê, mình không muốn ăn nữa."},{"speaker":"甲","name":"Bạn A","zh":"你还想吃什么？","py":"Nǐ hái xiǎng chī shénme?","vi":"Vậy bạn còn muốn ăn gì?"},{"speaker":"乙","name":"Bạn B","zh":"来一点面条吧。","py":"Lái yìdiǎn miàntiáo ba.","vi":"Cho một ít mì đi."}]},{"titleZh":"课文三 · 在健身房","titleVi":"Ở phòng tập — vì sao hôm qua vắng","lines":[{"speaker":"甲","name":"Bạn A","zh":"昨天你们怎么都没去打篮球？","py":"Zuótiān nǐmen zěnme dōu méi qù dǎ lánqiú?","vi":"Hôm qua sao các bạn đều không đi chơi bóng rổ?"},{"speaker":"乙","name":"Bạn B","zh":"昨天下雨，所以我们都没去，我去游泳了。","py":"Zuótiān xià yǔ, suǒyǐ wǒmen dōu méi qù, wǒ qù yóuyǒng le.","vi":"Hôm qua trời mưa nên bọn mình đều không đi, mình đi bơi."},{"speaker":"甲","name":"Bạn A","zh":"你经常游泳吗？","py":"Nǐ jīngcháng yóuyǒng ma?","vi":"Bạn có hay đi bơi không?"},{"speaker":"乙","name":"Bạn B","zh":"这个月我天天游泳，我现在70公斤了。","py":"Zhège yuè wǒ tiāntiān yóuyǒng, wǒ xiànzài qīshí gōngjīn le.","vi":"Tháng này ngày nào mình cũng bơi, giờ mình bảy mươi cân rồi."}]},{"titleZh":"课文四 · 在办公室","titleVi":"Ở văn phòng — Tiểu Trương đi đâu","lines":[{"speaker":"甲","name":"Bạn A","zh":"这两天怎么没看见小张？","py":"Zhè liǎng tiān zěnme méi kànjiàn Xiǎo Zhāng?","vi":"Mấy hôm nay sao không thấy Tiểu Trương nhỉ?"},{"speaker":"乙","name":"Bạn B","zh":"他去北京了。","py":"Tā qù Běijīng le.","vi":"Cậu ấy đi Bắc Kinh rồi."},{"speaker":"甲","name":"Bạn A","zh":"去北京了？是去旅游吗？","py":"Qù Běijīng le? Shì qù lǚyóu ma?","vi":"Đi Bắc Kinh à? Đi du lịch hả?"},{"speaker":"乙","name":"Bạn B","zh":"不是，听说是去看她姐姐。","py":"Bú shì, tīngshuō shì qù kàn tā jiějie.","vi":"Không phải, nghe nói là đi thăm chị gái cô ấy."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"逻辑重音","grpVi":"Trọng âm logic của câu","introZh":"一个句子中，说话人想要表达比较重要的信息或者内容，往往要说得重一些，这个重读的成分就叫作逻辑重音。逻辑重音又叫强调重音。","introVi":"Khi nói, người ta thường nhấn mạnh đôi chút nếu đề cập đến thông tin hay nội dung tương đối quan trọng. Thành phần được nhấn mạnh này có tên gọi là trọng âm logic (hay trọng âm nhấn mạnh).","zh":"语境不同，重音不同","py":"","tag":"Trọng âm logic","vi":"Ngữ cảnh khác → nhấn khác","listZh":"(1) 不同语境中的逻辑重音","listVi":"Trong các ngữ cảnh khác nhau, trọng âm logic xuất hiện ở những vị trí khác nhau","descZh":"在不同语境中，逻辑重音出现在不同的位置。","descVi":"Trong các ngữ cảnh khác nhau, trọng âm logic xuất hiện ở những vị trí khác nhau.","arrow":true,"pat":[{"l":"问：谁？哪儿？","s":"câu hỏi hỏi về gì"},{"l":"答：重读答案","s":"nhấn đúng phần trả lời","st":true}],"tip":"Hỏi <span class=\"zh\">谁</span> → nhấn <span class=\"zh\">他</span> · hỏi <span class=\"zh\">哪儿</span> → nhấn <span class=\"zh\">房间</span>: câu trả lời nhấn vào <b>thông tin mới</b>.","sents":[{"lines":[{"who":"A","w":[{"hz":"谁","py":"Shéi"},{"hz":"在","py":"zài"},{"hz":"房间","py":"fángjiān"},{"hz":"学习","py":"xuéxí"},{"hz":"汉语","py":"Hànyǔ"},{"hz":"呢？","py":"ne?"}],"vi":"Ai đang học tiếng Trung trong phòng thế?"},{"who":"B","w":[{"hz":"他","py":"Tā","st":true},{"hz":"在","py":"zài","j":true},{"hz":"房间","py":"fángjiān"},{"hz":"学习","py":"xuéxí"},{"hz":"汉语","py":"Hànyǔ"},{"hz":"呢。","py":"ne."}],"vi":"Anh ấy đang học tiếng Trung trong phòng."}]},{"lines":[{"who":"A","w":[{"hz":"他","py":"Tā"},{"hz":"在","py":"zài","j":true},{"hz":"哪儿","py":"nǎr","j":true},{"hz":"学习","py":"xuéxí","j":true},{"hz":"汉语","py":"Hànyǔ"},{"hz":"呢？","py":"ne?"}],"vi":"Anh ấy đang học tiếng Trung ở đâu thế?"},{"who":"B","w":[{"hz":"他","py":"Tā"},{"hz":"在","py":"zài","j":true},{"hz":"房间","py":"fángjiān","st":true},{"hz":"学习","py":"xuéxí"},{"hz":"汉语","py":"Hànyǔ"},{"hz":"呢。","py":"ne."}],"vi":"Anh ấy đang học tiếng Trung trong phòng."}]}]},{"id":"pa-02","grp":"逻辑重音","grpVi":"Trọng âm logic của câu","zh":"重音不同，语义不同","py":"","tag":"Trọng âm logic","vi":"Một câu · nhấn khác → nghĩa khác","listZh":"(2) 同一句话，重音不同","listVi":"Trọng âm logic ở vị trí khác nhau → trọng tâm ngữ nghĩa của câu cũng thay đổi","descZh":"同样一句话，逻辑重音的位置不同，语义的重点也会发生变化。","descVi":"Trọng tâm ngữ nghĩa của câu cũng sẽ có sự thay đổi khi trọng âm logic ở các vị trí khác nhau.","arrow":true,"pat":[{"l":"重音位置","s":"nhấn vào chỗ nào"},{"l":"语义重点","s":"trọng tâm nghĩa ở đó","st":true}],"tip":"Nhấn chữ nào là <b>khẳng định chính điều đó</b>, ngầm phủ định khả năng khác: nhấn <span class=\"zh\">他</span> → không phải người khác · nhấn <span class=\"zh\">房间</span> → không phải nơi khác.","sents":[{"lines":[{"who":"A","w":[{"hz":"他","py":"Tā","st":true},{"hz":"在","py":"zài","j":true},{"hz":"房间","py":"fángjiān"},{"hz":"学习","py":"xuéxí"},{"hz":"汉语","py":"Hànyǔ"},{"hz":"呢。","py":"ne."}],"exZh":"是他在房间学习汉语，不是别的人。","vi":"Người đang học tiếng Trung trong phòng là anh ấy chứ không phải người khác."}]},{"lines":[{"who":"B","w":[{"hz":"他","py":"Tā"},{"hz":"在","py":"zài","j":true},{"hz":"房间","py":"fángjiān","st":true},{"hz":"学习","py":"xuéxí"},{"hz":"汉语","py":"Hànyǔ"},{"hz":"呢。","py":"ne."}],"exZh":"他是在房间学习汉语，不是在别的地方。","vi":"Anh ấy đang học tiếng Trung trong phòng chứ không phải ở nơi khác."}]}]}],"activity":{"act":[],"speak":[{"zh":"口语练习","py":"kǒuyǔ liànxí","tag":"Luyện nói","mean":"Chuẩn bị · Trình bày","prep":3,"talk":2,"q":{"zh":"你认为生活中最重要的是什么？为什么？","py":"Nǐ rènwéi shēnghuó zhōng zuì zhòngyào de shì shénme? Wèi shénme?","vi":"Theo bạn, điều quan trọng nhất trong cuộc sống là gì? Tại sao?"},"frame":[{"lbl":"Mở bài","zh":"我认为生活中最重要的是……。","py":"Wǒ rènwéi shēnghuó zhōng zuì zhòngyào de shì …….","vi":"Mình cho rằng điều quan trọng nhất trong cuộc sống là … .","ex":{"zh":"我认为生活中最重要的是身体。","py":"Wǒ rènwéi shēnghuó zhōng zuì zhòngyào de shì shēntǐ.","vi":"Mình cho rằng điều quan trọng nhất trong cuộc sống là sức khoẻ."}},{"lbl":"Thân bài · Lí do 1","zh":"第一，因为……，所以……。","py":"Dì yī, yīnwèi ……, suǒyǐ …….","vi":"Thứ nhất, vì … nên … .","ex":{"zh":"第一，因为身体好，所以每天都能工作、学习。","py":"Dì yī, yīnwèi shēntǐ hǎo, suǒyǐ měi tiān dōu néng gōngzuò, xuéxí.","vi":"Thứ nhất, vì sức khoẻ tốt nên ngày nào cũng có thể làm việc, học tập."}},{"lbl":"Thân bài · Lí do 2","zh":"第二，因为……，所以……。","py":"Dì èr, yīnwèi ……, suǒyǐ …….","vi":"Thứ hai, vì … nên … .","ex":{"zh":"第二，因为身体好，所以可以和家人一起去旅游。","py":"Dì èr, yīnwèi shēntǐ hǎo, suǒyǐ kěyǐ hé jiārén yìqǐ qù lǚyóu.","vi":"Thứ hai, vì sức khoẻ tốt nên có thể cùng gia đình đi du lịch."}},{"lbl":"Kết bài","zh":"所以，我觉得……最重要。","py":"Suǒyǐ, wǒ juéde …… zuì zhòngyào.","vi":"Vì vậy, mình thấy … là quan trọng nhất.","ex":{"zh":"所以，我觉得身体最重要。我每天都去跑步。","py":"Suǒyǐ, wǒ juéde shēntǐ zuì zhòngyào. Wǒ měi tiān dōu qù pǎobù.","vi":"Vì vậy, mình thấy sức khoẻ là quan trọng nhất. Ngày nào mình cũng đi chạy bộ."}}]}]}},{"id":"k2v2-b07","courseId":"k2v2","order":7,"title":"Nhà chị có ở xa công ty không?","titleZh":"你家离公司远吗？","titlePy":"nǐ jiā lí gōngsī yuǎn ma","vocab":[{"stt":1,"hanzi":"教室","pinyin":"jiàoshì","hanviet":"Giáo thất","pos":"Danh từ","meaning":"phòng học, lớp học","comps":"在教室 (ở trong lớp), 教室里 (bên trong lớp học)","example":{"zh":"他还在教室学习呢。","py":"Tā hái zài jiàoshì xuéxí ne.","vi":"Cậu ấy vẫn còn đang học ở lớp."}},{"stt":2,"hanzi":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","pos":"Danh từ","meaning":"sân bay","comps":"去机场 (đi ra sân bay), 到机场 (đến sân bay)","example":{"zh":"我在去机场的路上。","py":"Wǒ zài qù jīchǎng de lùshang.","vi":"Tôi đang trên đường ra sân bay."}},{"stt":3,"hanzi":"路","pinyin":"lù","hanviet":"Lộ","pos":"Danh từ","meaning":"đường, đường đi","comps":"路上 (trên đường), 走路 (đi bộ)","example":{"zh":"路上的车太多了。","py":"Lùshang de chē tài duō le.","vi":"Xe trên đường đông quá."}},{"stt":4,"hanzi":"离","pinyin":"lí","hanviet":"Ly","pos":"Giới từ","meaning":"cách, cách xa","comps":"离这儿 (cách đây), 离开 (rời khỏi)","example":{"zh":"我家离公司很远。","py":"Wǒ jiā lí gōngsī hěn yuǎn.","vi":"Nhà tôi cách công ty rất xa."}},{"stt":5,"hanzi":"公司","pinyin":"gōngsī","hanviet":"Công ty","pos":"Danh từ","meaning":"công ty","comps":"去公司 (đến công ty), 在公司 (ở công ty)","example":{"zh":"你家离公司远吗？","py":"Nǐ jiā lí gōngsī yuǎn ma?","vi":"Nhà bạn cách công ty có xa không?"}},{"stt":6,"hanzi":"远","pinyin":"yuǎn","hanviet":"Viễn","pos":"Tính từ","meaning":"xa","comps":"很远 (rất xa), 不远 (không xa)","example":{"zh":"离这儿不远。","py":"Lí zhèr bù yuǎn.","vi":"Cách đây không xa."}},{"stt":7,"hanzi":"公共汽车","pinyin":"gōnggòng qìchē","hanviet":"Công cộng khí xa","pos":"Danh từ","meaning":"xe buýt","comps":"坐公共汽车 (đi xe buýt), 等公共汽车 (đợi xe buýt)","example":{"zh":"我坐公共汽车去公司。","py":"Wǒ zuò gōnggòng qìchē qù gōngsī.","vi":"Tôi đi xe buýt đến công ty."}},{"stt":8,"hanzi":"小时","pinyin":"xiǎoshí","hanviet":"Tiểu thời","pos":"Danh từ","meaning":"tiếng, giờ đồng hồ","comps":"一个小时 (một tiếng), 半个小时 (nửa tiếng)","example":{"zh":"坐车要一个多小时。","py":"Zuò chē yào yí ge duō xiǎoshí.","vi":"Đi xe mất hơn một tiếng."}},{"stt":9,"hanzi":"慢","pinyin":"màn","hanviet":"Mạn","pos":"Tính từ","meaning":"chậm","comps":"很慢 (rất chậm), 慢走 (đi thong thả nhé)","example":{"zh":"坐公共汽车太慢了。","py":"Zuò gōnggòng qìchē tài màn le.","vi":"Đi xe buýt chậm quá."}},{"stt":10,"hanzi":"快","pinyin":"kuài","hanviet":"Khoái","pos":"Tính từ","meaning":"nhanh, mau","comps":"很快 (rất nhanh), 快点儿 (nhanh lên)","example":{"zh":"开车也不快。","py":"Kāichē yě bú kuài.","vi":"Lái xe cũng không nhanh."}},{"stt":11,"hanzi":"过","pinyin":"guò","hanviet":"Quá","pos":"Động từ","meaning":"qua; tổ chức, đón","comps":"过生日 (tổ chức sinh nhật), 过年 (đón Tết)","example":{"zh":"今天晚上给你过生日。","py":"Jīntiān wǎnshang gěi nǐ guò shēngrì.","vi":"Tối nay tổ chức sinh nhật cho bạn."}},{"stt":12,"hanzi":"走","pinyin":"zǒu","hanviet":"Tẩu","pos":"Động từ","meaning":"đi, đi bộ; rời đi","comps":"走路 (đi bộ), 走吧 (đi thôi)","example":{"zh":"我们走几分钟就到了。","py":"Wǒmen zǒu jǐ fēnzhōng jiù dào le.","vi":"Chúng ta đi bộ mấy phút là tới."}},{"stt":13,"hanzi":"到","pinyin":"dào","hanviet":"Đáo","pos":"Động từ","meaning":"đến, tới","comps":"到了 (đến rồi), 到公司 (tới công ty)","example":{"zh":"二十分钟就到。","py":"Èrshí fēnzhōng jiù dào.","vi":"Hai mươi phút là tới ngay."}}],"hanzi":[{"char":"教室","pinyin":"jiàoshì","hanviet":"Giáo thất","chars":["教","室"],"story":"教 gồm 孝 (hiếu, chỉ âm) và 攵 (bộ Phốc — bàn tay cầm cây roi) nên nghĩa là dạy dỗ. 室 gồm 宀 (mái nhà) và 至 (đến nơi) nên nghĩa là căn phòng. 教室 là căn phòng dùng để dạy học, tức lớp học."},{"char":"机场","pinyin":"jīchǎng","hanviet":"Cơ trường","chars":["机","场"],"story":"机 gồm 木 (gỗ) và 几 (chỉ âm), vốn chỉ đồ làm bằng gỗ, nay là máy móc — ở đây là dạng rút gọn của 飞机. 场 gồm 土 (đất) và phần chỉ âm, nghĩa là bãi đất rộng. 机场 là bãi đất rộng dành cho máy bay."},{"char":"路","pinyin":"lù","hanviet":"Lộ","chars":["路"],"story":"路 gồm 足 (bộ Túc — bàn chân) chỉ nghĩa và 各 gè chỉ âm. Bộ chân cho biết chữ này nói về chỗ để chân bước qua, nên 路 nghĩa là con đường."},{"char":"离","pinyin":"lí","hanviet":"Ly","chars":["离"],"story":"离 nghĩa gốc là chia lìa, rời xa (như 离开 = rời khỏi). Từ ý \"rời xa\" mà 离 thành giới từ đo khoảng cách giữa hai nơi: A 离 B 远 nghĩa là A cách B xa."},{"char":"公司","pinyin":"gōngsī","hanviet":"Công ty","chars":["公","司"],"story":"公 gồm 八 (chia ra) và 厶 (riêng tư) — chia cái riêng thành của chung, nên 公 nghĩa là chung, công. 司 nghĩa là trông coi, quản lý. 公司 là tổ chức làm ăn chung, tức công ty."},{"char":"远","pinyin":"yuǎn","hanviet":"Viễn","chars":["远"],"story":"远 gồm 辶 (bộ Sước — bước chân đi trên đường) chỉ nghĩa và 元 yuán chỉ âm. Bộ Sước cho biết chữ này nói về đường đi: đi mãi mới tới, nên nghĩa là xa. Trái nghĩa là 近 jìn (gần)."},{"char":"公共汽车","pinyin":"gōnggòng qìchē","hanviet":"Công cộng khí xa","chars":["公","共","汽","车"],"story":"公 (chung) ghép 共 (cùng) thành 公共 = công cộng, của mọi người. 汽 gồm 氵 (nước) và 气 (hơi) nên nghĩa là hơi nước — xe thời xưa chạy bằng hơi nước. 车 vẽ hình chiếc xe nhìn từ trên xuống. Cả cụm là chiếc xe cho mọi người cùng đi — xe buýt."},{"char":"小时","pinyin":"xiǎoshí","hanviet":"Tiểu thời","chars":["小","时"],"story":"小 (nhỏ) ghép 时 (thời gian). Người xưa chia một ngày thành 12 时辰; sau này theo cách chia phương Tây thành 24 phần nhỏ hơn nên gọi là 小时 — \"giờ nhỏ\", tức một tiếng đồng hồ."},{"char":"慢","pinyin":"màn","hanviet":"Mạn","chars":["慢"],"story":"慢 gồm 忄 (bộ Tâm — trái tim) chỉ nghĩa và 曼 màn chỉ âm. Bộ Tâm cho biết chữ tả trạng thái trong lòng: lòng thong thả, không vội vã, nên 慢 nghĩa là chậm."},{"char":"快","pinyin":"kuài","hanviet":"Khoái","chars":["快"],"story":"快 gồm 忄 (bộ Tâm) và 夬 guài chỉ âm. Cùng bộ Tâm với 慢 nhưng ngược nghĩa: trong lòng dứt khoát, mau lẹ — nên 快 nghĩa là nhanh, và cũng có nghĩa vui (愉快)."},{"char":"过","pinyin":"guò","hanviet":"Quá","chars":["过"],"story":"过 gồm 辶 (bộ Sước — bước chân) và 寸 (tấc). Bước chân đi qua một chỗ nên nghĩa gốc là \"đi qua\"; từ đó sinh ra nghĩa trải qua, đón một dịp: 过生日, 过年."},{"char":"走","pinyin":"zǒu","hanviet":"Tẩu","chars":["走"],"story":"走 vốn vẽ hình một người vung tay (phần trên) đặt trên bộ 止 (bàn chân) — dáng người đang bước. Tiếng Trung cổ 走 nghĩa là chạy, ngày nay nghĩa là đi bộ, rời đi."},{"char":"到","pinyin":"dào","hanviet":"Đáo","chars":["到"],"story":"到 gồm 至 (hình mũi tên cắm xuống đất, nghĩa là đến nơi) chỉ nghĩa và 刂 (bộ Đao) chỉ âm. Vì vậy 到 nghĩa là đến, tới đích."}],"grammar":[{"title":"Phó từ 还 (nghĩa 2 — \"vẫn, còn\")","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>还</b><small>vẫn, còn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>谓语</b><small>vị ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(呢)</b><small>trợ từ cuối câu</small></span></div>","summary":"<p class=\"gr-lead\">还 = \"vẫn, còn\" — việc chưa kết thúc</p><ul><li>Bài 5 đã học <span class=\"zh\">还</span> nghĩa \"cũng khá, tạm được\" (<span class=\"zh\">还可以</span>). Ở đây <span class=\"zh\">还</span> nghĩa <b>\"vẫn, còn\"</b> — việc chưa kết thúc.</li><li><span class=\"zh\">还</span> đứng <b>ngay trước động từ hoặc tính từ</b>, rất hay đi cùng <span class=\"zh\">呢</span> ở cuối câu.</li><li>Ghép với <span class=\"zh\">有</span> để nói phần <b>còn lại</b>: <span class=\"zh\">还有二十分钟</span>, <span class=\"zh\">还有一个多星期</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">他还在教室学习呢。</span>　·　<span class=\"zh\">离我的生日还有一个多星期。</span></p>","note":"<b>Lưu ý:</b> Đừng lẫn <span class=\"zh\">还</span> (vẫn còn — việc <b>đang</b> diễn ra) với <span class=\"zh\">再</span> (lại, lần nữa — việc <b>chưa</b> diễn ra).","examples":[{"zh":"八点了，他还在睡觉。","py":"Bā diǎn le, tā hái zài shuìjiào.","vi":"Tám giờ rồi mà anh ấy vẫn còn đang ngủ."},{"zh":"你怎么还没吃饭？","py":"Nǐ zěnme hái méi chīfàn?","vi":"Sao bạn vẫn chưa ăn cơm?"},{"zh":"他还在教室学习呢。","py":"Tā hái zài jiàoshì xuéxí ne.","vi":"Cậu ấy vẫn còn đang học ở lớp."}],"exercises":[]},{"title":"Phó từ 就","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>时间 / 数量</b><small>thời gian, số lượng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>就</b><small>là… ngay</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(了)</b><small>trợ từ</small></span></div>","summary":"<p class=\"gr-lead\">Nhấn mạnh nhanh, sớm, dễ dàng</p><ul><li>Bài 5 đã gặp <span class=\"zh\">就</span> trong <span class=\"zh\">就买这件吧</span> (thì, vậy thì). Ở đây <span class=\"zh\">就</span> nhấn mạnh việc xảy ra <b>nhanh, sớm, dễ dàng</b>.</li><li>Phía trước <span class=\"zh\">就</span> thường có <b>từ chỉ thời gian hoặc số lượng ít</b>: <span class=\"zh\">二十分钟</span>, <span class=\"zh\">几分钟</span>.</li><li>Ý ngầm là \"chỉ cần chừng đó thôi là xong\" — người nói thấy nhanh hơn người nghe tưởng.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">二十分钟就到。</span>　·　<span class=\"zh\">我们走几分钟就到了。</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">就</span> <b>luôn đứng ngay trước động từ</b>, không đứng cuối câu và không đứng trước chủ ngữ.","examples":[{"zh":"同学们七点半就来教室了。","py":"Tóngxuémen qī diǎn bàn jiù lái jiàoshì le.","vi":"Mới bảy rưỡi các bạn đã đến lớp rồi."},{"zh":"我坐飞机一个半小时就到北京了。","py":"Wǒ zuò fēijī yí ge bàn xiǎoshí jiù dào Běijīng le.","vi":"Tôi đi máy bay một tiếng rưỡi là đến Bắc Kinh rồi."},{"zh":"（我）二十分钟就到。","py":"(Wǒ) èrshí fēnzhōng jiù dào.","vi":"(Tôi) hai mươi phút nữa là tới ngay."}],"exercises":[]},{"title":"Giới từ 离","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>nơi thứ nhất</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>离</b><small>cách</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>nơi thứ hai</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>远 / 近</b><small>xa / gần</small></span></div>","summary":"<p class=\"gr-lead\">Nói A cách B xa hay gần</p><ul><li><span class=\"zh\">离</span> đo <b>khoảng cách giữa hai nơi</b>, phía sau là tính từ <span class=\"zh\">远</span> hoặc <span class=\"zh\">近</span>.</li><li>Hỏi bằng <span class=\"zh\">…远吗？</span>; trả lời <span class=\"zh\">很远</span> / <span class=\"zh\">不远</span> / <span class=\"zh\">不太远</span>.</li><li><span class=\"zh\">离</span> còn đo <b>thời gian còn lại</b> tới một mốc: <span class=\"zh\">离我的生日还有一个多星期。</span></li></ul>","note":"<b>Lưu ý:</b> Phân biệt với <span class=\"zh\">从</span>: <span class=\"zh\">离</span> nói <b>khoảng cách</b>, còn <span class=\"zh\">从</span> nói <b>điểm xuất phát</b> (<span class=\"zh\">从家到公司</span>).","examples":[{"zh":"你家离公司远吗？","py":"Nǐ jiā lí gōngsī yuǎn ma?","vi":"Nhà bạn cách công ty có xa không?"}],"exercises":[]},{"title":"Trợ từ ngữ khí 呢","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(还) 在</b><small>vẫn đang</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>谓语</b><small>vị ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>呢</b><small>trợ từ nhấn mạnh</small></span></div>","summary":"<p class=\"gr-lead\">Nhấn mạnh việc đang diễn ra</p><ul><li>Bài 9 và Bài 13 đã học <span class=\"zh\">呢</span> hỏi ngắn (<span class=\"zh\">你呢？</span>) và <span class=\"zh\">在……呢</span> (đang làm gì). Ở đây <span class=\"zh\">呢</span> để <b>nhấn mạnh</b>.</li><li>Cuối câu trần thuật, <span class=\"zh\">呢</span> nhấn mạnh mức độ <b>nhiều, lâu, xa</b> hơn người nghe tưởng: <span class=\"zh\">要一个多小时呢！</span></li><li>Cuối câu hỏi, <span class=\"zh\">呢</span> làm giọng <b>mềm và thân mật</b> hơn: <span class=\"zh\">你现在在哪儿呢？</span></li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">他还在教室学习呢。</span>　·　<span class=\"zh\">坐公共汽车要一个多小时呢！</span></p>","note":"<b>Lưu ý:</b> <span class=\"zh\">呢</span> <b>không phải</b> <span class=\"zh\">吗</span>: <span class=\"zh\">吗</span> biến câu trần thuật thành câu hỏi, còn <span class=\"zh\">呢</span> chỉ thêm sắc thái.","examples":[{"zh":"八点上课，时间还早呢。","py":"Bā diǎn shàngkè, shíjiān hái zǎo ne.","vi":"Tám giờ mới vào học, vẫn còn sớm mà."},{"zh":"医院离我们这儿还远呢。","py":"Yīyuàn lí wǒmen zhèr hái yuǎn ne.","vi":"Bệnh viện còn cách chỗ chúng ta xa lắm."},{"zh":"坐公共汽车要一个多小时呢！","py":"Zuò gōnggòng qìchē yào yí ge duō xiǎoshí ne!","vi":"Đi xe buýt mất hơn một tiếng cơ đấy!"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — hỏi vì sao Đại Vệ chưa về","lines":[{"speaker":"甲","name":"Bạn A","zh":"大卫回来了吗？","py":"Dàwèi huílai le ma?","vi":"Đại Vệ về chưa?"},{"speaker":"乙","name":"Bạn B","zh":"没有，他还在教室学习呢。","py":"Méiyǒu, tā hái zài jiàoshì xuéxí ne.","vi":"Chưa. Cậu ấy vẫn còn đang học ở lớp."},{"speaker":"甲","name":"Bạn A","zh":"已经9:00多了，他怎么还在学习？","py":"Yǐjīng jiǔ diǎn duō le, tā zěnme hái zài xuéxí?","vi":"Hơn 9 giờ rồi, sao cậu ấy vẫn còn học thế?"},{"speaker":"乙","name":"Bạn B","zh":"明天有考试，他说今天要好好准备。","py":"Míngtiān yǒu kǎoshì, tā shuō jīntiān yào hǎohāo zhǔnbèi.","vi":"Mai có bài kiểm tra, cậu ấy bảo hôm nay phải chuẩn bị cho kỹ."}]},{"titleZh":"课文二 · 在机场的路上","titleVi":"Ra sân bay đón — gọi điện cho nhau","lines":[{"speaker":"甲","name":"Bạn A","zh":"你现在在哪儿呢？","py":"Nǐ xiànzài zài nǎr ne?","vi":"Cậu đang ở đâu đấy?"},{"speaker":"乙","name":"Bạn B","zh":"在去机场的路上。你已经到了吗？","py":"Zài qù jīchǎng de lùshang. Nǐ yǐjīng dào le ma?","vi":"Tớ đang trên đường ra sân bay. Cậu tới rồi à?"},{"speaker":"甲","name":"Bạn A","zh":"我下飞机了。你还有多长时间能到这儿？","py":"Wǒ xià fēijī le. Nǐ hái yǒu duō cháng shíjiān néng dào zhèr?","vi":"Tớ xuống máy bay rồi. Còn bao lâu nữa cậu mới tới được đây?"},{"speaker":"乙","name":"Bạn B","zh":"20分钟就到。","py":"Èrshí fēnzhōng jiù dào.","vi":"Hai mươi phút nữa là tới ngay."}]},{"titleZh":"课文三 · 在健身房","titleVi":"Ở phòng gym — nói về đường đi làm","lines":[{"speaker":"甲","name":"Bạn A","zh":"你家离公司远吗？","py":"Nǐ jiā lí gōngsī yuǎn ma?","vi":"Nhà cậu cách công ty có xa không?"},{"speaker":"乙","name":"Bạn B","zh":"很远，坐公共汽车要一个多小时呢！","py":"Hěn yuǎn, zuò gōnggòng qìchē yào yí ge duō xiǎoshí ne!","vi":"Xa lắm, đi xe buýt mất hơn một tiếng cơ!"},{"speaker":"甲","name":"Bạn A","zh":"坐公共汽车太慢了，你怎么不开车？","py":"Zuò gōnggòng qìchē tài màn le, nǐ zěnme bù kāichē?","vi":"Đi xe buýt chậm quá, sao cậu không lái xe?"},{"speaker":"乙","name":"Bạn B","zh":"开车也不快，路上的车太多了！","py":"Kāichē yě bú kuài, lùshang de chē tài duō le!","vi":"Lái xe cũng chẳng nhanh, xe trên đường đông quá!"}]},{"titleZh":"课文四 · 在路上","titleVi":"Trên đường — rủ đi ăn sinh nhật sớm","lines":[{"speaker":"甲","name":"Bạn A","zh":"今天晚上我们一起吃饭吧，给你过生日。","py":"Jīntiān wǎnshang wǒmen yìqǐ chīfàn ba, gěi nǐ guò shēngrì.","vi":"Tối nay chúng mình đi ăn với nhau nhé, mừng sinh nhật cậu."},{"speaker":"乙","name":"Bạn B","zh":"今天？离我的生日还有一个多星期呢！","py":"Jīntiān? Lí wǒ de shēngrì hái yǒu yí ge duō xīngqī ne!","vi":"Hôm nay á? Còn hơn một tuần nữa mới tới sinh nhật tớ cơ mà!"},{"speaker":"甲","name":"Bạn A","zh":"下个星期我要去北京，今天过吧。","py":"Xià ge xīngqī wǒ yào qù Běijīng, jīntiān guò ba.","vi":"Tuần sau tớ phải đi Bắc Kinh, thôi mừng luôn hôm nay đi."},{"speaker":"乙","name":"Bạn B","zh":"好吧，离这儿不远，有一个中国饭馆，我们走几分钟就到了。","py":"Hǎo ba, lí zhèr bù yuǎn, yǒu yí ge Zhōngguó fànguǎn, wǒmen zǒu jǐ fēnzhōng jiù dào le.","vi":"Được thôi, cách đây không xa có một quán ăn Trung Quốc, đi bộ mấy phút là tới."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu cơ bản của câu tiếng Trung","introZh":"汉语的基本句调有两种：升调和降调。一般来说，疑问句读升调，陈述句读降调。","introVi":"Trong tiếng Trung Quốc, câu có hai loại ngữ điệu cơ bản: lên giọng và xuống giọng. Thông thường, câu hỏi có ngữ điệu lên giọng và câu trần thuật có ngữ điệu xuống giọng.","zh":"汉语的基本句调","py":"","tag":"Ngữ điệu","vi":"Lên giọng ↗ · Xuống giọng ↘","listZh":"升调和降调","listVi":"Câu hỏi lên giọng ↗ · câu trần thuật xuống giọng ↘","descZh":"一般来说，疑问句读升调，陈述句读降调。","descVi":"Thông thường, câu hỏi lên giọng, câu trần thuật xuống giọng.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"疑问句","s":"câu hỏi"},{"l":"升调 ↗","s":"lên giọng","st":true}],[{"l":"陈述句","s":"câu trần thuật"},{"l":"降调 ↘","s":"xuống giọng","dn":true}]],"tip":"Cùng một câu: cuối câu <b>lên giọng ↗</b> → câu hỏi · <b>xuống giọng ↘</b> → câu trần thuật. Thanh điệu từng chữ giữ nguyên (<span class=\"zh\">张</span> vẫn thanh 1).","readLbl":"Luyện đọc · ↗ lên giọng · ↘ xuống giọng","sents":[{"tone":"up","w":[{"hz":"他","py":"Tā"},{"hz":"姓","py":"xìng"},{"hz":"张？","py":"Zhāng?"}],"vi":"Anh ấy họ Trương à?"},{"tone":"down","w":[{"hz":"他","py":"Tā"},{"hz":"姓","py":"xìng"},{"hz":"张。","py":"Zhāng."}],"vi":"Anh ấy họ Trương."},{"tone":"up","w":[{"hz":"他不","py":"Tā bù"},{"hz":"喜欢","py":"xǐhuan"},{"hz":"喝啤酒？","py":"hē píjiǔ?"}],"vi":"Anh ấy không thích uống bia à?"},{"tone":"down","w":[{"hz":"他不","py":"Tā bù"},{"hz":"喜欢","py":"xǐhuan"},{"hz":"喝啤酒。","py":"hē píjiǔ."}],"vi":"Anh ấy không thích uống bia."}]}],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"","q":{"zh":"两人一组，说说你常去的地方，你怎么去那儿？","py":"Liǎng rén yì zǔ, shuōshuo nǐ cháng qù de dìfang, nǐ zěnme qù nàr?","vi":"Hai người một cặp, kể về những nơi bạn hay đến và bạn đến đó bằng cách nào."},"items":[],"pattern":{"parts":[{"slot":"Địa điểm A"},{"zh":"离","py":"lí"},{"slot":"Địa điểm B"},{"zh":"非常远","py":"fēicháng yuǎn"},{"zh":"，","py":""},{"zh":"我","py":"wǒ"},{"slot":"Phương tiện"},{"zh":"去","py":"qù"},{"slot":"Địa điểm A"},{"zh":"。","py":""}],"vi":"[Địa điểm A] cách [Địa điểm B] rất xa, tôi [Phương tiện] đến [Địa điểm A]."},"banks":[{"lbl":"Địa điểm A","zh":"地点","items":[{"zh":"学校","py":"xuéxiào","vi":"trường học"},{"zh":"饭馆","py":"fànguǎn","vi":"quán ăn"},{"zh":"商店","py":"shāngdiàn","vi":"cửa hàng"},{"zh":"医院","py":"yīyuàn","vi":"bệnh viện"},{"zh":"公司","py":"gōngsī","vi":"công ty"},{"zh":"机场","py":"jīchǎng","vi":"sân bay"},{"zh":"火车站","py":"huǒchēzhàn","vi":"ga tàu hoả"},{"zh":"宾馆","py":"bīnguǎn","vi":"khách sạn"}]},{"lbl":"Địa điểm B","zh":"地点","items":[{"zh":"我家","py":"wǒ jiā","vi":"nhà tôi"},{"zh":"你家","py":"nǐ jiā","vi":"nhà bạn"},{"zh":"这儿","py":"zhèr","vi":"chỗ này"}]},{"lbl":"Phương tiện","zh":"交通","items":[{"zh":"飞机","py":"fēijī","vi":"đi máy bay"},{"zh":"自行车","py":"zìxíngchē","vi":"đi xe đạp"},{"zh":"出租车","py":"chūzūchē","vi":"đi taxi"},{"zh":"公共汽车","py":"gōnggòng qìchē","vi":"đi xe buýt"},{"zh":"走路","py":"zǒulù","vi":"đi bộ"},{"zh":"摩托车","py":"mótuōchē","vi":"đi xe máy"},{"zh":"开车","py":"kāichē","vi":"lái xe"}]}]}],"speak":[]}},{"id":"k2v2-b08","courseId":"k2v2","order":8,"title":"Để mình suy nghĩ rồi sẽ nói cho bạn biết.","titleZh":"让我想想再告诉你。","titlePy":"ràng wǒ xiǎngxiang zài gàosu nǐ","vocab":[{"stt":1,"hanzi":"再","pinyin":"zài","hanviet":"Tái","pos":"Phó từ","meaning":"lại, nữa; rồi hãy","comps":"再见 (tạm biệt), 再来 (lại đến lần nữa)","example":{"zh":"我们下午再去吧。","py":"Wǒmen xiàwǔ zài qù ba.","vi":"Chiều chúng ta đi sau vậy."}},{"stt":2,"hanzi":"让","pinyin":"ràng","hanviet":"Nhượng","pos":"Động từ","meaning":"để, bảo, cho phép","comps":"让我 (để tôi), 让他去 (bảo anh ấy đi)","example":{"zh":"让我想想。","py":"Ràng wǒ xiǎngxiang.","vi":"Để tôi nghĩ một chút."}},{"stt":3,"hanzi":"告诉","pinyin":"gàosu","hanviet":"Cáo tố","pos":"Động từ","meaning":"nói cho biết, bảo","comps":"告诉我 (nói cho tôi biết), 告诉他 (bảo anh ấy)","example":{"zh":"我明天告诉你。","py":"Wǒ míngtiān gàosu nǐ.","vi":"Mai tôi báo bạn nhé."}},{"stt":4,"hanzi":"等","pinyin":"děng","hanviet":"Đẳng","pos":"Động từ","meaning":"đợi, chờ","comps":"等等 (đợi chút), 等一下 (chờ một lát)","example":{"zh":"你等等我，好吗？","py":"Nǐ děngdeng wǒ, hǎo ma?","vi":"Bạn đợi tôi một lát, được không?"}},{"stt":5,"hanzi":"找","pinyin":"zhǎo","hanviet":"Trảo","pos":"Động từ","meaning":"tìm, tìm gặp","comps":"找人 (tìm người), 找时间 (thu xếp thời gian)","example":{"zh":"我想找时间去看看他。","py":"Wǒ xiǎng zhǎo shíjiān qù kànkan tā.","vi":"Tôi muốn thu xếp thời gian đi thăm anh ấy."}},{"stt":6,"hanzi":"事情","pinyin":"shìqing","hanviet":"Sự tình","pos":"Danh từ","meaning":"việc, chuyện","comps":"有事情 (có việc), 什么事情 (chuyện gì)","example":{"zh":"找大卫有什么事情吗？","py":"Zhǎo Dàwèi yǒu shénme shìqing ma?","vi":"Tìm Đại Vệ có chuyện gì thế?"}},{"stt":7,"hanzi":"服务员","pinyin":"fúwùyuán","hanviet":"Phục vụ viên","pos":"Danh từ","meaning":"nhân viên phục vụ","comps":"叫服务员 (gọi nhân viên), 服务 (phục vụ)","example":{"zh":"我叫服务员来。","py":"Wǒ jiào fúwùyuán lái.","vi":"Tôi gọi nhân viên phục vụ đến."}},{"stt":8,"hanzi":"白","pinyin":"bái","hanviet":"Bạch","pos":"Tính từ","meaning":"trắng","comps":"白色 (màu trắng), 白的 (cái màu trắng)","example":{"zh":"这件白的有点长。","py":"Zhè jiàn bái de yǒudiǎn cháng.","vi":"Chiếc màu trắng này hơi dài."}},{"stt":9,"hanzi":"黑","pinyin":"hēi","hanviet":"Hắc","pos":"Tính từ","meaning":"đen","comps":"黑色 (màu đen), 黑的 (cái màu đen)","example":{"zh":"那件黑的有点贵。","py":"Nà jiàn hēi de yǒudiǎn guì.","vi":"Chiếc màu đen kia hơi đắt."}},{"stt":10,"hanzi":"贵","pinyin":"guì","hanviet":"Quý","pos":"Tính từ","meaning":"đắt, mắc; quý","comps":"很贵 (rất đắt), 太贵了 (đắt quá)","example":{"zh":"这件衣服太贵了。","py":"Zhè jiàn yīfu tài guì le.","vi":"Chiếc áo này đắt quá."}}],"hanzi":[{"char":"再","pinyin":"zài","hanviet":"Tái","chars":["再"],"story":"再 vẽ hình một vật được chồng thêm một lớp nữa lên trên vật đã có sẵn, ý là làm thêm một lần. Vì vậy 再 nghĩa là \"lại, thêm lần nữa\" — và luôn dùng cho việc CHƯA xảy ra: 再见 nghĩa gốc là \"gặp lại\"."},{"char":"让","pinyin":"ràng","hanviet":"Nhượng","chars":["让"],"story":"让 giản thể gồm 讠 (bộ Ngôn — lời nói) và 上; dạng phồn thể 讓 có 言 bên trái và 襄 xiāng chỉ âm. Bộ Ngôn cho biết chữ này nói về việc dùng lời: dùng lời bảo người khác làm gì, hoặc nhường cho người ta."},{"char":"告诉","pinyin":"gàosu","hanviet":"Cáo tố","chars":["告","诉"],"story":"告 gồm 牛 (con bò) ở trên và 口 (miệng) ở dưới — người xưa dâng bò tế mà khấn báo với thần, nên 告 nghĩa là báo cho biết. 诉 gồm 讠 (lời nói) và 斥 chỉ âm, nghĩa là kể, trình bày. 告诉 là nói cho ai đó biết."},{"char":"等","pinyin":"děng","hanviet":"Đẳng","chars":["等"],"story":"等 gồm ⺮ (bộ Trúc — thẻ tre) ở trên và 寺 chỉ âm ở dưới. Thẻ tre ngày xưa được xếp cho bằng nhau nên 等 có nghĩa \"ngang bằng, hạng\"; từ ý xếp hàng chờ tới lượt mà thành nghĩa đợi, chờ."},{"char":"找","pinyin":"zhǎo","hanviet":"Trảo","chars":["找"],"story":"找 gồm 扌 (bộ Thủ — bàn tay) và 戈 (cây giáo). Đưa tay ra lục lọi để kiếm cho ra một vật, nên 找 nghĩa là tìm, tìm gặp."},{"char":"事情","pinyin":"shìqing","hanviet":"Sự tình","chars":["事","情"],"story":"事 vẽ hình bàn tay cầm bút ghi chép công việc, nên nghĩa là việc, sự việc. 情 gồm 忄 (bộ Tâm — trái tim) và 青 qīng chỉ âm, nghĩa là tình cảm, tình hình. 事情 ghép lại chỉ chuyện, sự việc nói chung."},{"char":"服务员","pinyin":"fúwùyuán","hanviet":"Phục vụ viên","chars":["服","务","员"],"story":"服 nghĩa là phục tùng, làm theo; 务 nghĩa là công việc, nhiệm vụ — ghép thành 服务 là phục vụ. 员 gồm 口 và 贝 (vỏ sò — tiền thời cổ), chỉ người làm một công việc nhất định (như 学员, 演员). 服务员 là người làm công việc phục vụ."},{"char":"白","pinyin":"bái","hanviet":"Bạch","chars":["白"],"story":"白 vẽ hình mặt trời vừa nhô lên toả ánh sáng (có thuyết nói là hình hạt gạo). Ánh sáng thì trắng và sáng rõ, nên 白 nghĩa là trắng, đồng thời có nghĩa \"rõ ràng\" trong 明白 (hiểu rõ)."},{"char":"黑","pinyin":"hēi","hanviet":"Hắc","chars":["黑"],"story":"黑 phần trên vẽ ống khói của bếp lò, phần dưới là bộ 灬 (bốn chấm — biến thể của 火, lửa). Khói lửa bám lâu ngày làm mọi thứ đen sạm, nên 黑 nghĩa là đen."},{"char":"贵","pinyin":"guì","hanviet":"Quý","chars":["贵"],"story":"贵 có bộ 贝 (vỏ sò — tiền bạc thời cổ) ở dưới. Chữ nào mang bộ 贝 cũng liên quan tới tiền của, nên 贵 nghĩa là đắt tiền; từ đó sinh ra nghĩa quý giá và cách xưng hô lịch sự 贵姓 (quý danh)."}],"grammar":[{"title":"Mẫu câu \"……，好吗？\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>我们</b><small>chúng ta</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>việc muốn làm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>好吗？</b><small>được không?</small></span></div>","summary":"<p class=\"gr-lead\">Đề nghị rồi hỏi ý người nghe</p><ul><li>Nêu <b>đề nghị trước</b>, rồi thêm <span class=\"zh\">好吗？</span> ở cuối để hỏi ý người nghe — lịch sự hơn hẳn câu ra lệnh.</li><li>Đồng ý thì đáp <span class=\"zh\">好</span> / <span class=\"zh\">好的</span> / <span class=\"zh\">好吧</span>; từ chối thì nêu lý do rồi đề nghị cách khác.</li><li>Có thể thay bằng <span class=\"zh\">行吗？</span> hoặc <span class=\"zh\">可以吗？</span> — cùng một sắc thái đề nghị.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">我们下午去看电影，好吗？</span> = Chiều nay chúng mình đi xem phim, được không?</p>","note":"<b>Lưu ý:</b> Phần trước dấu phẩy là <b>câu trần thuật</b>: nói <span class=\"zh\">我们去看电影，好吗？</span>, KHÔNG nói <span class=\"zh\">我们去看电影吗，好吗？</span>","examples":[{"zh":"我们一起去吃饭，好吗？","py":"Wǒmen yìqǐ qù chīfàn, hǎo ma?","vi":"Chúng mình cùng đi ăn cơm, được không?"},{"zh":"你明天下午给我打电话，好吗？","py":"Nǐ míngtiān xiàwǔ gěi wǒ dǎ diànhuà, hǎo ma?","vi":"Chiều mai bạn gọi điện cho tôi, được không?"},{"zh":"我们下午去看电影，好吗？","py":"Wǒmen xiàwǔ qù kàn diànyǐng, hǎo ma?","vi":"Chiều nay chúng mình đi xem phim, được không?"}],"exercises":[]},{"title":"Phó từ 再","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(先做完 A)</b><small>xong việc trước</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>再</b><small>rồi mới</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>việc làm sau</small></span></div>","summary":"<p class=\"gr-lead\">Lại, nữa — việc chưa xảy ra</p><ul><li><span class=\"zh\">再</span> đứng <b>ngay trước động từ</b>, nghĩa \"lại, thêm lần nữa\" — chỉ dùng cho việc <b>chưa xảy ra</b>.</li><li>Nối hai việc theo thứ tự: làm xong việc trước <b>rồi mới</b> làm việc sau (<span class=\"zh\">想想 → 再告诉你</span>).</li><li>Bài 7 học <span class=\"zh\">还</span> = việc <b>đang</b> diễn ra; <span class=\"zh\">再</span> là việc <b>sẽ</b> diễn ra — hai chữ này hay bị lẫn.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">让我想想再告诉你。</span>　·　<span class=\"zh\">回来再打吧。</span></p>","note":"<b>Lưu ý:</b> Việc <b>đã lặp lại rồi</b> thì dùng <span class=\"zh\">又</span>, không dùng <span class=\"zh\">再</span>: <span class=\"zh\">他昨天又来了。</span>","examples":[{"zh":"你再看看这本书吧。","py":"Nǐ zài kànkan zhè běn shū ba.","vi":"Bạn xem lại cuốn sách này thêm chút nữa đi."},{"zh":"你（明天）再给我打电话吧。","py":"Nǐ (míngtiān) zài gěi wǒ dǎ diànhuà ba.","vi":"(Mai) bạn gọi lại cho tôi nhé."},{"zh":"（你）让我想想再告诉你。","py":"(Nǐ) ràng wǒ xiǎngxiang zài gàosu nǐ.","vi":"(Bạn) để tôi nghĩ đã rồi báo bạn sau."}],"exercises":[]},{"title":"Câu kiêm ngữ (兼语句)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>让 / 叫</b><small>bảo, để</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>兼语</b><small>người được bảo</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>việc phải làm</small></span></div>","summary":"<p class=\"gr-lead\">Bảo ai đó làm việc gì</p><ul><li>Tân ngữ của <span class=\"zh\">让</span> / <span class=\"zh\">叫</span> <b>đồng thời làm chủ ngữ</b> của động từ đứng sau — vì \"kiêm\" hai vai nên gọi là kiêm ngữ.</li><li>Động từ hay đứng đầu câu kiêm ngữ: <span class=\"zh\">让</span> (để, bảo), <span class=\"zh\">叫</span> (gọi, sai), <span class=\"zh\">请</span> (mời).</li><li>Phủ định đặt <span class=\"zh\">不</span> hoặc <span class=\"zh\">没</span> <b>trước</b> <span class=\"zh\">让</span> / <span class=\"zh\">叫</span>: <span class=\"zh\">妈妈不让我去。</span></li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">王老师让我给大卫打个电话。</span> = Thầy Vương bảo mình gọi điện cho Đại Vệ.</p>","note":"<b>Lưu ý:</b> Đặt <span class=\"zh\">不</span> trước động từ thứ hai là <b>nghĩa khác hẳn</b>: <span class=\"zh\">他不让我去</span> (không cho đi) ≠ <span class=\"zh\">他让我不去</span> (bảo đừng đi).","examples":[{"zh":"我请你吃饭。","py":"Wǒ qǐng nǐ chīfàn.","vi":"Tôi mời bạn ăn cơm."},{"zh":"你让我再想想。","py":"Nǐ ràng wǒ zài xiǎngxiang.","vi":"Bạn để tôi nghĩ thêm chút nữa."},{"zh":"我叫人去看看。","py":"Wǒ jiào rén qù kànkan.","vi":"Tôi cho người đi xem thử."}],"exercises":[]},{"title":"Lặp lại động từ (动词重叠)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>动词</b><small>lặp lại</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b><small>tân ngữ</small></span></div>","summary":"<p class=\"gr-lead\">Làm một chút, thử một chút</p><ul><li>Lặp động từ làm giọng <b>nhẹ nhàng, thân mật</b> hơn: làm một chút, làm thử xem — thay cho câu ra lệnh cộc lốc.</li><li>Động từ <b>một âm tiết</b> lặp thành AA (<span class=\"zh\">看看</span>, <span class=\"zh\">等等</span>), có thể xen <span class=\"zh\">一</span>: <span class=\"zh\">看一看</span>.</li><li>Động từ <b>hai âm tiết</b> lặp theo kiểu <b>ABAB</b>: <span class=\"zh\">运动运动</span>, <span class=\"zh\">休息休息</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> Một âm tiết → AA: <span class=\"zh\">看看</span>, <span class=\"zh\">等等</span>, <span class=\"zh\">想想</span>　·　Hai âm tiết → ABAB: <span class=\"zh\">运动运动</span></p>","note":"<b>Lưu ý:</b> Chữ lặp lại đọc <b>thanh nhẹ</b> (<span class=\"zh\">看看</span> kànkan). Hai âm tiết KHÔNG lặp thành AABB — nói <span class=\"zh\">运动运动</span>, KHÔNG nói <span class=\"zh\">运运动动</span>.","examples":[{"zh":"说：说说、说一说、说了说","py":"shuō: shuōshuo, shuō yi shuō, shuōle shuō","vi":"nói thử, nói chút · 说了说 = đã nói qua"},{"zh":"听：听听、听一听、听了听","py":"tīng: tīngting, tīng yi tīng, tīngle tīng","vi":"nghe thử, nghe chút · 听了听 = đã nghe qua"},{"zh":"看：看看、看一看、看了看","py":"kàn: kànkan, kàn yi kàn, kànle kàn","vi":"xem thử, xem chút · 看了看 = đã xem qua"},{"zh":"学习：学习学习","py":"xuéxí: xuéxí xuéxí","vi":"học một chút (ABAB)"},{"zh":"准备：准备准备","py":"zhǔnbèi: zhǔnbèi zhǔnbèi","vi":"chuẩn bị một chút (ABAB)"},{"zh":"运动：运动运动","py":"yùndòng: yùndòng yùndòng","vi":"vận động một chút (ABAB)"}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室","titleVi":"Trong lớp — rủ nhau đi xem phim","lines":[{"speaker":"甲","name":"Bạn A","zh":"我们下午去看电影，好吗？","py":"Wǒmen xiàwǔ qù kàn diànyǐng, hǎo ma?","vi":"Chiều nay chúng mình đi xem phim, được không?"},{"speaker":"乙","name":"Bạn B","zh":"今天下午我没有时间，下午再去吧？","py":"Jīntiān xiàwǔ wǒ méiyǒu shíjiān, xiàwǔ zài qù ba?","vi":"Chiều nay tớ không có thời gian, để chiều rồi đi sau nhé?"},{"speaker":"甲","name":"Bạn A","zh":"你想看什么电影？","py":"Nǐ xiǎng kàn shénme diànyǐng?","vi":"Cậu muốn xem phim gì?"},{"speaker":"乙","name":"Bạn B","zh":"让我想想再告诉你。","py":"Ràng wǒ xiǎngxiang zài gàosu nǐ.","vi":"Để tớ nghĩ đã rồi báo cậu sau."}]},{"titleZh":"课文二 · 在宿舍","titleVi":"Ký túc xá — rủ ra ngoài vận động","lines":[{"speaker":"甲","name":"Bạn A","zh":"外边天气很好，我们出去运动运动吧！","py":"Wàibian tiānqì hěn hǎo, wǒmen chūqu yùndong yùndong ba!","vi":"Thời tiết bên ngoài đẹp lắm, chúng mình ra ngoài vận động chút đi!"},{"speaker":"乙","name":"Bạn B","zh":"你等等我，好吗？王老师让我给大卫打个电话。","py":"Nǐ děngdeng wǒ, hǎo ma? Wáng lǎoshī ràng wǒ gěi Dàwèi dǎ ge diànhuà.","vi":"Cậu đợi tớ một lát, được không? Thầy Vương bảo tớ gọi điện cho Đại Vệ."},{"speaker":"甲","name":"Bạn A","zh":"回来再打吧。找大卫有什么事情吗？","py":"Huílai zài dǎ ba. Zhǎo Dàwèi yǒu shénme shìqing ma?","vi":"Về rồi gọi cũng được mà. Tìm Đại Vệ có chuyện gì thế?"},{"speaker":"乙","name":"Bạn B","zh":"听说大卫病了，我想找时间去看看他。","py":"Tīngshuō Dàwèi bìng le, wǒ xiǎng zhǎo shíjiān qù kànkan tā.","vi":"Nghe nói Đại Vệ ốm rồi, tớ muốn thu xếp thời gian qua thăm cậu ấy."}]},{"titleZh":"课文三 · 宾馆的前台","titleVi":"Lễ tân khách sạn — hỏng khoá cửa","lines":[{"speaker":"甲","name":"Bạn A","zh":"服务员，我房间的门打不开了。","py":"Fúwùyuán, wǒ fángjiān de mén dǎbukāi le.","vi":"Anh phục vụ ơi, cửa phòng tôi không mở được rồi."},{"speaker":"服","name":"Nhân viên","zh":"您住哪个房间？","py":"Nín zhù nǎge fángjiān?","vi":"Dạ quý khách ở phòng nào ạ?"},{"speaker":"甲","name":"Bạn A","zh":"317","py":"Sān yāo qī.","vi":"Phòng 317."},{"speaker":"服","name":"Nhân viên","zh":"好的，我叫人去看看。","py":"Hǎo de, wǒ jiào rén qù kànkan.","vi":"Vâng ạ, tôi cho người lên xem thử."}]},{"titleZh":"课文四 · 在商店","titleVi":"Trong cửa hàng — chọn áo màu nào","lines":[{"speaker":"甲","name":"Bạn A","zh":"你看看这几件衣服怎么样。","py":"Nǐ kànkan zhè jǐ jiàn yīfu zěnmeyàng.","vi":"Bạn xem thử mấy chiếc áo này thế nào."},{"speaker":"乙","name":"Bạn B","zh":"这件白的有点长，那件黑的有点贵。","py":"Zhè jiàn bái de yǒudiǎn cháng, nà jiàn hēi de yǒudiǎn guì.","vi":"Chiếc màu trắng này hơi dài, chiếc màu đen kia hơi đắt."},{"speaker":"甲","name":"Bạn A","zh":"这件红的呢？这是今天新来的。","py":"Zhè jiàn hóng de ne? Zhè shì jīntiān xīn lái de.","vi":"Thế chiếc màu đỏ này thì sao? Cái này hôm nay mới về đấy."},{"speaker":"乙","name":"Bạn B","zh":"让我再看看。","py":"Ràng wǒ zài kànkan.","vi":"Để tớ xem thêm chút nữa đã."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu của câu trần thuật","introZh":"汉语的陈述句句调一般为降调。","introVi":"Trong tiếng Trung Quốc, câu trần thuật thường có ngữ điệu xuống giọng.","zh":"陈述句的句调","py":"chénshùjù de jùdiào","tag":"Ngữ điệu","vi":"Xuống giọng ↘","listZh":"陈述句的句调","listVi":"Câu trần thuật thường xuống giọng ↘","descZh":"汉语的陈述句句调一般为降调。","descVi":"Trong tiếng Trung Quốc, câu trần thuật thường có ngữ điệu xuống giọng.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"陈述句","s":"câu trần thuật"},{"l":"降调 ↘","s":"xuống giọng","dn":true}]],"tip":"Cuối câu trần thuật <b>hạ giọng dần ↘</b>, đọc dứt khoát như kết thúc ý. Thanh điệu từng chữ giữ nguyên (<span class=\"zh\">好</span> vẫn thanh 3).","readLbl":"Luyện đọc · ↘ xuống giọng","sents":[{"tone":"down","w":[{"hz":"我","py":"Wǒ"},{"hz":"学习","py":"xuéxí"},{"hz":"汉语。","py":"Hànyǔ."}],"vi":"Tôi học tiếng Trung."},{"tone":"down","w":[{"hz":"他","py":"Tā"},{"hz":"是","py":"shì"},{"hz":"我的","py":"wǒ de"},{"hz":"老师。","py":"lǎoshī."}],"vi":"Anh ấy là thầy giáo của tôi."},{"tone":"down","w":[{"hz":"外边","py":"Wàibian"},{"hz":"天气","py":"tiānqì"},{"hz":"很","py":"hěn"},{"hz":"好。","py":"hǎo."}],"vi":"Thời tiết bên ngoài rất đẹp."}]}],"activity":{"act":[],"speak":[{"tag":"Hoạt động nhóm","mean":"Xây khung · Trình bày","q":{"zh":"说一说你最喜欢的运动。","py":"Shuō yi shuō nǐ zuì xǐhuan de yùndòng.","vi":"Hãy nói về môn thể thao bạn yêu thích nhất."},"prep":3,"talk":2,"frame":[{"lbl":"开头","zh":"我最喜欢的运动是……。","py":"","vi":"Mở bài","ex":null},{"lbl":"中间","zh":"因为……，所以我很喜欢……。","py":"","vi":"Thân bài · 1","ex":null},{"lbl":"中间","zh":"我每个星期……次，常常和……一起去……。","py":"","vi":"Thân bài · 2","ex":null},{"lbl":"结尾","zh":"我们一起去运动运动，好吗？","py":"","vi":"Kết bài","ex":null}]}]}},{"id":"k2v2-b09","courseId":"k2v2","order":9,"title":"Câu hỏi quá nhiều nên mình không làm hết.","titleZh":"题太多，我没做完。","titlePy":"tí tài duō, wǒ méi zuòwán","vocab":[{"stt":1,"hanzi":"错","pinyin":"cuò","hanviet":"Thác","pos":"Tính từ","meaning":"sai, nhầm","comps":"打错 (gọi nhầm), 说错 (nói sai)","example":{"zh":"你打错了。","py":"Nǐ dǎcuò le.","vi":"Bạn gọi nhầm rồi."}},{"stt":2,"hanzi":"从","pinyin":"cóng","hanviet":"Tùng","pos":"Giới từ","meaning":"từ, kể từ","comps":"从……开始 (bắt đầu từ), 从这儿 (từ đây)","example":{"zh":"从下个星期一开始。","py":"Cóng xià ge xīngqīyī kāishǐ.","vi":"Bắt đầu từ thứ Hai tuần sau."}},{"stt":3,"hanzi":"跳舞","pinyin":"tiàowǔ","hanviet":"Khiêu vũ","pos":"Động từ","meaning":"nhảy múa, khiêu vũ","comps":"学跳舞 (học nhảy), 喜欢跳舞 (thích nhảy múa)","example":{"zh":"我七岁开始跳舞。","py":"Wǒ qī suì kāishǐ tiàowǔ.","vi":"Tôi bắt đầu học nhảy từ năm bảy tuổi."}},{"stt":4,"hanzi":"第一","pinyin":"dìyī","hanviet":"Đệ nhất","pos":"Số từ","meaning":"thứ nhất, đầu tiên","comps":"第一次 (lần đầu tiên), 第一个 (cái thứ nhất)","example":{"zh":"这是我第一次来中国。","py":"Zhè shì wǒ dì yī cì lái Zhōngguó.","vi":"Đây là lần đầu tiên tôi đến Trung Quốc."}},{"stt":5,"hanzi":"希望","pinyin":"xīwàng","hanviet":"Hy vọng","pos":"Động từ","meaning":"hy vọng, mong","comps":"希望你 (mong bạn), 希望能 (mong có thể)","example":{"zh":"希望他能喜欢。","py":"Xīwàng tā néng xǐhuan.","vi":"Mong là anh ấy sẽ thích."}},{"stt":6,"hanzi":"问题","pinyin":"wèntí","hanviet":"Vấn đề","pos":"Danh từ","meaning":"câu hỏi; vấn đề","comps":"没问题 (không thành vấn đề), 有问题 (có câu hỏi)","example":{"zh":"没问题，非常欢迎。","py":"Méi wèntí, fēicháng huānyíng.","vi":"Không vấn đề gì, rất hoan nghênh."}},{"stt":7,"hanzi":"欢迎","pinyin":"huānyíng","hanviet":"Hoan nghênh","pos":"Động từ","meaning":"hoan nghênh, chào đón","comps":"欢迎你 (chào mừng bạn), 非常欢迎 (rất hoan nghênh)","example":{"zh":"欢迎你来我家。","py":"Huānyíng nǐ lái wǒ jiā.","vi":"Chào mừng bạn đến nhà tôi chơi."}},{"stt":8,"hanzi":"上班","pinyin":"shàngbān","hanviet":"Thượng ban","pos":"Động từ","meaning":"đi làm, đi làm việc","comps":"去上班 (đi làm), 上班时间 (giờ làm việc)","example":{"zh":"他下个星期开始上班。","py":"Tā xià ge xīngqī kāishǐ shàngbān.","vi":"Tuần sau anh ấy bắt đầu đi làm."}},{"stt":9,"hanzi":"懂","pinyin":"dǒng","hanviet":"Đổng","pos":"Động từ","meaning":"hiểu","comps":"听懂 (nghe hiểu), 看懂 (đọc hiểu)","example":{"zh":"你都听懂了吗？","py":"Nǐ dōu tīngdǒng le ma?","vi":"Bạn nghe hiểu hết chứ?"}},{"stt":10,"hanzi":"完","pinyin":"wán","hanviet":"Hoàn","pos":"Động từ","meaning":"xong, hết","comps":"做完 (làm xong), 吃完 (ăn hết)","example":{"zh":"我没做完。","py":"Wǒ méi zuòwán.","vi":"Tôi làm chưa xong."}},{"stt":11,"hanzi":"题","pinyin":"tí","hanviet":"Đề","pos":"Danh từ","meaning":"đề, câu hỏi bài tập","comps":"做题 (làm bài tập), 题太多 (đề quá nhiều)","example":{"zh":"题太多，我没做完。","py":"Tí tài duō, wǒ méi zuòwán.","vi":"Đề nhiều quá, tôi làm không xong."}}],"hanzi":[{"char":"错","pinyin":"cuò","hanviet":"Thác","chars":["错"],"story":"错 gồm 钅 (bộ Kim — kim loại) chỉ nghĩa và 昔 xī chỉ âm. Nghĩa gốc là dát vàng đan chéo lên đồ kim loại; từ ý \"đan xen, lệch nhau\" mà sinh ra nghĩa hôm nay là sai, nhầm."},{"char":"从","pinyin":"cóng","hanviet":"Tùng","chars":["从"],"story":"从 vẽ hình hai chữ 人 (người) nối nhau, người sau đi theo người trước — nghĩa gốc là \"đi theo\". Từ ý đi theo một mốc mà 从 thành giới từ chỉ điểm bắt đầu: từ đâu, từ khi nào."},{"char":"跳舞","pinyin":"tiàowǔ","hanviet":"Khiêu vũ","chars":["跳","舞"],"story":"跳 gồm 足 (bộ Túc — bàn chân) chỉ nghĩa và 兆 zhào chỉ âm, nghĩa là nhảy. 舞 vẽ hình người dang hai tay cầm đồ trang trí mà múa, phía dưới là hai bàn chân. 跳舞 ghép lại là nhảy múa."},{"char":"第一","pinyin":"dìyī","hanviet":"Đệ nhất","chars":["第","一"],"story":"第 gồm ⺮ (bộ Trúc — thẻ tre) ở trên và phần dưới lấy từ 弟 (em); thẻ tre ngày xưa xếp theo thứ tự trên dưới, nên 第 chuyên đứng trước số để chỉ thứ tự. 一 chỉ là một nét ngang — số một. 第一 là thứ nhất."},{"char":"希望","pinyin":"xīwàng","hanviet":"Hy vọng","chars":["希","望"],"story":"希 có 巾 (tấm vải) ở dưới, phần trên vẽ các sợi đan thưa — vải thưa nhìn thấu qua được, sinh ra ý trông ngóng. 望 gồm 月 (mặt trăng), 王 và 亡 chỉ âm — hình người đứng ngóng trăng. 希望 là mong ngóng, hy vọng."},{"char":"问题","pinyin":"wèntí","hanviet":"Vấn đề","chars":["问","题"],"story":"问 gồm 门 (cánh cửa) bao ngoài và 口 (miệng) bên trong — đứng ngoài cửa mà cất tiếng hỏi vào. 题 gồm 页 (bộ Hiệt — cái đầu) và 是 chỉ âm, vốn chỉ vầng trán, sau chỉ đầu đề. 问题 là câu hỏi, vấn đề."},{"char":"欢迎","pinyin":"huānyíng","hanviet":"Hoan nghênh","chars":["欢","迎"],"story":"欢 gồm 又 (bàn tay) và 欠 (bộ Khiếm — người há miệng); dạng phồn thể 歡 có 雚 chỉ âm. Nghĩa là vui mừng. 迎 gồm 辶 (bộ Sước — bước đi) và 卬 chỉ âm, nghĩa là ra đón. 欢迎 là vui mừng ra đón khách."},{"char":"上班","pinyin":"shàngbān","hanviet":"Thượng ban","chars":["上","班"],"story":"上 vẽ một nét nằm phía TRÊN vạch mốc, nên nghĩa là ở trên, đi lên. 班 gồm hai chữ 王 (ngọc) kẹp 刂 (con dao) ở giữa — lấy dao chia ngọc thành từng nhóm, nên 班 nghĩa là nhóm, ca, lớp. 上班 là lên ca làm việc, tức đi làm."},{"char":"懂","pinyin":"dǒng","hanviet":"Đổng","chars":["懂"],"story":"懂 gồm 忄 (bộ Tâm — trái tim) chỉ nghĩa và 董 dǒng chỉ âm. Bộ Tâm cho biết chữ này nói về hoạt động trong lòng: trong lòng đã sáng tỏ, nên 懂 nghĩa là hiểu."},{"char":"完","pinyin":"wán","hanviet":"Hoàn","chars":["完"],"story":"完 gồm 宀 (mái nhà) chỉ nghĩa và 元 yuán chỉ âm. Nghĩa gốc là ngôi nhà đã xây trọn vẹn, không thiếu chỗ nào — từ đó sinh ra nghĩa hoàn thành, xong, hết."},{"char":"题","pinyin":"tí","hanviet":"Đề","chars":["题"],"story":"题 gồm 页 (bộ Hiệt — vẽ cái đầu người) chỉ nghĩa và 是 chỉ âm. Nghĩa gốc là vầng trán, tức phần trên cùng; từ đó ra nghĩa \"đầu đề\" đặt ở đầu bài, rồi thành đề bài, câu hỏi bài tập."}],"grammar":[{"title":"Bổ ngữ kết quả (结果补语)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>hành động</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>结果补语</b><small>kết quả</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b><small>tân ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(了)</b><small>trợ từ</small></span></div>","summary":"<p class=\"gr-lead\">Nói rõ kết quả của hành động</p><div class=\"gr-sub\"><h4><span class=\"zh\">补语</span> · Bổ ngữ</h4><p>Bổ ngữ là gì? · Các loại bổ ngữ</p></div><div class=\"gr-sub\"><h4><span class=\"zh\">常用结果补语</span> · Bảng tổng hợp</h4><p>5 bổ ngữ kết quả thường gặp</p></div><div class=\"gr-sub\"><h4><span class=\"zh\">结果补语</span> · Công thức</h4><p>Khẳng định · Phủ định · Nghi vấn</p><ul><li><b>Vị trí:</b> V + BNKQ <b>dính liền</b>, không chen gì vào giữa</li><li><b>Phủ định:</b> dùng <span class=\"zh\">没(有)</span>, <b>không</b> dùng <span class=\"zh\">不</span> — ✗ <span class=\"zh\">我不做完</span></li></ul><div class=\"gr-formula\"><div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>结果补语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了</b></span></div><div class=\"fx-ex zh\">我做完作业了。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没(有)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>结果补语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span></div><div class=\"fx-ex zh\">我没做完作业。</div><div class=\"fx-lbl\">Nghi vấn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>结果补语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>了吗？/ 了没有？</b></span></div><div class=\"fx-ex zh\">你听懂了吗？</div></div></div><div class=\"gr-sub\"><h4><span class=\"zh\">结果补语 \"见\"</span> · Bổ ngữ kết quả</h4><p>Thấy — qua giác quan</p><ul><li><b>Ý nghĩa:</b> nhìn / nghe và đã <b>thấy</b> — cảm nhận được kết quả</li><li><b>Hay gặp:</b> <span class=\"zh\">看见</span> nhìn thấy · <span class=\"zh\">听见</span> nghe thấy</li></ul></div><div class=\"gr-sub\"><h4><span class=\"zh\">结果补语 \"懂\"</span> · Bổ ngữ kết quả</h4><p>Hiểu — qua nghe / đọc</p><ul><li><b>Ý nghĩa:</b> nghe / xem / đọc và đã <b>hiểu</b> được nội dung</li><li><b>Hay gặp:</b> <span class=\"zh\">听懂</span> nghe hiểu · <span class=\"zh\">看懂</span> xem hiểu, đọc hiểu</li></ul></div><div class=\"gr-sub\"><h4><span class=\"zh\">结果补语 \"好\"</span> · Bổ ngữ kết quả</h4><p>Xong xuôi, đạt yêu cầu</p><ul><li><b>Ý nghĩa:</b> làm xong và <b>đạt yêu cầu</b> — xong xuôi, sẵn sàng</li><li><b>Hay gặp:</b> <span class=\"zh\">做好</span> làm xong · <span class=\"zh\">准备好</span> chuẩn bị xong · <span class=\"zh\">写好</span> viết xong</li></ul></div><div class=\"gr-sub\"><h4><span class=\"zh\">结果补语 \"到\"</span> · Bổ ngữ kết quả</h4><p>Được, tới — đạt mục đích</p><ul><li><b>Ý nghĩa:</b> hành động <b>đạt được mục đích</b> (… được) hoặc <b>tới</b> một nơi, một lúc</li><li><b>Hay gặp:</b> <span class=\"zh\">找到</span> tìm được · <span class=\"zh\">买到</span> mua được · <span class=\"zh\">走到</span> đi tới</li></ul></div><div class=\"gr-sub\"><h4><span class=\"zh\">结果补语 \"完\"</span> · Bổ ngữ kết quả</h4><p>Xong, hết — kết thúc</p><ul><li><b>Ý nghĩa:</b> hành động <b>kết thúc</b> — làm xong, dùng hết</li><li><b>Hay gặp:</b> <span class=\"zh\">做完</span> làm xong · <span class=\"zh\">吃完</span> ăn hết · <span class=\"zh\">看完</span> xem xong</li></ul></div>","note":"<b>Lưu ý:</b> <span class=\"zh\">了</span> / tân ngữ đặt <b>sau cả cụm</b>: <span class=\"zh\">我听懂了</span> — ✗ <span class=\"zh\">我听了懂</span>","examples":[{"zh":"题太多，我没做完。","py":"Tí tài duō, wǒ méi zuòwán.","vi":"Đề nhiều quá, tớ làm không xong."}],"exercises":[]},{"title":"Giới từ 从","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>从</b><small>từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>时间 / 地点</b><small>mốc bắt đầu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>开始</b><small>bắt đầu</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>việc làm</small></span></div>","summary":"<p class=\"gr-lead\">Nói điểm bắt đầu — từ khi nào, từ đâu</p><ul><li><span class=\"zh\">从</span> nêu <b>điểm xuất phát</b> — về thời gian (<span class=\"zh\">从七岁</span>) hoặc nơi chốn (<span class=\"zh\">从北京</span>).</li><li>Cụm <span class=\"zh\">从……</span> đứng <b>trước động từ</b>, rất hay đi đôi với <span class=\"zh\">开始</span>: <span class=\"zh\">从……开始</span>.</li><li>Cặp <span class=\"zh\">从……到……</span> nêu cả điểm đầu lẫn điểm cuối: <span class=\"zh\">从家到公司</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">从下个星期一开始。</span>　·　<span class=\"zh\">你从几岁开始学习跳舞？</span></p>","note":"<b>Lưu ý:</b> Bài 7 học <span class=\"zh\">离</span> đo <b>khoảng cách</b>; <span class=\"zh\">从</span> nêu <b>điểm xuất phát</b> — hai giới từ này rất hay bị lẫn.","examples":[{"zh":"从北京到上海要坐几个小时的飞机？","py":"Cóng Běijīng dào Shànghǎi yào zuò jǐ ge xiǎoshí de fēijī?","vi":"Từ Bắc Kinh đến Thượng Hải phải đi máy bay mấy tiếng?"},{"zh":"从老人到小孩子都喜欢吃苹果。","py":"Cóng lǎorén dào xiǎoháizi dōu xǐhuan chī píngguǒ.","vi":"Từ người già đến trẻ nhỏ đều thích ăn táo."},{"zh":"从下个星期开始上班。","py":"Cóng xià ge xīngqī kāishǐ shàngbān.","vi":"Bắt đầu đi làm từ tuần sau."}],"exercises":[]},{"title":"第…… — cách nói số thứ tự","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>第</b><small>thứ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>数词</b><small>số đếm</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>量词</b><small>lượng từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(名词)</b><small>danh từ</small></span></div>","summary":"<p class=\"gr-lead\">Thêm 第 để nói thứ tự</p><ul><li>Số đếm (<span class=\"zh\">一, 二, 三</span>) chỉ <b>số lượng</b>; thêm <span class=\"zh\">第</span> phía trước thì thành <b>số thứ tự</b>.</li><li>Sau <span class=\"zh\">第 + 数词</span> vẫn phải có <b>lượng từ</b>: <span class=\"zh\">第一个</span>, <span class=\"zh\">第二件</span>, <span class=\"zh\">第三次</span>.</li><li>Một số danh từ tự làm lượng từ nên ghép thẳng: <span class=\"zh\">第一课</span>, <span class=\"zh\">第一天</span>, <span class=\"zh\">第一年</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">第一次</span> lần thứ nhất　·　<span class=\"zh\">第一个工作</span> công việc đầu tiên　·　<span class=\"zh\">第九课</span> bài thứ chín</p>","note":"<b>Lưu ý:</b> Sau <span class=\"zh\">第</span> luôn dùng <span class=\"zh\">二</span>, KHÔNG dùng <span class=\"zh\">两</span>: nói <span class=\"zh\">第二个</span>, không nói <span class=\"zh\">第两个</span>.","examples":[{"zh":"我第一次跳舞是在七岁的时候。","py":"Wǒ dì yī cì tiàowǔ shì zài qī suì de shíhou.","vi":"Lần đầu tiên mình nhảy múa là hồi bảy tuổi."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 打电话","titleVi":"Gọi điện — bấm nhầm số máy","lines":[{"speaker":"甲","name":"Bạn A","zh":"你好，请问张欢在吗？","py":"Nǐ hǎo, qǐngwèn Zhāng Huān zài ma?","vi":"Xin chào, cho hỏi Trương Hoan có ở đó không ạ?"},{"speaker":"乙","name":"Bạn B","zh":"你打错了，我没有叫张欢的。","py":"Nǐ dǎcuò le, wǒ méiyǒu jiào Zhāng Huān de.","vi":"Bạn gọi nhầm rồi, chỗ tôi không có ai tên Trương Hoan cả."},{"speaker":"甲","name":"Bạn A","zh":"对不起。","py":"Duìbuqǐ.","vi":"Xin lỗi ạ."}]},{"titleZh":"课文二 · 在学校","titleVi":"Ở trường — xin cho con học nhảy","lines":[{"speaker":"甲","name":"Bạn A","zh":"你从几岁开始学习跳舞？","py":"Nǐ cóng jǐ suì kāishǐ xuéxí tiàowǔ?","vi":"Cô bắt đầu học nhảy từ năm mấy tuổi ạ?"},{"speaker":"乙","name":"Bạn B","zh":"我第一次跳舞是在七岁的时候。","py":"Wǒ dì yī cì tiàowǔ shì zài qī suì de shíhou.","vi":"Lần đầu tiên tôi nhảy múa là hồi bảy tuổi."},{"speaker":"甲","name":"Bạn A","zh":"我女儿今年也七岁了。我希望他能跟您学跳舞，可以吗？","py":"Wǒ nǚ'ér jīnnián yě qī suì le. Wǒ xīwàng tā néng gēn nín xué tiàowǔ, kěyǐ ma?","vi":"Con gái tôi năm nay cũng bảy tuổi. Tôi mong cháu được theo cô học nhảy, có được không ạ?"},{"speaker":"乙","name":"Bạn B","zh":"没问题，非常欢迎。","py":"Méi wèntí, fēicháng huānyíng.","vi":"Không vấn đề gì, rất hoan nghênh ạ."}]},{"titleZh":"课文三 · 在家里","titleVi":"Ở nhà — Đại Vệ tìm được việc làm","lines":[{"speaker":"甲","name":"Bạn A","zh":"你知道吗？大卫找到工作了。","py":"Nǐ zhīdào ma? Dàwèi zhǎodào gōngzuò le.","vi":"Cậu biết không? Đại Vệ tìm được việc rồi."},{"speaker":"乙","name":"Bạn B","zh":"太好了！他从什么时候开始上班？","py":"Tài hǎo le! Tā cóng shénme shíhou kāishǐ shàngbān?","vi":"Tuyệt quá! Cậu ấy bắt đầu đi làm từ khi nào?"},{"speaker":"甲","name":"Bạn A","zh":"从下个星期一开始。","py":"Cóng xià ge xīngqīyī kāishǐ.","vi":"Từ thứ Hai tuần sau."},{"speaker":"乙","name":"Bạn B","zh":"这是他的第一的工作，希望他能喜欢。","py":"Zhè shì tā de dì yī de gōngzuò, xīwàng tā néng xǐhuan.","vi":"Đây là công việc đầu tiên của cậu ấy, mong cậu ấy sẽ thích."}]},{"titleZh":"课文四 · 在教室","titleVi":"Trong lớp — hỏi nhau về bài thi","lines":[{"speaker":"甲","name":"Bạn A","zh":"昨天的考试怎么样？你都听懂了吗？","py":"Zuótiān de kǎoshì zěnmeyàng? Nǐ dōu tīngdǒng le ma?","vi":"Bài thi hôm qua thế nào? Cậu nghe hiểu hết chứ?"},{"speaker":"乙","name":"Bạn B","zh":"听懂了。","py":"Tīngdǒng le.","vi":"Tớ nghe hiểu hết."},{"speaker":"甲","name":"Bạn A","zh":"你都做完了没有？","py":"Nǐ dōu zuòwán le méiyǒu?","vi":"Thế cậu làm xong hết chưa?"},{"speaker":"乙","name":"Bạn B","zh":"题太多，我没做完。","py":"Tí tài duō, wǒ méi zuòwán.","vi":"Đề nhiều quá, tớ làm không xong."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu câu hỏi xác nhận đúng / sai","introZh":"是非疑问句：谓语部分重读，全句末为升调。","introVi":"Câu hỏi yêu cầu xác nhận thông tin đúng hay sai: đọc nhấn mạnh phần vị ngữ và lên giọng ở cuối câu.","zh":"是非疑问句的句调","py":"","tag":"Ngữ điệu","vi":"Nhấn vị ngữ · lên giọng ↗","listZh":"是非疑问句的句调","listVi":"Câu hỏi xác nhận đúng / sai — nhấn vị ngữ, cuối câu lên giọng ↗","descZh":"谓语部分重读，全句末为升调。","descVi":"Với loại câu hỏi này, ta đọc nhấn mạnh phần vị ngữ và lên giọng ở cuối câu.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"谓语","s":"vị ngữ"},{"l":"重读","s":"đọc nhấn","st":true}],[{"l":"句末","s":"cuối câu"},{"l":"升调 ↗","s":"lên giọng","st":true}]],"tip":"Nhấn <b>vị ngữ</b> (chữ có chấm đỏ), rồi <b>lên giọng ở cuối câu ↗</b> — <span class=\"zh\">吗</span> đọc nhẹ nhưng cao giọng. Thanh điệu từng chữ giữ nguyên.","readLbl":"Luyện đọc · chữ có chấm đỏ đọc nhấn · ↗ lên giọng","sents":[{"tone":"up","w":[{"hz":"你","py":"Nǐ"},{"hz":"明天","py":"míngtiān"},{"hz":"去","py":"qù","st":true},{"hz":"学校","py":"xuéxiào"},{"hz":"吗？","py":"ma?"}],"vi":"Ngày mai bạn có đến trường không?"},{"tone":"up","w":[{"hz":"他们","py":"Tāmen"},{"hz":"都","py":"dōu"},{"hz":"知道","py":"zhīdào","st":true},{"hz":"这","py":"zhè"},{"hz":"件","py":"jiàn"},{"hz":"事","py":"shì"},{"hz":"吗？","py":"ma?"}],"vi":"Họ đều biết chuyện này chứ?"},{"tone":"up","w":[{"hz":"你","py":"Nǐ"},{"hz":"都","py":"dōu"},{"hz":"听懂","py":"tīngdǒng","st":true},{"hz":"了吗？","py":"le ma?"}],"vi":"Bạn nghe hiểu hết chưa?"}]}]},{"id":"k2v2-b10","courseId":"k2v2","order":10,"title":"Đừng tìm nữa, điện thoại di động ở trên bàn kìa.","titleZh":"别找了，手机在桌子上呢。","titlePy":"bié zhǎo le, shǒujī zài zhuōzi shàng ne","vocab":[{"stt":1,"hanzi":"课","pinyin":"kè","hanviet":"Khoá","pos":"Danh từ","meaning":"tiết học, bài học","comps":"汉语课 (tiết tiếng Trung), 上课 (lên lớp)","example":{"zh":"明天上午还有汉语课。","py":"Míngtiān shàngwǔ hái yǒu Hànyǔ kè.","vi":"Sáng mai còn có tiết tiếng Trung."}},{"stt":2,"hanzi":"帮助","pinyin":"bāngzhù","hanviet":"Bang trợ","pos":"Động từ","meaning":"giúp đỡ; sự giúp ích","comps":"帮助我 (giúp tôi), 有帮助 (có ích)","example":{"zh":"看电视对学汉语有帮助。","py":"Kàn diànshì duì xué Hànyǔ yǒu bāngzhù.","vi":"Xem tivi có ích cho việc học tiếng Trung."}},{"stt":3,"hanzi":"别","pinyin":"bié","hanviet":"Biệt","pos":"Phó từ","meaning":"đừng, chớ (khuyên ngăn)","comps":"别去 (đừng đi), 别说话 (đừng nói chuyện)","example":{"zh":"别找了，手机在桌子上。","py":"Bié zhǎo le, shǒujī zài zhuōzi shàng.","vi":"Đừng tìm nữa, điện thoại ở trên bàn."}},{"stt":4,"hanzi":"哥哥","pinyin":"gēge","hanviet":"Ca ca","pos":"Danh từ","meaning":"anh trai","comps":"我哥哥 (anh trai tôi), 大哥 (anh cả)","example":{"zh":"哥哥今天中午回来吃饭。","py":"Gēge jīntiān zhōngwǔ huílái chīfàn.","vi":"Trưa nay anh trai về ăn cơm."}},{"stt":5,"hanzi":"鸡蛋","pinyin":"jīdàn","hanviet":"Kê đản","pos":"Danh từ","meaning":"trứng gà","comps":"一个鸡蛋 (một quả trứng), 吃鸡蛋 (ăn trứng)","example":{"zh":"妈妈买了鸡蛋和西瓜。","py":"Māma mǎi le jīdàn hé xīguā.","vi":"Mẹ đã mua trứng gà và dưa hấu."}},{"stt":6,"hanzi":"西瓜","pinyin":"xīguā","hanviet":"Tây qua","pos":"Danh từ","meaning":"dưa hấu","comps":"买西瓜 (mua dưa hấu), 吃西瓜 (ăn dưa hấu)","example":{"zh":"我很喜欢吃西瓜。","py":"Wǒ hěn xǐhuan chī xīguā.","vi":"Mình rất thích ăn dưa hấu."}},{"stt":7,"hanzi":"正在","pinyin":"zhèngzài","hanviet":"Chính tại","pos":"Phó từ","meaning":"đang (làm việc gì)","comps":"正在吃饭 (đang ăn cơm), 正在准备 (đang chuẩn bị)","example":{"zh":"妈妈正在准备午饭呢！","py":"Māma zhèngzài zhǔnbèi wǔfàn ne!","vi":"Mẹ đang chuẩn bị bữa trưa đấy!"}},{"stt":8,"hanzi":"手机","pinyin":"shǒujī","hanviet":"Thủ cơ","pos":"Danh từ","meaning":"điện thoại di động","comps":"我的手机 (điện thoại của tôi), 手机号码 (số máy)","example":{"zh":"我的手机在电脑旁边。","py":"Wǒ de shǒujī zài diànnǎo pángbiān.","vi":"Điện thoại của mình ở cạnh máy tính."}},{"stt":9,"hanzi":"洗","pinyin":"xǐ","hanviet":"Tẩy","pos":"Động từ","meaning":"rửa, giặt, gội","comps":"洗衣服 (giặt quần áo), 洗手 (rửa tay)","example":{"zh":"那件衣服我帮你洗了。","py":"Nà jiàn yīfu wǒ bāng nǐ xǐ le.","vi":"Cái áo đó mình giặt giúp bạn rồi."}}],"hanzi":[{"char":"课","pinyin":"kè","hanviet":"Khoá","chars":["课"],"story":"课 gồm bộ Ngôn 讠 (lời nói) chỉ nghĩa — việc dạy và học đều bằng lời — ghép với 果 guǒ chỉ âm đọc. Đây là chữ hình thanh điển hình, nên 课 nghĩa là tiết học, bài học."},{"char":"帮助","pinyin":"bāngzhù","hanviet":"Bang trợ","chars":["帮","助"],"story":"帮 = 邦 bāng (chỉ âm) + 巾 (mảnh vải). 助 = 且 (chỉ âm) + 力 (sức lực) — bỏ sức ra làm đỡ cho người khác. Hai chữ ghép lại thành 帮助: giúp đỡ."},{"char":"别","pinyin":"bié","hanviet":"Biệt","chars":["别"],"story":"别 gồm 另 (khác, riêng ra) bên trái và 刂 bộ Đao (con dao) bên phải: lấy dao tách rời ra. Nghĩa gốc là chia tách, phân biệt; về sau mượn dùng làm lời can ngăn \"đừng, chớ\"."},{"char":"哥哥","pinyin":"gēge","hanviet":"Ca ca","chars":["哥","哥"],"story":"哥 do hai chữ 可 xếp chồng lên nhau; 可 vốn vẽ cái miệng đang cất tiếng. Người Trung Quốc gọi người thân hay lặp chữ (爸爸, 妈妈), nên 哥哥 là cách gọi anh trai."},{"char":"鸡蛋","pinyin":"jīdàn","hanviet":"Kê đản","chars":["鸡","蛋"],"story":"鸡 bên phải là 鸟 (bộ Điểu, con chim), bên trái là phần chỉ âm rút gọn thành 又. 蛋 có 虫 (bộ Trùng, loài vật nhỏ) ở dưới. 鸡蛋 nghĩa đen là \"trứng của con gà\"."},{"char":"西瓜","pinyin":"xīguā","hanviet":"Tây qua","chars":["西","瓜"],"story":"西 vốn vẽ cái tổ chim, sau mượn chỉ hướng tây; 瓜 vẽ dây leo có quả treo lủng lẳng. Giống dưa này từ phương Tây truyền vào nên gọi 西瓜 — \"quả dưa phương Tây\"."},{"char":"正在","pinyin":"zhèngzài","hanviet":"Chính tại","chars":["正","在"],"story":"正 gồm 一 (vạch đích) và 止 (bàn chân) — bước chân đi thẳng tới đích, nên 正 nghĩa là ngay, đúng lúc. Ghép với 在 (ở, đang) thành 正在: đúng ngay lúc đang làm việc gì."},{"char":"手机","pinyin":"shǒujī","hanviet":"Thủ cơ","chars":["手","机"],"story":"手 vẽ bàn tay xoè năm ngón. 机 = 木 (bộ Mộc, gỗ) + 几 chỉ âm, nghĩa là cái máy. 手机 nghĩa đen là \"cái máy cầm trên tay\" — điện thoại di động."},{"char":"洗","pinyin":"xǐ","hanviet":"Tẩy","chars":["洗"],"story":"洗 gồm 氵 bộ Thuỷ (ba chấm nước) chỉ nghĩa và 先 xiān chỉ âm đọc. Phải có nước mới rửa được, nên 洗 nghĩa là rửa, giặt, gội."}],"grammar":[{"title":"祈使句：不要……了；别……了","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>不要 / 别</b><small>đừng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词 (+宾语)</b><small>động từ (+ tân ngữ)</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>… nữa</small></span></div>","summary":"<p class=\"gr-lead\">Khuyên ngăn — bảo ai đó đừng làm nữa</p><ul><li><b>Ý nghĩa:</b> câu cầu khiến (<span class=\"zh\">祈使句</span>) — <b>khuyên ngăn</b> hoặc <b>cấm</b> ai đó làm việc gì</li><li><b><span class=\"zh\">别</span> = <span class=\"zh\">不要</span></b> · <span class=\"zh\">别</span> ngắn gọn, khẩu ngữ hơn · <span class=\"zh\">了</span> cuối câu = \"… <b>nữa</b>\"</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">\"不要……了\" · \"别……了\"</span> · Ví dụ</h4><p>Bảng ví dụ như sách</p><div class=\"ct-box\"><div class=\"ct-cap\">Ví dụ · 不要 / 别 + động từ (+ tân ngữ) + 了</div><div class=\"ct-intro\"><span class=\"zh\">表示劝阻或禁止做某件事情。</span> — ngăn cản hay cấm đoán ai làm việc gì　<span class=\"ct-lg k\">不要 / 别 · 了</span><span class=\"ct-lg a\">Động từ (+ tân ngữ)</span></div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>不要……了<small>búyào … le</small></th><th>别……了<small>bié … le</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-k\"><b class=\"zh\">不要</b><small>Búyào</small></span><span class=\"ct-w c-a\"><b class=\"zh\">玩手机</b><small>wán shǒujī</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了。</b><small>le.</small></span></div><div class=\"ct-vi\">Đừng chơi điện thoại nữa.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-k\"><b class=\"zh\">别</b><small>Bié</small></span><span class=\"ct-w c-a\"><b class=\"zh\">睡觉</b><small>shuìjiào</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了。</b><small>le.</small></span></div><div class=\"ct-vi\">Đừng ngủ nữa.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-k\"><b class=\"zh\">不要</b><small>Búyào</small></span><span class=\"ct-w c-a\"><b class=\"zh\">做饭</b><small>zuò fàn</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了。</b><small>le.</small></span></div><div class=\"ct-vi\">Đừng nấu cơm nữa.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-k\"><b class=\"zh\">别</b><small>Bié</small></span><span class=\"ct-w c-a\"><b class=\"zh\">看书</b><small>kàn shū</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了。</b><small>le.</small></span></div><div class=\"ct-vi\">Đừng đọc sách nữa.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-k\"><b class=\"zh\">不要</b><small>Búyào</small></span><span class=\"ct-w c-a\"><b class=\"zh\">看电视</b><small>kàn diànshì</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了。</b><small>le.</small></span></div><div class=\"ct-vi\">Đừng xem tivi nữa.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-k\"><b class=\"zh\">别</b><small>Bié</small></span><span class=\"ct-w c-a\"><b class=\"zh\">看报纸</b><small>kàn bàozhǐ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了。</b><small>le.</small></span></div><div class=\"ct-vi\">Đừng đọc báo nữa.</div></td></tr></tbody></table></div></div></div><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"hot\"><span class=\"zh\">别找</span> = Đừng tìm　·　<span class=\"zh\">别找了</span> = Đừng tìm <b>nữa</b></span></p>","note":"<b>Lưu ý:</b> Không thêm <span class=\"zh\">吗</span> · ✗ <span class=\"zh\">别不找了</span> → <span class=\"zh\">别找了</span>","examples":[{"zh":"别玩手机了，快睡觉吧。","py":"Bié wán shǒujī le, kuài shuìjiào ba.","vi":"Đừng chơi điện thoại nữa, mau đi ngủ đi."},{"zh":"不要喝咖啡了，对身体不好。","py":"Búyào hē kāfēi le, duì shēntǐ bù hǎo.","vi":"Đừng uống cà phê nữa, không tốt cho sức khoẻ."},{"zh":"你的病已经好了，别吃药了。","py":"Nǐ de bìng yǐjīng hǎo le, bié chī yào le.","vi":"Bệnh của bạn khỏi rồi, đừng uống thuốc nữa."}],"exercises":[]},{"title":"Giới từ 对","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>A</b><small>người / việc</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>对</b><small>đối với</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b><small>đối tượng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>有帮助 / 好</b><small>nhận xét</small></span></div>","summary":"<p class=\"gr-lead\">Nêu đối tượng: đối với, với</p><ul><li><b>Ý nghĩa:</b> nêu <b>đối tượng</b> mà việc / nhận xét hướng tới — \"đối với, với\" (người ↔ người · người ↔ sự vật · sự vật ↔ sự vật)</li><li><b>Vị trí:</b> <span class=\"zh\">对 + B</span> đứng <b>trước</b> động từ / tính từ · hay đi với <span class=\"zh\">有帮助 · 好 · 不好</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">介词 \"对\"</span> · Ví dụ</h4><p>Bảng ví dụ như sách</p></div><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">看电视对学汉语有帮助。</span> = Xem tivi có ích cho việc học tiếng Trung.</p>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">有帮助对我</span> → <span class=\"zh\">对我有帮助</span>","examples":[{"zh":"游泳对身体很好。","py":"Yóuyǒng duì shēntǐ hěn hǎo.","vi":"Bơi lội rất tốt cho sức khoẻ."},{"zh":"看报纸对学习英语有帮助。","py":"Kàn bàozhǐ duì xuéxí Yīngyǔ yǒu bāngzhù.","vi":"Đọc báo có ích cho việc học tiếng Anh."},{"zh":"他对我说：\"别找了。\"","py":"Tā duì wǒ shuō: \"Bié zhǎo le.\"","vi":"Anh ấy nói với tôi: \"Đừng tìm nữa.\""}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在家里","titleVi":"Ở nhà — nhắc nhau chuẩn bị bài","lines":[{"speaker":"甲","name":"Bạn A","zh":"不要看电视了，明天上午还有汉语课呢。","py":"Búyào kàn diànshì le, míngtiān shàngwǔ hái yǒu Hànyǔ kè ne.","vi":"Đừng xem tivi nữa, sáng mai còn có tiết tiếng Trung mà."},{"speaker":"乙","name":"Bạn B","zh":"看电视对学汉语有帮助。","py":"Kàn diànshì duì xué Hànyǔ yǒu bāngzhù.","vi":"Xem tivi có ích cho việc học tiếng Trung mà."},{"speaker":"甲","name":"Bạn A","zh":"明天的课你都准备好了吗？","py":"Míngtiān de kè nǐ dōu zhǔnbèi hǎo le ma?","vi":"Bài của ngày mai bạn chuẩn bị xong hết chưa?"},{"speaker":"乙","name":"Bạn B","zh":"都准备好了。","py":"Dōu zhǔnbèi hǎo le.","vi":"Chuẩn bị xong hết rồi."}]},{"titleZh":"课文二 · 在医院","titleVi":"Ở bệnh viện — thăm người đang ốm","lines":[{"speaker":"甲","name":"Bạn A","zh":"别看报纸了，医生说你要多休息。","py":"Bié kàn bàozhǐ le, yīshēng shuō nǐ yào duō xiūxi.","vi":"Đừng đọc báo nữa, bác sĩ bảo bạn phải nghỉ ngơi nhiều mà."},{"speaker":"乙","name":"Bạn B","zh":"好，不看了。给我一杯茶吧。","py":"Hǎo, bú kàn le. Gěi wǒ yì bēi chá ba.","vi":"Được, không xem nữa. Cho mình một cốc trà nhé."},{"speaker":"甲","name":"Bạn A","zh":"医生说吃药后两个小时不要喝茶。","py":"Yīshēng shuō chī yào hòu liǎng ge xiǎoshí búyào hē chá.","vi":"Bác sĩ bảo sau khi uống thuốc hai tiếng thì đừng uống trà."},{"speaker":"乙","name":"Bạn B","zh":"医生还说什么了？","py":"Yīshēng hái shuō shénme le?","vi":"Bác sĩ còn nói gì nữa không?"},{"speaker":"甲","name":"Bạn A","zh":"医生让你听我的。","py":"Yīshēng ràng nǐ tīng wǒ de.","vi":"Bác sĩ bảo bạn phải nghe lời mình."}]},{"titleZh":"课文三 · 在家里","titleVi":"Ở nhà — cả nhà đón anh trai về ăn cơm","lines":[{"speaker":"甲","name":"Bạn A","zh":"你怎么买了这么多东西啊？","py":"Nǐ zěnme mǎi le zhème duō dōngxi a?","vi":"Sao bạn lại mua nhiều đồ thế?"},{"speaker":"乙","name":"Bạn B","zh":"哥哥今天中午回来吃饭。","py":"Gēge jīntiān zhōngwǔ huílái chīfàn.","vi":"Trưa nay anh trai về nhà ăn cơm."},{"speaker":"甲","name":"Bạn A","zh":"我看看买什么了。羊肉、鸡蛋、面条、西瓜…真不少！妈妈呢？","py":"Wǒ kànkan mǎi shénme le. Yángròu, jīdàn, miàntiáo, xīguā… zhēn bù shǎo! Māma ne?","vi":"Để mình xem mua những gì nào. Thịt dê, trứng gà, mì sợi, dưa hấu… nhiều thật đấy! Mẹ đâu rồi?"},{"speaker":"乙","name":"Bạn B","zh":"正在准备午饭呢！","py":"Zhèngzài zhǔnbèi wǔfàn ne!","vi":"Mẹ đang chuẩn bị bữa trưa đấy!"}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — tìm điện thoại và quần áo","lines":[{"speaker":"甲","name":"Bạn A","zh":"你在找什么？","py":"Nǐ zài zhǎo shénme?","vi":"Bạn đang tìm gì thế?"},{"speaker":"乙","name":"Bạn B","zh":"你看见我的手机了吗？白色的。","py":"Nǐ kànjiàn wǒ de shǒujī le ma? Báisè de.","vi":"Bạn có thấy điện thoại của mình không? Cái màu trắng ấy."},{"speaker":"甲","name":"Bạn A","zh":"别找了，手机在桌子上呢，电脑旁边。","py":"Bié zhǎo le, shǒujī zài zhuōzi shàng ne, diànnǎo pángbiān.","vi":"Đừng tìm nữa, điện thoại ở trên bàn kìa, cạnh máy tính ấy."},{"speaker":"乙","name":"Bạn B","zh":"你看见我的衣服了吗？红色的那件。","py":"Nǐ kànjiàn wǒ de yīfu le ma? Hóngsè de nà jiàn.","vi":"Bạn có thấy áo của mình không? Cái màu đỏ ấy."},{"speaker":"甲","name":"Bạn A","zh":"那件衣服我帮你洗了，在外边呢。","py":"Nà jiàn yīfu wǒ bāng nǐ xǐ le, zài wàibian ne.","vi":"Cái áo đó mình giặt giúp bạn rồi, đang ở ngoài kia."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu của câu hỏi có đại từ nghi vấn","introZh":"疑问代词重读，重音之后全句句调逐渐下降。","introVi":"Với loại câu hỏi này, ta đọc nhấn mạnh đại từ nghi vấn và dần dần xuống giọng ở thành phần đứng sau trọng âm.","zh":"特指问句的句调","py":"tèzhǐ wènjù de jùdiào","tag":"Ngữ điệu","vi":"Nhấn đại từ nghi vấn · xuống giọng ↘","listZh":"特指问句的句调","listVi":"Nhấn mạnh đại từ nghi vấn, sau đó xuống giọng dần ↘","descZh":"疑问代词重读，重音之后全句句调逐渐下降。","descVi":"Với loại câu hỏi này, ta đọc nhấn mạnh đại từ nghi vấn và dần dần xuống giọng ở thành phần đứng sau trọng âm.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"疑问代词","s":"đại từ nghi vấn · nhấn","st":true},{"l":"降调 ↘","s":"xuống giọng dần","dn":true}]],"tip":"Đại từ nghi vấn (<span class=\"zh\">谁</span>, <span class=\"zh\">什么</span>, <span class=\"zh\">多少</span>…) đã mang ý hỏi nên cuối câu <b>không lên giọng</b> như câu có <span class=\"zh\">吗</span> — nhấn mạnh từ để hỏi rồi <b>hạ giọng dần ↘</b>.","readLbl":"Luyện đọc · nhấn đại từ nghi vấn ↘","sents":[{"tone":"down","w":[{"hz":"这","py":"Zhè"},{"hz":"是","py":"shì"},{"hz":"谁","py":"shéi","st":true},{"hz":"的笔？","py":"de bǐ?"}],"vi":"Đây là bút của ai?"},{"tone":"down","w":[{"hz":"你们","py":"Nǐmen"},{"hz":"学校","py":"xuéxiào"},{"hz":"有","py":"yǒu"},{"hz":"多少","py":"duōshao","st":true},{"hz":"学生？","py":"xuésheng?"}],"vi":"Trường các bạn có bao nhiêu học sinh?"},{"tone":"down","w":[{"hz":"你","py":"Nǐ"},{"hz":"在","py":"zài","j":true},{"hz":"找","py":"zhǎo"},{"hz":"什么？","py":"shénme?","st":true}],"vi":"Bạn đang tìm gì thế?"}]}],"activity":{"act":[{"zh":"双人活动","py":"shuāngrén huódòng","tag":"Hoạt động theo cặp","mean":"","q":{"zh":"两人一组，选择下列词语，用\"不要……了\"\"别……了\"练习说句子。","py":"Liǎng rén yì zǔ, xuǎnzé xiàliè cíyǔ, yòng \"búyào……le\" \"bié……le\" liànxí shuō jùzi.","vi":"Hai người một cặp, chọn các từ ngữ bên dưới, dùng 不要……了 / 别……了 để đặt câu và luyện nói."},"items":[],"pattern":{"parts":[{"slot":"Khuyên ngăn"},{"slot":"Việc đang làm"},{"zh":"了","py":"le"},{"zh":"，","py":""},{"slot":"Lí do"},{"zh":"。","py":""}],"vi":"[Khuyên ngăn] [Việc đang làm] nữa, [Lí do]."},"banks":[{"lbl":"Khuyên ngăn","zh":"劝阻","items":[{"zh":"不要","py":"búyào","vi":"đừng"},{"zh":"别","py":"bié","vi":"đừng"}]},{"lbl":"Việc đang làm","zh":"动作","items":[{"zh":"玩手机","py":"wán shǒujī","vi":"chơi điện thoại"},{"zh":"看电视","py":"kàn diànshì","vi":"xem tivi"},{"zh":"喝咖啡","py":"hē kāfēi","vi":"uống cà phê"},{"zh":"买新衣服","py":"mǎi xīn yīfu","vi":"mua quần áo mới"},{"zh":"吃药","py":"chī yào","vi":"uống thuốc"},{"zh":"玩电脑","py":"wán diànnǎo","vi":"chơi máy tính"},{"zh":"看报纸","py":"kàn bàozhǐ","vi":"đọc báo"},{"zh":"睡觉","py":"shuìjiào","vi":"ngủ"}]},{"lbl":"Lí do","zh":"原因","items":[{"zh":"明天有课","py":"míngtiān yǒu kè","vi":"mai còn có tiết học"},{"zh":"对身体不好","py":"duì shēntǐ bù hǎo","vi":"không tốt cho sức khoẻ"},{"zh":"很晚了","py":"hěn wǎn le","vi":"muộn rồi"},{"zh":"病好了","py":"bìng hǎo le","vi":"khỏi bệnh rồi"},{"zh":"要多休息","py":"yào duō xiūxi","vi":"phải nghỉ ngơi nhiều"},{"zh":"太贵了","py":"tài guì le","vi":"đắt quá"},{"zh":"快睡觉吧","py":"kuài shuìjiào ba","vi":"mau đi ngủ đi"}]}]}],"speak":[]}},{"id":"k2v2-b11","courseId":"k2v2","order":11,"title":"Anh ấy lớn hơn mình ba tuổi.","titleZh":"他比我大三岁。","titlePy":"tā bǐ wǒ dà sān suì","vocab":[{"stt":1,"hanzi":"唱歌","pinyin":"chànggē","hanviet":"Xướng ca","pos":"Động từ","meaning":"hát, ca hát","comps":"爱唱歌 (thích hát), 唱中文歌 (hát bài tiếng Trung)","example":{"zh":"我妹妹很喜欢唱歌。","py":"Wǒ mèimei hěn xǐhuan chànggē.","vi":"Em gái mình rất thích hát."}},{"stt":2,"hanzi":"男","pinyin":"nán","hanviet":"Nam","pos":"Danh từ","meaning":"nam, con trai","comps":"男朋友 (bạn trai), 男孩子 (bé trai)","example":{"zh":"是不是男朋友？","py":"Shì bu shì nán péngyou?","vi":"Có phải bạn trai không?"}},{"stt":3,"hanzi":"女","pinyin":"nǚ","hanviet":"Nữ","pos":"Danh từ","meaning":"nữ, con gái","comps":"女孩子 (bé gái), 女朋友 (bạn gái)","example":{"zh":"那个女孩子是我姐姐。","py":"Nàge nǚ háizi shì wǒ jiějie.","vi":"Cô gái đó là chị của mình."}},{"stt":4,"hanzi":"孩子","pinyin":"háizi","hanviet":"Hài tử","pos":"Danh từ","meaning":"trẻ con; con cái","comps":"女孩子 (bé gái), 两个孩子 (hai đứa con)","example":{"zh":"那个孩子是谁？","py":"Nàge háizi shì shéi?","vi":"Đứa bé đó là ai vậy?"}},{"stt":5,"hanzi":"右边","pinyin":"yòubian","hanviet":"Hữu biên","pos":"Danh từ","meaning":"bên phải, phía phải","comps":"在右边 (ở bên phải), 右边的 (cái bên phải)","example":{"zh":"右边写字的人是我哥哥。","py":"Yòubian xiě zì de rén shì wǒ gēge.","vi":"Người viết chữ bên phải là anh trai mình."}},{"stt":6,"hanzi":"比","pinyin":"bǐ","hanviet":"Tỉ","pos":"Giới từ","meaning":"so với, hơn (so sánh)","comps":"比我大 (lớn hơn tôi), 比昨天 (so với hôm qua)","example":{"zh":"他比我大三岁。","py":"Tā bǐ wǒ dà sān suì.","vi":"Anh ấy hơn mình ba tuổi."}},{"stt":7,"hanzi":"便宜","pinyin":"piányi","hanviet":"Tiện nghi","pos":"Tính từ","meaning":"rẻ, giá thấp","comps":"很便宜 (rất rẻ), 便宜一些 (rẻ hơn một chút)","example":{"zh":"今天的西瓜比昨天便宜。","py":"Jīntiān de xīguā bǐ zuótiān piányi.","vi":"Dưa hấu hôm nay rẻ hơn hôm qua."}},{"stt":8,"hanzi":"说话","pinyin":"shuōhuà","hanviet":"Thuyết thoại","pos":"Động từ","meaning":"nói chuyện, nói","comps":"说话的人 (người đang nói), 别说话 (đừng nói chuyện)","example":{"zh":"前边说话的人是老师。","py":"Qiánbian shuōhuà de rén shì lǎoshī.","vi":"Người đang nói phía trước là thầy giáo."}},{"stt":9,"hanzi":"可能","pinyin":"kěnéng","hanviet":"Khả năng","pos":"Động từ","meaning":"có thể, có lẽ","comps":"可能不来 (có lẽ không đến), 不可能 (không thể nào)","example":{"zh":"你可能不认识他。","py":"Nǐ kěnéng bú rènshi tā.","vi":"Có lẽ bạn không quen anh ấy."}},{"stt":10,"hanzi":"去年","pinyin":"qùnián","hanviet":"Khứ niên","pos":"Danh từ","meaning":"năm ngoái","comps":"去年来的 (đến từ năm ngoái), 去年冬天 (mùa đông năm ngoái)","example":{"zh":"他是去年来的。","py":"Tā shì qùnián lái de.","vi":"Anh ấy đến từ năm ngoái."}},{"stt":11,"hanzi":"姓","pinyin":"xìng","hanviet":"Tính","pos":"Động từ","meaning":"họ là; họ (tên họ)","comps":"姓王 (họ Vương), 您贵姓 (ngài quý danh)","example":{"zh":"他姓王，是我的老师。","py":"Tā xìng Wáng, shì wǒ de lǎoshī.","vi":"Thầy ấy họ Vương, là thầy của mình."}}],"hanzi":[{"char":"唱歌","pinyin":"chànggē","hanviet":"Xướng ca","chars":["唱","歌"],"story":"唱 = 口 (bộ Khẩu, cái miệng) chỉ nghĩa + 昌 chāng chỉ âm — tiếng cất ra từ miệng. 歌 = 哥 (chỉ âm) + 欠 (vẽ người há miệng thở ra). 唱歌 là cất tiếng hát."},{"char":"男","pinyin":"nán","hanviet":"Nam","chars":["男"],"story":"男 gồm 田 (thửa ruộng) ở trên và 力 (sức lực) ở dưới: người ra đồng bỏ sức cày cấy. Từ hình ảnh đó mà 男 chỉ đàn ông, con trai."},{"char":"女","pinyin":"nǚ","hanviet":"Nữ","chars":["女"],"story":"女 là chữ tượng hình, vẽ dáng một người phụ nữ đang quỳ, hai tay khoanh trước ngực. Đây cũng là bộ thủ của rất nhiều chữ chỉ người nữ: 妈, 姐, 妹, 姓."},{"char":"孩子","pinyin":"háizi","hanviet":"Hài tử","chars":["孩","子"],"story":"孩 = 子 (đứa trẻ) chỉ nghĩa + 亥 hài chỉ âm đọc. Chữ 子 vốn vẽ em bé quấn tã, hai tay giơ ra. 孩子 là từ quen dùng để gọi trẻ con, con cái."},{"char":"右边","pinyin":"yòubian","hanviet":"Hữu biên","chars":["右","边"],"story":"右 gồm bàn tay và 口 (cái miệng) — tay phải là tay đưa thức ăn lên miệng. 边 = 辶 (bộ Sước, bước đi) + 力, nghĩa là mép, phía. 右边 là phía tay phải, đối lại với 左边 đã học ở bài 3."},{"char":"比","pinyin":"bǐ","hanviet":"Tỉ","chars":["比"],"story":"比 vẽ hai người đứng cùng chiều sát kề nhau, như đang đọ xem ai cao hơn ai. Từ hình ảnh so kề ấy mà ra nghĩa \"so sánh, hơn\"."},{"char":"便宜","pinyin":"piányi","hanviet":"Tiện nghi","chars":["便","宜"],"story":"便 = 亻 (bộ Nhân) + 更 (đổi) — người sửa cho thuận tiện. 宜 = 宀 (mái nhà) + 且, nghĩa là thích hợp. 便宜 vốn là \"thuận lợi\", nay hay dùng nhất với nghĩa \"rẻ\". Ở đây 便 đọc pián, không đọc biàn."},{"char":"说话","pinyin":"shuōhuà","hanviet":"Thuyết thoại","chars":["说","话"],"story":"说 = 讠 bộ Ngôn (lời nói) + 兑 chỉ âm. 话 cũng có 讠 bên trái, bên phải là 舌 (cái lưỡi) — lời bật ra từ đầu lưỡi. 说话 nghĩa là cất lời, nói chuyện."},{"char":"可能","pinyin":"kěnéng","hanviet":"Khả năng","chars":["可","能"],"story":"可 vẽ cái miệng thốt lời ưng thuận, nghĩa là \"được, có thể\". 能 vốn vẽ con gấu, sau mượn làm \"có sức làm được\". Ghép lại 可能 là việc có thể xảy ra — \"có lẽ\"."},{"char":"去年","pinyin":"qùnián","hanviet":"Khứ niên","chars":["去","年"],"story":"去 nghĩa gốc là rời đi, bỏ đi; ghép với 年 (năm) thành \"năm đã đi qua\" — năm ngoái. Cùng khuôn với 今年 (năm nay) và 明年 (năm tới) đã học."},{"char":"姓","pinyin":"xìng","hanviet":"Tính","chars":["姓"],"story":"姓 = 女 (bộ Nữ, người phụ nữ) + 生 (sinh ra). Thời xa xưa con cái theo họ mẹ nên chữ chỉ dòng họ lấy bộ 女; phần 生 shēng đồng thời gợi âm đọc xìng."}],"grammar":[{"title":"Cụm động từ làm định ngữ (动词结构做定语)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词结构</b><small>cụm động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>trợ từ nối</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>người / vật</small></span></div>","summary":"<p class=\"gr-lead\">Tả rõ người đang nói tới</p><ul><li>Đặt cụm động từ <b>trước</b> danh từ để tả rõ người hoặc vật đó <b>đang làm gì</b>; giữa hai phần <b>bắt buộc</b> có <span class=\"zh\">的</span>.</li><li>Bài 3 đã học <span class=\"zh\">的字短语</span> (<span class=\"zh\">红色的</span>); ở đây phần đứng trước <span class=\"zh\">的</span> là <b>cụm động từ</b> chứ không phải tính từ.</li><li>Có thể thêm nơi chốn hoặc <span class=\"zh\">这 / 那</span> ra ngoài cùng: <span class=\"zh\">左边这个看报纸的女孩子</span>.</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">定语 · 汉语 ↔ 越南语</span> · So sánh</h4><p>Hai thứ tiếng ngược trật tự</p><ul><li><b>Định ngữ</b> (<span class=\"zh\">定语</span>) = thành phần <b>bổ sung ý nghĩa</b> cho danh từ: ai làm, làm gì, như thế nào</li><li><b>Vị trí:</b> tiếng Trung — đứng <b>trước</b> danh từ, nối bằng <span class=\"zh\">的</span> · tiếng Việt — đứng <b>sau</b> danh từ</li></ul><div class=\"gr-formula\"><div class=\"fx-lbl\">Tiếng Trung</div><div class=\"fx-row\"><span class=\"fx-p c-a\"><b>定语</b><small>thành phần bổ sung ý nghĩa</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>的</b><small>trợ từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>名词</b><small>danh từ</small></span></div><div class=\"fx-ex zh\">看报纸的女孩子</div><div class=\"fx-lbl\">Tiếng Việt</div><div class=\"fx-row\"><span class=\"fx-p\"><b>名词</b><small>danh từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>定语</b><small>thành phần bổ sung ý nghĩa</small></span></div><div class=\"fx-ex zh\">cô bé đang đọc báo</div></div><p class=\"gr-key\"><span class=\"hot\">Tiếng Trung: <b>bổ sung</b> + <span class=\"zh\">的</span> + <b>danh từ</b>　·　Tiếng Việt: <b>danh từ</b> + <b>bổ sung</b></span></p></div><div class=\"gr-sub\"><h4><span class=\"zh\">动词结构做定语</span> · Ví dụ</h4><p>Đối chiếu trật tự tiếng Việt</p><div class=\"ct-box\"><div class=\"ct-cap\">Ví dụ · Đối chiếu tiếng Việt</div><div class=\"ct-intro\"><span class=\"ct-lg a\">Thành phần bổ sung ý nghĩa</span><span class=\"ct-lg k\">的</span><span class=\"ct-lg b\">Danh từ</span>cùng màu = cùng thành phần, sang tiếng Việt chỉ <b>đổi chỗ</b></div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Tiếng Trung<small>Bổ sung + 的 + Danh từ</small></th><th>Tiếng Việt<small>Danh từ + Bổ sung</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">新买</b><small>xīn mǎi</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">自行车</b><small>zìxíngchē</small></span></div><div class=\"ct-vi\">mới mua + 的 + xe đạp</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">chiếc xe đạp</span><span class=\"ct-w c-a\">mới mua</span></div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">我妈妈做</b><small>wǒ māma zuò</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">饭</b><small>fàn</small></span></div><div class=\"ct-vi\">mẹ tôi nấu + 的 + cơm</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">cơm</span><span class=\"ct-w c-a\">mẹ tôi nấu</span></div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">和你一起唱歌</b><small>hé nǐ yìqǐ chànggē</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">人</b><small>rén</small></span></div><div class=\"ct-vi\">cùng bạn hát + 的 + người</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">người</span><span class=\"ct-w c-a\">hát cùng bạn</span></div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\"><b class=\"zh\">我昨天看</b><small>wǒ zuótiān kàn</small></span><span class=\"ct-w c-k\"><b class=\"zh\">的</b><small>de</small></span><span class=\"ct-w c-b\"><b class=\"zh\">电影</b><small>diànyǐng</small></span></div><div class=\"ct-vi\">tôi hôm qua xem + 的 + phim</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-b\">bộ phim</span><span class=\"ct-w c-a\">tôi xem hôm qua</span></div></td></tr></tbody></table></div></div></div><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">看报纸的女孩子</span> = cô bé đang đọc báo　·　<span class=\"zh\">写字的那个人</span> = người đang viết chữ</p>","note":"<b>Lưu ý:</b> Tiếng Việt nói ngược — \"cô bé <b>đang đọc báo</b>\", tiếng Trung phải đưa cụm động từ <b>lên trước</b>: <span class=\"zh\">看报纸的女孩子</span>, không nói <span class=\"zh\">女孩子看报纸的</span>.<br>Cụm động từ làm định ngữ <b>phải có</b> <span class=\"zh\">的</span>: <span class=\"zh\">妈妈做的饭</span> = cơm mẹ nấu — ✗ <span class=\"zh\">妈妈做饭</span> = mẹ nấu cơm","examples":[{"zh":"左边看报纸的女孩子是我姐姐。","py":"Zuǒbian kàn bàozhǐ de nǚ háizi shì wǒ jiějie.","vi":"Cô gái đang đọc báo bên trái là chị của mình."}],"exercises":[]},{"title":"Câu chữ 比 (1)","formula":"","summary":"<p class=\"gr-lead\">So sánh A với B — A hơn B</p><ul><li><b>Ý nghĩa:</b> diễn tả sự <b>so sánh</b> giữa đối tượng <b>A</b> và đối tượng <b>B</b> theo một tính chất, đặc điểm nào đó</li><li><b>Vị trí:</b> <span class=\"zh\">比</span> (giới từ) đứng <b>giữa A và B</b> · tính từ đứng <b>cuối câu</b></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">\"比\"字句 · 否定</span> · Khẳng định · Phủ định</h4><p>Phủ định dùng 没有, không dùng 不比</p><div class=\"ct-box\"><div class=\"ct-cap\">Ví dụ · Khẳng định ↔ Phủ định</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Khẳng định<small>A 比 B + tính từ</small></th><th>Phủ định<small>A 没有 B + tính từ</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">哥哥</b><small>Gēge</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比</b><small>bǐ</small></span><span class=\"ct-w c-\"><b class=\"zh\">姐姐</b><small>jiějie</small></span><span class=\"ct-w c-a\"><b class=\"zh\">高。</b><small>gāo.</small></span></div><div class=\"ct-vi\">Anh trai cao hơn chị gái.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">哥哥</b><small>Gēge</small></span><span class=\"ct-w c-k\"><b class=\"zh\">没有</b><small>méiyǒu</small></span><span class=\"ct-w c-\"><b class=\"zh\">姐姐</b><small>jiějie</small></span><span class=\"ct-w c-a\"><b class=\"zh\">高。</b><small>gāo.</small></span></div><div class=\"ct-vi\">Anh trai không cao bằng chị gái.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">今天</b><small>Jīntiān</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比</b><small>bǐ</small></span><span class=\"ct-w c-\"><b class=\"zh\">昨天</b><small>zuótiān</small></span><span class=\"ct-w c-a\"><b class=\"zh\">热。</b><small>rè.</small></span></div><div class=\"ct-vi\">Hôm nay nóng hơn hôm qua.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">今天</b><small>Jīntiān</small></span><span class=\"ct-w c-k\"><b class=\"zh\">没有</b><small>méiyǒu</small></span><span class=\"ct-w c-\"><b class=\"zh\">昨天</b><small>zuótiān</small></span><span class=\"ct-w c-a\"><b class=\"zh\">热。</b><small>rè.</small></span></div><div class=\"ct-vi\">Hôm nay không nóng bằng hôm qua.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">（今天的西瓜）</b><small>(Jīntiān de xīguā)</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比</b><small>bǐ</small></span><span class=\"ct-w c-\"><b class=\"zh\">昨天的</b><small>zuótiān de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">便宜。</b><small>piányi.</small></span></div><div class=\"ct-vi\">(Dưa hấu hôm nay) rẻ hơn (dưa) hôm qua.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">今天的西瓜</b><small>Jīntiān de xīguā</small></span><span class=\"ct-w c-k\"><b class=\"zh\">没有</b><small>méiyǒu</small></span><span class=\"ct-w c-\"><b class=\"zh\">昨天的</b><small>zuótiān de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">便宜。</b><small>piányi.</small></span></div><div class=\"ct-vi\">Dưa hấu hôm nay không rẻ bằng (dưa) hôm qua.</div></td></tr></tbody></table></div></div></div><div class=\"gr-sub\"><h4><span class=\"zh\">\"比\"字句 · 副词</span> · Mở rộng</h4><p>Phó từ đứng trước tính từ</p><ul><li><b>Được dùng:</b> <span class=\"zh\">更</span> gèng (càng … hơn) · <span class=\"zh\">还</span> hái (còn … hơn) — nhấn mạnh mức chênh lệch</li></ul><div class=\"gr-formula\"><div class=\"fx-lbl\">✓ Được dùng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>更 / 还</b><small>càng / còn</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span></div><div class=\"fx-ex zh\">哥哥比姐姐更高。</div><div class=\"fx-lbl\">✗ Không dùng</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>很 / 非常…</b><small>rất / quá…</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span></div><div class=\"fx-ex zh\">✗ 今天比昨天很热。</div></div><p class=\"gr-key\"><span class=\"zh\">今天比昨天还热。</span> = Hôm nay còn nóng hơn hôm qua　·　<span class=\"hot\"><span class=\"zh\">比</span> đã mang nghĩa \"hơn\" → chỉ thêm <span class=\"zh\">更 / 还</span></span></p></div><div class=\"gr-sub\"><h4><span class=\"zh\">\"比\"字句 · 程度</span> · Mở rộng</h4><p>Hơn bao nhiêu? — đặt sau tính từ</p><ul><li><b>Vị trí:</b> mức độ / số lượng đứng <b>sau tính từ</b>: <span class=\"zh\">热3度</span> nóng hơn 3 độ · <span class=\"zh\">大三岁</span> hơn 3 tuổi</li></ul><div class=\"gr-formula\"><div class=\"fx-lbl\">Ít · một chút</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A 比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>一些 / 一点儿</b><small>hơn một chút</small></span></div><div class=\"fx-ex zh\">苹果比昨天便宜一些。</div><div class=\"fx-lbl\">Nhiều · hơn hẳn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A 比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>得多 / 多了</b><small>hơn nhiều</small></span></div><div class=\"fx-ex zh\">今天比昨天热多了。</div><div class=\"fx-lbl\">Số lượng cụ thể</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A 比 B</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>形容词</b><small>tính từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>数量</b><small>số + đơn vị</small></span></div><div class=\"fx-ex zh\">哥哥比姐姐高2厘米。</div></div></div>","note":"<b>Lưu ý:</b> <b>Không dùng:</b> <span class=\"zh\">很、非常、太、真、特别、最</span> … — ✗ <span class=\"zh\">哥哥比姐姐很高</span>","examples":[{"zh":"他比我大三岁。","py":"Tā bǐ wǒ dà sān suì.","vi":"Anh ấy hơn mình ba tuổi."}],"exercises":[]},{"title":"Động từ năng nguyện 可能","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>可能</b><small>có lẽ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span></div>","summary":"<p class=\"gr-lead\">Đoán việc có thể xảy ra</p><ul><li><span class=\"zh\">可能</span> đặt <b>trước động từ</b>, dùng khi người nói <b>đoán</b> chứ chưa chắc chắn.</li><li>Bài 10 HSK1 đã học <span class=\"zh\">能</span> (đủ điều kiện để làm); <span class=\"zh\">可能</span> khác hẳn — nói về <b>khả năng xảy ra</b> của sự việc.</li><li>Có thể đứng một mình để trả lời: <span class=\"zh\">— 他会来吗？ — 可能。</span> = \"Có lẽ vậy.\"</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">你可能不认识他。</span> = Có lẽ bạn không quen anh ấy.</p>","note":"<b>Lưu ý:</b> Phân biệt kỹ: <span class=\"zh\">可能不来</span> = \"có lẽ không đến\" (vẫn còn khả năng), còn <span class=\"zh\">不可能来</span> = \"không thể nào đến\".","examples":[{"zh":"他可能早就知道这件事情了。","py":"Tā kěnéng zǎo jiù zhīdào zhè jiàn shìqing le.","vi":"Có lẽ anh ấy đã biết chuyện này từ lâu rồi."},{"zh":"可能我明天不来上课了。","py":"Kěnéng wǒ míngtiān bù lái shàngkè le.","vi":"Có lẽ ngày mai tôi không đến lớp nữa."},{"zh":"你可能不认识她。","py":"Nǐ kěnéng bú rènshi tā.","vi":"Có lẽ bạn không quen cô ấy."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在歌厅","titleVi":"Ở quán hát — hỏi chuyện hôm qua","lines":[{"speaker":"甲","name":"Bạn A","zh":"王方，昨天和你一起唱的人是谁？","py":"Wáng Fāng, zuótiān hé nǐ yìqǐ chàng de rén shì shéi?","vi":"Vương Phương này, người hát cùng cậu hôm qua là ai thế?"},{"speaker":"方","name":"Vương Phương","zh":"一个朋友。","py":"Yí ge péngyou.","vi":"Một người bạn thôi."},{"speaker":"甲","name":"Bạn A","zh":"什么朋友？是不是男朋友？","py":"Shénme péngyou? Shì bu shì nán péngyou?","vi":"Bạn kiểu gì? Có phải bạn trai không đấy?"},{"speaker":"方","name":"Vương Phương","zh":"不是不是，我同学介绍的，昨天第一次见。","py":"Bú shì bú shì, wǒ tóngxué jièshào de, zuótiān dì yī cì jiàn.","vi":"Không phải không phải, bạn cùng lớp mình giới thiệu, hôm qua mới gặp lần đầu."}]},{"titleZh":"课文二 · 在宿舍","titleVi":"Trong ký túc xá — xem ảnh gia đình","lines":[{"speaker":"甲","name":"Bạn A","zh":"左边这个看报纸的女孩子是你姐姐吗？","py":"Zuǒbian zhège kàn bàozhǐ de nǚ háizi shì nǐ jiějie ma?","vi":"Cô gái đang đọc báo bên trái là chị của bạn à?"},{"speaker":"乙","name":"Bạn B","zh":"是，右边写字的那个人是我哥哥。","py":"Shì, yòubian xiě zì de nàge rén shì wǒ gēge.","vi":"Đúng rồi, còn người viết chữ bên phải là anh trai mình."},{"speaker":"甲","name":"Bạn A","zh":"你哥哥多大？","py":"Nǐ gēge duō dà?","vi":"Anh trai bạn bao nhiêu tuổi?"},{"speaker":"乙","name":"Bạn B","zh":"25岁，她比我大三岁。","py":"Èrshíwǔ suì, tā bǐ wǒ dà sān suì.","vi":"25 tuổi, anh ấy hơn mình ba tuổi."}]},{"titleZh":"课文三 · 在商店","titleVi":"Ở cửa hàng — hỏi giá dưa hấu","lines":[{"speaker":"甲","name":"Bạn A","zh":"今天的西瓜怎么卖？","py":"Jīntiān de xīguā zěnme mài?","vi":"Dưa hấu hôm nay bán thế nào ạ?"},{"speaker":"乙","name":"Bạn B","zh":"¥3.51斤。","py":"Sān kuài wǔ yì jīn.","vi":"3,5 tệ một cân."},{"speaker":"甲","name":"Bạn A","zh":"比昨天便宜。","py":"Bǐ zuótiān piányi.","vi":"Rẻ hơn hôm qua rồi đấy."},{"speaker":"乙","name":"Bạn B","zh":"是，苹果也比昨天便宜一些。您来点吧。","py":"Shì, píngguǒ yě bǐ zuótiān piányi yìxiē. Nín lái diǎn ba.","vi":"Vâng, táo cũng rẻ hơn hôm qua một chút. Bác mua một ít đi ạ."}]},{"titleZh":"课文四 · 在学校","titleVi":"Ở trường — nói về thầy giáo mới","lines":[{"speaker":"甲","name":"Bạn A","zh":"前边说话的那个人就是我的汉语老师。你可能不认识他。","py":"Qiánbian shuōhuà de nàge rén jiù shì wǒ de Hànyǔ lǎoshī. Nǐ kěnéng bú rènshi tā.","vi":"Người đang nói ở phía trước chính là thầy dạy tiếng Trung của mình. Có lẽ bạn chưa quen thầy ấy."},{"speaker":"乙","name":"Bạn B","zh":"是新来的汉语老师吗？","py":"Shì xīn lái de Hànyǔ lǎoshī ma?","vi":"Là thầy tiếng Trung mới đến à?"},{"speaker":"甲","name":"Bạn A","zh":"是去年来的，他姓王，28岁。","py":"Shì qùnián lái de, tā xìng Wáng, èrshíbā suì.","vi":"Thầy đến từ năm ngoái, thầy họ Vương, 28 tuổi."},{"speaker":"乙","name":"Bạn B","zh":"他比我们老师小两岁。","py":"Tā bǐ wǒmen lǎoshī xiǎo liǎng suì.","vi":"Thầy ấy kém thầy của bọn mình hai tuổi."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu của câu hỏi có thành phần khẳng định và phủ định","introZh":"句中肯定部分重读，否定部分轻读，肯定否定重叠部分语速较快，重音后语调逐渐下降。","introVi":"Với loại câu hỏi này, ta đọc nhấn mạnh ở thành phần khẳng định, đọc nhẹ ở thành phần phủ định, đọc lướt nhanh ở thành phần khẳng định-phủ định và xuống giọng ở thành phần đứng sau trọng âm.","zh":"正反问句的句调","py":"","tag":"Ngữ điệu","vi":"Nhấn khẳng định · xuống giọng ↘","listZh":"正反问句的句调","listVi":"Câu hỏi khẳng định + phủ định — nhấn phần khẳng định, phủ định đọc nhẹ, xuống giọng ↘","descZh":"句中肯定部分重读，否定部分轻读，肯定否定重叠部分语速较快，重音后语调逐渐下降。","descVi":"Với loại câu hỏi này, ta đọc nhấn mạnh ở thành phần khẳng định, đọc nhẹ ở thành phần phủ định, đọc lướt nhanh ở thành phần khẳng định-phủ định và xuống giọng ở thành phần đứng sau trọng âm.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"肯定部分","s":"khẳng định · nhấn","st":true},{"l":"否定部分","s":"phủ định · đọc nhẹ","lt":true}],[{"l":"肯定否定","s":"đọc lướt nhanh"},{"l":"降调 ↘","s":"xuống giọng dần","dn":true}]],"tip":"Nhấn phần <b>khẳng định</b> (chữ có chấm đỏ), <span class=\"zh\">不</span> + phần lặp lại đọc <b>nhẹ, nhanh</b>, sau trọng âm <b>hạ giọng dần ↘</b> — khác câu hỏi <span class=\"zh\">吗</span> (bài 9) lên giọng ↗.","readLbl":"Luyện đọc · chữ có chấm đỏ đọc nhấn · ↘ xuống giọng","sents":[{"tone":"down","w":[{"hz":"明天","py":"Míngtiān"},{"hz":"你","py":"nǐ"},{"hz":"去","py":"qù","st":true},{"hz":"不去","py":"bu qù","j":true},{"hz":"银行？","py":"yínháng?"}],"vi":"Ngày mai bạn có đi ngân hàng không?"},{"tone":"down","w":[{"hz":"这","py":"Zhè"},{"hz":"件衣服","py":"jiàn yīfu"},{"hz":"你","py":"nǐ"},{"hz":"喜欢","py":"xǐhuan","st":true},{"hz":"不喜欢？","py":"bu xǐhuan?"}],"vi":"Bộ quần áo này bạn có thích không?"},{"tone":"down","w":[{"hz":"十一点","py":"Shíyī diǎn"},{"hz":"多了，","py":"duō le,"},{"hz":"你","py":"nǐ"},{"hz":"睡","py":"shuì","st":true},{"hz":"不睡","py":"bu shuì","j":true},{"hz":"觉？","py":"jiào?","j":true}],"vi":"Hơn mười một giờ rồi, bạn có đi ngủ không?"}]}]},{"id":"k2v2-b12","courseId":"k2v2","order":12,"title":"Anh mặc ít quần áo quá","titleZh":"你穿得太少了","titlePy":"nǐ chuān de tài shǎo le","vocab":[{"stt":1,"hanzi":"得","pinyin":"de","hanviet":"Đắc","pos":"Trợ từ","meaning":"trợ từ nối bổ ngữ","comps":"睡得早 (ngủ sớm), 吃得多 (ăn nhiều)","example":{"zh":"我睡得很早。","py":"Wǒ shuì de hěn zǎo.","vi":"Mình ngủ rất sớm."}},{"stt":2,"hanzi":"妻子","pinyin":"qīzi","hanviet":"Thê tử","pos":"Danh từ","meaning":"vợ","comps":"我妻子 (vợ tôi), 妻子和孩子 (vợ con)","example":{"zh":"我妻子比我做得好。","py":"Wǒ qīzi bǐ wǒ zuò de hǎo.","vi":"Vợ mình nấu ngon hơn mình."}},{"stt":3,"hanzi":"雪","pinyin":"xuě","hanviet":"Tuyết","pos":"Danh từ","meaning":"tuyết","comps":"下雪 (rơi tuyết), 大雪 (tuyết lớn)","example":{"zh":"今天下雪了，真冷。","py":"Jīntiān xià xuě le, zhēn lěng.","vi":"Hôm nay tuyết rơi, lạnh thật."}},{"stt":4,"hanzi":"零","pinyin":"líng","hanviet":"Linh","pos":"Số từ","meaning":"số không; lẻ","comps":"零下 (dưới không độ), 一百零五 (một trăm linh năm)","example":{"zh":"今天有零下十度。","py":"Jīntiān yǒu líng xià shí dù.","vi":"Hôm nay âm mười độ."}},{"stt":5,"hanzi":"度","pinyin":"dù","hanviet":"Độ","pos":"Lượng từ","meaning":"độ (đơn vị nhiệt độ)","comps":"十度 (mười độ), 零下五度 (âm năm độ)","example":{"zh":"房间里有二十度。","py":"Fángjiān lǐ yǒu èrshí dù.","vi":"Trong phòng hai mươi độ."}},{"stt":6,"hanzi":"穿","pinyin":"chuān","hanviet":"Xuyên","pos":"Động từ","meaning":"mặc, đi (giày)","comps":"穿衣服 (mặc quần áo), 穿鞋 (đi giày)","example":{"zh":"你穿的衣服太少了。","py":"Nǐ chuān de yīfu tài shǎo le.","vi":"Áo bạn mặc mỏng quá rồi."}},{"stt":7,"hanzi":"进","pinyin":"jìn","hanviet":"Tiến","pos":"Động từ","meaning":"vào, đi vào","comps":"进房间 (vào phòng), 进来 (vào đây)","example":{"zh":"我们进房间吧。","py":"Wǒmen jìn fángjiān ba.","vi":"Chúng mình vào phòng đi."}},{"stt":8,"hanzi":"弟弟","pinyin":"dìdi","hanviet":"Đệ đệ","pos":"Danh từ","meaning":"em trai","comps":"我弟弟 (em trai tôi), 弟弟和妹妹 (em trai em gái)","example":{"zh":"我弟弟让我帮他找房子。","py":"Wǒ dìdi ràng wǒ bāng tā zhǎo fángzi.","vi":"Em trai nhờ mình tìm giúp nhà."}},{"stt":9,"hanzi":"近","pinyin":"jìn","hanviet":"Cận","pos":"Tính từ","meaning":"gần","comps":"很近 (rất gần), 近一点儿 (gần hơn một chút)","example":{"zh":"他家离公司很近。","py":"Tā jiā lí gōngsī hěn jìn.","vi":"Nhà anh ấy gần công ty."}}],"hanzi":[{"char":"得","pinyin":"de","hanviet":"Đắc","chars":["得"],"story":"得 gồm 彳 (bộ Xích, bước chân) + phần giữa vẽ vật quý + 寸 (bàn tay): đi đường nhặt được của. Nghĩa gốc là \"được, đạt được\" (đọc dé); khi làm trợ từ nối bổ ngữ thì đọc nhẹ thành de."},{"char":"妻子","pinyin":"qīzi","hanviet":"Thê tử","chars":["妻","子"],"story":"妻 có 女 (người phụ nữ) ở dưới, phía trên vẽ bàn tay đang cài trâm lên tóc — người con gái đã búi tóc là đã lập gia đình. 妻子 là từ ghép chỉ người vợ."},{"char":"雪","pinyin":"xuě","hanviet":"Tuyết","chars":["雪"],"story":"雪 gồm 雨 (bộ Vũ, mưa) ở trên, phần dưới vốn vẽ bàn tay cầm chổi. Thứ từ trời rơi xuống mà lại quét gom lại được thì chỉ có thể là tuyết."},{"char":"零","pinyin":"líng","hanviet":"Linh","chars":["零"],"story":"零 = 雨 (bộ Vũ, mưa) chỉ nghĩa + 令 lìng chỉ âm. Nghĩa gốc là giọt mưa rơi lác đác, từ đó ra nghĩa \"lẻ, vụn\"; ngày nay còn dùng làm chữ viết của số 0."},{"char":"度","pinyin":"dù","hanviet":"Độ","chars":["度"],"story":"度 có 广 (mái nhà) bao ngoài, bên trong là 廿 và 又 (bàn tay) — người xưa dang tay ra mà đo. Nghĩa gốc là đo lường, nay dùng làm đơn vị đo: độ nhiệt, độ góc."},{"char":"穿","pinyin":"chuān","hanviet":"Xuyên","chars":["穿"],"story":"穿 = 穴 (bộ Huyệt, cái hang) ở trên + 牙 (cái răng) ở dưới: dùng răng khoét thủng qua. Nghĩa gốc là xuyên qua; mặc áo cũng là xỏ người qua ống tay áo nên dùng chữ này."},{"char":"进","pinyin":"jìn","hanviet":"Tiến","chars":["进"],"story":"进 = 辶 (bộ Sước, bước đi) + 井 jǐng chỉ âm. Bản phồn thể 進 dùng 隹 (con chim) — chim chỉ bay tới chứ không lùi, nên 进 nghĩa là tiến vào."},{"char":"弟弟","pinyin":"dìdi","hanviet":"Đệ đệ","chars":["弟","弟"],"story":"弟 vốn vẽ sợi dây quấn quanh cây cọc theo thứ tự từ dưới lên; từ hình ảnh \"thứ tự\" ấy mà chỉ người em. Giống 哥哥, chữ được lặp hai lần thành cách gọi thân trong nhà."},{"char":"近","pinyin":"jìn","hanviet":"Cận","chars":["近"],"story":"近 = 辶 (bộ Sước, bước đi) + 斤 jīn chỉ âm — chỉ cần đi vài bước là tới, nên 近 nghĩa là gần. Trái nghĩa với 远 (xa) học ở bài 7. Đừng nhầm với 进 cùng đọc jìn: 近 có 斤, 进 có 井."}],"grammar":[{"title":"Bổ ngữ trạng thái (状态补语)","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>得</b><small>trợ từ · đọc nhẹ de</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>(很 / 不) 形容词</b><small>bổ ngữ trạng thái</small></span></div>","summary":"<p class=\"gr-lead\">Làm như thế nào?</p><ul><li><b>Ý nghĩa:</b> miêu tả, đánh giá hành động được làm <b>như thế nào</b> — sớm / muộn, nhanh / chậm, hay / dở…</li><li><b>Vị trí:</b> đứng <b>sau động từ</b>, nối bằng <span class=\"zh\">得</span> · <b>Phủ định:</b> <span class=\"zh\">不</span> đặt <b>sau 得</b></li><li><b>Câu hỏi:</b> <span class=\"zh\">……得怎么样？</span> · <span class=\"zh\">……得好不好？</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">状态补语 · 无宾语</span> · Công thức</h4><p>Trường hợp không có tân ngữ</p><div class=\"ct-box\"><div class=\"ct-cap\">Công thức · Ví dụ</div><div class=\"ct-intro\"><b>Công thức:</b> Chủ ngữ + <span class=\"ct-lg b\">Động từ</span><span class=\"ct-lg k\">得</span><span class=\"ct-lg a\">很 / 不 + Tính từ</span></div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Khẳng định<small>S + V + 得 + (很) + Adj</small></th><th>Phủ định<small>S + V + 得 + 不 + Adj</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-b\"><b class=\"zh\">说</b><small>shuō</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">很好。</b><small>hěn hǎo.</small></span></div><div class=\"ct-vi\">Anh ấy nói rất hay.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-b\"><b class=\"zh\">说</b><small>shuō</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">不好。</b><small>bù hǎo.</small></span></div><div class=\"ct-vi\">Anh ấy nói không hay.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">起</b><small>qǐ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">很早。</b><small>hěn zǎo.</small></span></div><div class=\"ct-vi\">Tôi dậy rất sớm.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">起</b><small>qǐ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">不早。</b><small>bù zǎo.</small></span></div><div class=\"ct-vi\">Tôi dậy không sớm.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">睡</b><small>shuì</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">也早。</b><small>yě zǎo.</small></span></div><div class=\"ct-vi\">Tôi cũng ngủ sớm.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">睡</b><small>shuì</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">也不早。</b><small>yě bù zǎo.</small></span></div><div class=\"ct-vi\">Tôi cũng ngủ không sớm.</div></td></tr></tbody></table></div></div></div><div class=\"gr-sub\"><h4><span class=\"zh\">状态补语 · 有宾语</span> · Công thức</h4><p>Trường hợp có tân ngữ</p><div class=\"ct-box\"><div class=\"ct-cap\">Công thức · Ví dụ</div><div class=\"ct-intro\"><b>Công thức:</b> Chủ ngữ + (Động từ) + Tân ngữ + <span class=\"ct-lg b\">Động từ</span><span class=\"ct-lg k\">得</span><span class=\"ct-lg a\">很 / 不 + Tính từ</span>　→ <b>lặp lại động từ</b>, động từ trong ngoặc có thể lược bỏ</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Khẳng định<small>S + (V) + O + V + 得 + (很) + Adj</small></th><th>Phủ định<small>S + (V) + O + V + 得 + 不 + Adj</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他（说）</b><small>Tā (shuō)</small></span><span class=\"ct-w c-\"><b class=\"zh\">汉语</b><small>Hànyǔ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">说</b><small>shuō</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">很好。</b><small>hěn hǎo.</small></span></div><div class=\"ct-vi\">Anh ấy nói tiếng Trung rất giỏi.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他（说）</b><small>Tā (shuō)</small></span><span class=\"ct-w c-\"><b class=\"zh\">汉语</b><small>Hànyǔ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">说</b><small>shuō</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">不好。</b><small>bù hǎo.</small></span></div><div class=\"ct-vi\">Anh ấy nói tiếng Trung không giỏi.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我（写）</b><small>Wǒ (xiě)</small></span><span class=\"ct-w c-\"><b class=\"zh\">汉字</b><small>Hànzì</small></span><span class=\"ct-w c-b\"><b class=\"zh\">写</b><small>xiě</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">很好。</b><small>hěn hǎo.</small></span></div><div class=\"ct-vi\">Tôi viết chữ Hán rất đẹp.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我（写）</b><small>Wǒ (xiě)</small></span><span class=\"ct-w c-\"><b class=\"zh\">汉字</b><small>Hànzì</small></span><span class=\"ct-w c-b\"><b class=\"zh\">写</b><small>xiě</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">不好。</b><small>bù hǎo.</small></span></div><div class=\"ct-vi\">Tôi viết chữ Hán không đẹp.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">姐姐（唱）</b><small>Jiějie (chàng)</small></span><span class=\"ct-w c-\"><b class=\"zh\">歌</b><small>gē</small></span><span class=\"ct-w c-b\"><b class=\"zh\">唱</b><small>chàng</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">不错。</b><small>búcuò.</small></span></div><div class=\"ct-vi\">Chị gái hát khá hay.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">姐姐（唱）</b><small>Jiějie (chàng)</small></span><span class=\"ct-w c-\"><b class=\"zh\">歌</b><small>gē</small></span><span class=\"ct-w c-b\"><b class=\"zh\">唱</b><small>chàng</small></span><span class=\"ct-w c-k\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">不好。</b><small>bù hǎo.</small></span></div><div class=\"ct-vi\">Chị gái hát không hay.</div></td></tr></tbody></table></div></div></div><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">他说得很好。</span> = Anh ấy nói rất hay　·　<span class=\"hot\">Bổ ngữ trạng thái luôn đứng <b>sau</b> <span class=\"zh\">得</span></span></p>","note":"<b>Lưu ý:</b> Có <b>tân ngữ</b> → <b>lặp lại động từ</b>: <span class=\"zh\">说汉语说得很好</span> — ✗ <span class=\"zh\">说汉语得很好</span>","examples":[{"zh":"你吃得太少了。","py":"Nǐ chī de tài shǎo le.","vi":"Bạn ăn ít quá rồi."}],"exercises":[]},{"title":"Câu chữ 比 (2) · có bổ ngữ trạng thái","formula":"<div class=\"fx-lbl\">Trước động từ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比 B</b><small>so với B</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span></div><div class=\"fx-ex zh\">他比我学得好。</div><div class=\"fx-lbl\">Trước bổ ngữ</div><div class=\"fx-row\"><span class=\"fx-p\"><b>A</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>得</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>比 B</b><small>so với B</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p c-a\"><b>形容词</b><small>tính từ</small></span></div><div class=\"fx-ex zh\">他学得比我好。</div>","summary":"<p class=\"gr-lead\">So sánh cách làm</p><ul><li><b>Ý nghĩa:</b> so sánh hành động của A và B được làm <b>như thế nào</b> (nhanh hơn, tốt hơn…) · bài 11 đã học <span class=\"zh\">A 比 B + 形容词</span></li><li><b>Vị trí:</b> <span class=\"zh\">比 B</span> đặt <b>trước động từ</b> hoặc <b>trước bổ ngữ</b> (sau <span class=\"zh\">得</span>) — nghĩa như nhau</li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">\"比\"字句 · 状态补语</span> · Ví dụ</h4><p>比 B trước động từ ↔ trước bổ ngữ</p><div class=\"ct-box\"><div class=\"ct-cap\">Ví dụ · Hai vị trí của 比 B</div><div class=\"ct-intro\"><span class=\"ct-lg k\">比 B</span><span class=\"ct-lg b\">Động từ</span><span class=\"ct-lg a\">Tính từ</span>chỉ <b>đổi chỗ</b> <span class=\"zh\">比 B</span> — nghĩa như nhau</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Trước động từ<small>A + 比 B + V + 得 + Adj</small></th><th>Trước bổ ngữ<small>A + V + 得 + 比 B + Adj</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比我</b><small>bǐ wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">学</b><small>xué</small></span><span class=\"ct-w c-\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">好。</b><small>hǎo.</small></span></div><div class=\"ct-vi\">Anh ấy học giỏi hơn tôi.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-b\"><b class=\"zh\">学</b><small>xué</small></span><span class=\"ct-w c-\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比我</b><small>bǐ wǒ</small></span><span class=\"ct-w c-a\"><b class=\"zh\">好。</b><small>hǎo.</small></span></div><div class=\"ct-vi\">Anh ấy học giỏi hơn tôi.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">姐姐</b><small>Jiějie</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比我</b><small>bǐ wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">跑</b><small>pǎo</small></span><span class=\"ct-w c-\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">快。</b><small>kuài.</small></span></div><div class=\"ct-vi\">Chị gái chạy nhanh hơn tôi.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">姐姐</b><small>Jiějie</small></span><span class=\"ct-w c-b\"><b class=\"zh\">跑</b><small>pǎo</small></span><span class=\"ct-w c-\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比我</b><small>bǐ wǒ</small></span><span class=\"ct-w c-a\"><b class=\"zh\">快。</b><small>kuài.</small></span></div><div class=\"ct-vi\">Chị gái chạy nhanh hơn tôi.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我妻子</b><small>Wǒ qīzi</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比我</b><small>bǐ wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">做</b><small>zuò</small></span><span class=\"ct-w c-\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-a\"><b class=\"zh\">好。</b><small>hǎo.</small></span></div><div class=\"ct-vi\">Vợ tôi nấu ăn ngon hơn tôi.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我妻子</b><small>Wǒ qīzi</small></span><span class=\"ct-w c-b\"><b class=\"zh\">做</b><small>zuò</small></span><span class=\"ct-w c-\"><b class=\"zh\">得</b><small>de</small></span><span class=\"ct-w c-k\"><b class=\"zh\">比我</b><small>bǐ wǒ</small></span><span class=\"ct-w c-a\"><b class=\"zh\">好。</b><small>hǎo.</small></span></div><div class=\"ct-vi\">Vợ tôi nấu ăn ngon hơn tôi.</div></td></tr></tbody></table></div></div></div><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"hot\">Hai vị trí của <span class=\"zh\">比 B</span> — nghĩa <b>không đổi</b></span></p>","note":"<b>Lưu ý:</b> <b>Không</b> thêm <span class=\"zh\">很 / 太 / 非常</span>: ✗ <span class=\"zh\">他比我学得很好</span>","examples":[{"zh":"我妻子比我做得好。","py":"Wǒ qīzi bǐ wǒ zuò de hǎo.","vi":"Vợ tôi nấu ăn ngon hơn tôi."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室","titleVi":"Trong lớp — hỏi nhau giờ ngủ dậy","lines":[{"speaker":"甲","name":"Bạn A","zh":"你每天早上几点起床？","py":"Nǐ měi tiān zǎoshang jǐ diǎn qǐchuáng?","vi":"Sáng nào bạn cũng dậy lúc mấy giờ?"},{"speaker":"乙","name":"Bạn B","zh":"6:00多。","py":"Liù diǎn duō.","vi":"Hơn 6 giờ."},{"speaker":"甲","name":"Bạn A","zh":"你比我早起个小时。","py":"Nǐ bǐ wǒ zǎo qǐ ge xiǎoshí.","vi":"Bạn dậy sớm hơn mình một tiếng đấy."},{"speaker":"乙","name":"Bạn B","zh":"我睡得也早，我每天晚上10:00就睡觉。早睡早起身体好。","py":"Wǒ shuì de yě zǎo, wǒ měi tiān wǎnshang shí diǎn jiù shuìjiào. Zǎo shuì zǎo qǐ shēntǐ hǎo.","vi":"Mình cũng ngủ sớm mà, tối nào cứ 10 giờ là đi ngủ. Ngủ sớm dậy sớm thì khoẻ người."}]},{"titleZh":"课文二 · 在朋友家","titleVi":"Ở nhà bạn — mời ăn thêm cơm","lines":[{"speaker":"甲","name":"Bạn A","zh":"再来点米饭吧，你吃得太少了。","py":"Zài lái diǎn mǐfàn ba, nǐ chī de tài shǎo le.","vi":"Ăn thêm chút cơm nữa đi, bạn ăn ít quá."},{"speaker":"乙","name":"Bạn B","zh":"不少了，今天吃的很好，太谢谢你了。","py":"Bù shǎo le, jīntiān chī de hěn hǎo, tài xièxie nǐ le.","vi":"Không ít đâu, hôm nay ăn ngon lắm, cảm ơn bạn nhiều."},{"speaker":"甲","name":"Bạn A","zh":"你做饭做得怎么样？","py":"Nǐ zuò fàn zuò de zěnmeyàng?","vi":"Bạn nấu ăn thế nào?"},{"speaker":"乙","name":"Bạn B","zh":"不怎么样，我妻子比我做得好。","py":"Bù zěnmeyàng, wǒ qīzi bǐ wǒ zuò de hǎo.","vi":"Cũng thường thôi, vợ mình nấu ngon hơn mình."}]},{"titleZh":"课文三 · 在家门口","titleVi":"Trước cửa nhà — trời lạnh có tuyết","lines":[{"speaker":"甲","name":"Bạn A","zh":"下雪了，今天真冷。","py":"Xià xuě le, jīntiān zhēn lěng.","vi":"Tuyết rơi rồi, hôm nay lạnh thật."},{"speaker":"乙","name":"Bạn B","zh":"有零下10度吧？","py":"Yǒu líng xià shí dù ba?","vi":"Chắc phải âm 10 độ ấy nhỉ?"},{"speaker":"甲","name":"Bạn A","zh":"是啊，你穿得太少了，我们进房间吧。","py":"Shì a, nǐ chuān de tài shǎo le, wǒmen jìn fángjiān ba.","vi":"Đúng đấy, bạn mặc ít quá, chúng mình vào phòng đi."},{"speaker":"乙","name":"Bạn B","zh":"好吧。","py":"Hǎo ba.","vi":"Ừ, được thôi."}]},{"titleZh":"课文四 · 在家里","titleVi":"Ở nhà — em trai nhờ tìm nhà","lines":[{"speaker":"甲","name":"Bạn A","zh":"你在忙什么呢？","py":"Nǐ zài máng shénme ne?","vi":"Bạn đang bận gì thế?"},{"speaker":"乙","name":"Bạn B","zh":"我弟弟让我帮他找个房子，现在他家离公司有点儿远。","py":"Wǒ dìdi ràng wǒ bāng tā zhǎo ge fángzi, xiànzài tā jiā lí gōngsī yǒudiǎnr yuǎn.","vi":"Em trai nhờ mình tìm giúp một căn nhà, giờ nhà nó cách công ty hơi xa."},{"speaker":"甲","name":"Bạn A","zh":"住得远真的很累！","py":"Zhù de yuǎn zhēn de hěn lèi!","vi":"Ở xa thì mệt thật đấy!"},{"speaker":"乙","name":"Bạn B","zh":"是啊，他也希望能住得近一点儿。","py":"Shì a, tā yě xīwàng néng zhù de jìn yìdiǎnr.","vi":"Đúng thế, nó cũng mong ở được gần hơn một chút."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu của câu hỏi yêu cầu đưa ra lựa chọn","introZh":"句中供选择的部分重读，前一部分读升调，语速较慢，后一部分读降调。","introVi":"Với loại câu hỏi này, ta đọc nhấn mạnh các lựa chọn, đọc tương đối chậm đồng thời lên giọng ở thành phần đứng trước và xuống giọng ở thành phần đứng sau.","zh":"选择问句的句调","py":"","tag":"Ngữ điệu","vi":"Nhấn các lựa chọn · trước ↗ sau ↘","listZh":"选择问句的句调","listVi":"Câu hỏi lựa chọn (还是) — nhấn các lựa chọn, vế trước lên giọng ↗, vế sau xuống giọng ↘","descZh":"句中供选择的部分重读，前一部分读升调，语速较慢，后一部分读降调。","descVi":"Với loại câu hỏi này, ta đọc nhấn mạnh các lựa chọn, đọc tương đối chậm đồng thời lên giọng ở thành phần đứng trước và xuống giọng ở thành phần đứng sau.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"前一部分","s":"lựa chọn 1 · nhấn","st":true},{"l":"升调 ↗","s":"lên giọng · đọc chậm"}],[{"l":"后一部分","s":"lựa chọn 2 · nhấn","st":true},{"l":"降调 ↘","s":"xuống giọng","dn":true}]],"tip":"Nhấn <b>cả hai lựa chọn</b> (chữ có chấm đỏ): lựa chọn trước <b>lên giọng ↗, đọc chậm</b>, qua <span class=\"zh\">还是</span> sang lựa chọn sau <b>xuống giọng ↘</b>.","readLbl":"Luyện đọc · chữ có chấm đỏ đọc nhấn · ↘ xuống giọng","sents":[{"tone":"down","w":[{"hz":"你","py":"Nǐ"},{"hz":"喜欢","py":"xǐhuan"},{"hz":"吃","py":"chī"},{"hz":"米饭","py":"mǐfàn","st":true,"j":true},{"hz":"还是","py":"háishi"},{"hz":"吃","py":"chī"},{"hz":"面条？","py":"miàntiáo?","st":true}],"vi":"Bạn thích ăn cơm hay ăn mì?"},{"tone":"down","w":[{"hz":"你","py":"Nǐ"},{"hz":"想","py":"xiǎng"},{"hz":"今天","py":"jīntiān","st":true},{"hz":"去","py":"qù","j":true},{"hz":"还是","py":"háishi"},{"hz":"明天","py":"míngtiān","st":true},{"hz":"去？","py":"qù?"}],"vi":"Bạn muốn hôm nay đi hay ngày mai đi?"},{"tone":"down","w":[{"hz":"你去","py":"Nǐ qù"},{"hz":"学校","py":"xuéxiào"},{"hz":"是","py":"shì"},{"hz":"开车","py":"kāi chē","st":true,"j":true},{"hz":"还是","py":"háishi"},{"hz":"坐车？","py":"zuò chē?","st":true}],"vi":"Bạn đến trường bằng cách tự lái xe hay đi xe (buýt, taxi)?"}]}]},{"id":"k2v2-b13","courseId":"k2v2","order":13,"title":"Cửa đang mở","titleZh":"门开着呢","titlePy":"mén kāi zhe ne","vocab":[{"stt":1,"hanzi":"着","pinyin":"zhe","hanviet":"Trước","pos":"Trợ từ","meaning":"trợ từ chỉ trạng thái","comps":"开着 (đang mở), 拿着 (đang cầm)","example":{"zh":"门开着呢。","py":"Mén kāi zhe ne.","vi":"Cửa đang mở kìa."}},{"stt":2,"hanzi":"手","pinyin":"shǒu","hanviet":"Thủ","pos":"Danh từ","meaning":"tay, bàn tay","comps":"手里 (trong tay), 手机 (điện thoại)","example":{"zh":"他手里有一本书。","py":"Tā shǒu lǐ yǒu yì běn shū.","vi":"Trong tay anh ấy có một quyển sách."}},{"stt":3,"hanzi":"拿","pinyin":"ná","hanviet":"Nã","pos":"Động từ","meaning":"cầm, lấy","comps":"拿着 (đang cầm), 拿来 (lấy lại đây)","example":{"zh":"他手里拿着铅笔。","py":"Tā shǒu lǐ ná zhe qiānbǐ.","vi":"Trong tay anh ấy cầm cây bút chì."}},{"stt":4,"hanzi":"铅笔","pinyin":"qiānbǐ","hanviet":"Diên bút","pos":"Danh từ","meaning":"bút chì","comps":"一支铅笔 (một cây bút chì), 用铅笔 (dùng bút chì)","example":{"zh":"这是我的铅笔。","py":"Zhè shì wǒ de qiānbǐ.","vi":"Đây là bút chì của mình."}},{"stt":5,"hanzi":"班","pinyin":"bān","hanviet":"Ban","pos":"Danh từ","meaning":"lớp (học); ca, kíp","comps":"我们班 (lớp chúng tôi), 班里 (trong lớp)","example":{"zh":"她是我们班的学生。","py":"Tā shì wǒmen bān de xuésheng.","vi":"Cô ấy là học sinh lớp mình."}},{"stt":6,"hanzi":"长","pinyin":"zhǎng","hanviet":"Trưởng","pos":"Động từ","meaning":"mọc, lớn lên; có dáng","comps":"长着 (có, mọc ra), 长大 (lớn lên)","example":{"zh":"她长着两个大眼睛。","py":"Tā zhǎng zhe liǎng ge dà yǎnjing.","vi":"Cô ấy có đôi mắt to."}},{"stt":7,"hanzi":"笑","pinyin":"xiào","hanviet":"Tiếu","pos":"Động từ","meaning":"cười","comps":"爱笑 (hay cười), 笑一笑 (cười một cái)","example":{"zh":"她非常爱笑。","py":"Tā fēicháng ài xiào.","vi":"Cô ấy rất hay cười."}},{"stt":8,"hanzi":"宾馆","pinyin":"bīnguǎn","hanviet":"Tân quán","pos":"Danh từ","meaning":"khách sạn, nhà khách","comps":"住宾馆 (ở khách sạn), 新京宾馆 (khách sạn Tân Kinh)","example":{"zh":"这儿离宾馆远吗？","py":"Zhèr lí bīnguǎn yuǎn ma?","vi":"Từ đây tới khách sạn có xa không?"}},{"stt":9,"hanzi":"一直","pinyin":"yìzhí","hanviet":"Nhất trực","pos":"Phó từ","meaning":"thẳng; luôn, liên tục","comps":"一直走 (đi thẳng), 一直在 (vẫn luôn ở)","example":{"zh":"从这儿一直往前走。","py":"Cóng zhèr yìzhí wǎng qián zǒu.","vi":"Từ đây đi thẳng về phía trước."}},{"stt":10,"hanzi":"往","pinyin":"wǎng","hanviet":"Vãng","pos":"Giới từ","meaning":"về phía, hướng về","comps":"往前走 (đi về phía trước), 往右 (về bên phải)","example":{"zh":"往右走就到了。","py":"Wǎng yòu zǒu jiù dào le.","vi":"Đi về bên phải là tới."}},{"stt":11,"hanzi":"路口","pinyin":"lùkǒu","hanviet":"Lộ khẩu","pos":"Danh từ","meaning":"ngã ba, ngã tư đường","comps":"前面的路口 (ngã tư phía trước), 到路口 (tới ngã tư)","example":{"zh":"前面有一个路口。","py":"Qiánmiàn yǒu yí ge lùkǒu.","vi":"Phía trước có một ngã tư."}},{"stt":12,"hanzi":"杨笑笑","pinyin":"Yáng Xiàoxiao","hanviet":"Dương Tiếu Tiếu","pos":"Danh từ riêng","meaning":"Dương Tiếu Tiếu (tên)","comps":"她姓杨 (cô ấy họ Dương), 叫笑笑 (tên là Tiếu Tiếu)","example":{"zh":"她姓杨，叫笑笑。","py":"Tā xìng Yáng, jiào Xiàoxiao.","vi":"Cô ấy họ Dương, tên là Tiếu Tiếu."}}],"hanzi":[{"char":"着","pinyin":"zhe","hanviet":"Trước","chars":["着"],"story":"着 là dạng viết khác của chữ 著: phần trên vốn là bộ Thảo 艹 (cỏ) nay viết thành nét giống 羊, phần dưới là 目 (con mắt). Nghĩa gốc là \"dính vào, bám lấy\", nên khi đứng sau động từ, 着 cho biết trạng thái vẫn còn \"bám\" lại — tức đang tiếp diễn."},{"char":"手","pinyin":"shǒu","hanviet":"Thủ","chars":["手"],"story":"手 là chữ tượng hình, vẽ một bàn tay giơ lên: nét phẩy trên cùng cùng hai nét ngang là các ngón tay xoè ra, nét sổ móc chạy dọc là cổ tay. Bộ Thủ 手 (viết tắt là 扌) có mặt trong hầu hết các chữ chỉ động tác của tay: 打, 拿, 找."},{"char":"拿","pinyin":"ná","hanviet":"Nã","chars":["拿"],"story":"拿 gồm 合 (hợp lại, khép lại) ở trên và 手 (bàn tay) ở dưới: bàn tay khép lại để giữ chặt một vật. Vì thế 拿 nghĩa là \"cầm, lấy\". Nhìn chữ là thấy ngay động tác — một chữ hội ý rất dễ nhớ."},{"char":"铅笔","pinyin":"qiānbǐ","hanviet":"Diên bút","chars":["铅","笔"],"story":"铅 gồm bộ Kim 钅 (kim loại) chỉ nghĩa và 㕣 chỉ âm, nghĩa là \"chì\". 笔 gồm 竹 (tre) ở trên và 毛 (lông) ở dưới — cây bút xưa là ống tre gắn túm lông. Ghép lại 铅笔 là \"cây bút ruột chì\", tức bút chì."},{"char":"班","pinyin":"bān","hanviet":"Ban","chars":["班"],"story":"班 gồm hai chữ 王 (vốn là 玉 — viên ngọc) kẹp bộ Đao 刂 (con dao) ở giữa: dùng dao chia đôi viên ngọc. Từ nghĩa gốc \"chia ra\" mà thành nghĩa hôm nay — một nhóm người được chia ra: lớp học, ca làm, chuyến xe."},{"char":"长","pinyin":"zhǎng","hanviet":"Trưởng","chars":["长"],"story":"长 vẽ hình một người già để tóc dài buông xuống, tay chống gậy. Chữ này có hai âm: đọc cháng nghĩa là \"dài\" (长头发), đọc zhǎng nghĩa là \"lớn lên, mọc ra\" (长大, 长着) — người tóc dài là người đã sống lâu, đã trưởng thành."},{"char":"笑","pinyin":"xiào","hanviet":"Tiếu","chars":["笑"],"story":"笑 gồm bộ Trúc 竹 ở trên và 夭 (dáng người nghiêng ngả) ở dưới. Người xưa hình dung cành trúc rung rinh trước gió trông giống dáng người ngả nghiêng khi cười, nên 笑 nghĩa là \"cười\"."},{"char":"宾馆","pinyin":"bīnguǎn","hanviet":"Tân quán","chars":["宾","馆"],"story":"宾 gồm 宀 (mái nhà) và 贝 (vỏ sò — tiền của): người mang lễ vật tới nhà, tức là \"khách\". 馆 gồm 饣 (ăn uống) chỉ nghĩa và 官 chỉ âm — nơi dọn cơm cho khách. Ghép lại 宾馆 là \"nhà tiếp khách\", tức khách sạn."},{"char":"一直","pinyin":"yìzhí","hanviet":"Nhất trực","chars":["一","直"],"story":"一 chỉ là một nét ngang thẳng băng. 直 gồm 十, 目 (mắt) và một nét gấp, nghĩa gốc là \"mắt nhìn thẳng, không lệch\". Ghép lại 一直 vừa có nghĩa \"đi một mạch thẳng về phía trước\", vừa có nghĩa \"suốt từ đầu đến cuối không thay đổi\"."},{"char":"往","pinyin":"wǎng","hanviet":"Vãng","chars":["往"],"story":"往 gồm bộ Xích 彳 (dấu chân bước, chỉ việc đi lại) và 主 chỉ âm. Nghĩa gốc là \"đi tới\", nay chủ yếu dùng làm giới từ đặt trước từ chỉ phương hướng: 往前 (về phía trước), 往右 (về bên phải)."},{"char":"路口","pinyin":"lùkǒu","hanviet":"Lộ khẩu","chars":["路","口"],"story":"路 gồm bộ Túc 足 (bàn chân) chỉ nghĩa và 各 chỉ âm — chỗ chân người đi qua, tức con đường. 口 vẽ cái miệng mở ra, nghĩa rộng là \"cửa, chỗ mở\". Ghép lại 路口 là \"miệng đường\" — nơi hai con đường gặp nhau: ngã ba, ngã tư."},{"char":"杨笑笑","pinyin":"Yáng Xiàoxiao","hanviet":"Dương Tiếu Tiếu","chars":["杨","笑","笑"],"story":"杨 gồm bộ Mộc 木 (cây) và 昜 chỉ âm, vốn chỉ cây dương liễu, nay là một họ rất phổ biến của người Trung Quốc — họ Dương. 笑 là \"cười\", đặt lặp lại thành 笑笑 nghe thân mật, gửi gắm mong ước cô bé lúc nào cũng tươi cười."}],"grammar":[{"title":"Trợ từ động thái 着","formula":"<div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span></div><div class=\"fx-ex zh\">门开着。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span></div><div class=\"fx-ex zh\">门没开着。</div><div class=\"fx-lbl\">Nghi vấn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>着</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？/ 没有？</b></span></div><div class=\"fx-ex zh\">门开着吗？</div>","summary":"<p class=\"gr-lead\">Chỉ trạng thái kéo dài</p><ul><li><b>Ý nghĩa:</b> trạng thái <b>đang duy trì</b> (<span class=\"zh\">开着 · 穿着 · 拿着</span>) · <b>Vị trí:</b> ngay <b>sau động từ</b>, cuối câu hay thêm <span class=\"zh\">呢</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">\"在\" 和 \"着\"</span> · Phân biệt</h4><p>Hành động đang diễn ra ↔ trạng thái đang duy trì</p><div class=\"ct-box\"><div class=\"ct-cap\">Phân biệt · 在 ↔ 着</div><div class=\"ct-intro\"><span class=\"ct-lg k\">在</span><b>trước</b> động từ → hành động <b>đang diễn ra</b>　·　<span class=\"ct-lg k\">着</span><b>sau</b> động từ → trạng thái <b>còn giữ nguyên</b></div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>在 + 动词<small>hành động đang diễn ra</small></th><th>动词 + 着<small>trạng thái đang duy trì</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-k\"><b class=\"zh\">在</b><small>zài</small></span><span class=\"ct-w c-b\"><b class=\"zh\">穿</b><small>chuān</small></span><span class=\"ct-w c-\"><b class=\"zh\">衣服。</b><small>yīfu.</small></span></div><div class=\"ct-vi\">Anh ấy đang mặc quần áo. (động tác mặc)</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-b\"><b class=\"zh\">穿</b><small>chuān</small></span><span class=\"ct-w c-k\"><b class=\"zh\">着</b><small>zhe</small></span><span class=\"ct-w c-\"><b class=\"zh\">红色的衣服。</b><small>hóngsè de yīfu.</small></span></div><div class=\"ct-vi\">Anh ấy mặc áo màu đỏ. (trạng thái)</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">她</b><small>Tā</small></span><span class=\"ct-w c-k\"><b class=\"zh\">在</b><small>zài</small></span><span class=\"ct-w c-b\"><b class=\"zh\">开</b><small>kāi</small></span><span class=\"ct-w c-\"><b class=\"zh\">门。</b><small>mén.</small></span></div><div class=\"ct-vi\">Cô ấy đang mở cửa. (động tác mở)</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">门</b><small>Mén</small></span><span class=\"ct-w c-b\"><b class=\"zh\">开</b><small>kāi</small></span><span class=\"ct-w c-k\"><b class=\"zh\">着</b><small>zhe</small></span><span class=\"ct-w c-\"><b class=\"zh\">呢。</b><small>ne.</small></span></div><div class=\"ct-vi\">Cửa đang mở kìa. (trạng thái)</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">她</b><small>Tā</small></span><span class=\"ct-w c-k\"><b class=\"zh\">在</b><small>zài</small></span><span class=\"ct-w c-b\"><b class=\"zh\">打</b><small>dǎ</small></span><span class=\"ct-w c-\"><b class=\"zh\">电话。</b><small>diànhuà.</small></span></div><div class=\"ct-vi\">Cô ấy đang gọi điện thoại.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">她手里</b><small>Tā shǒu lǐ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">拿</b><small>ná</small></span><span class=\"ct-w c-k\"><b class=\"zh\">着</b><small>zhe</small></span><span class=\"ct-w c-\"><b class=\"zh\">手机。</b><small>shǒujī.</small></span></div><div class=\"ct-vi\">Trong tay cô ấy đang cầm điện thoại.</div></td></tr></tbody></table></div></div></div>","note":"<b>Lưu ý:</b> <b>Phủ định</b> dùng <span class=\"zh\">没</span>, không dùng <span class=\"zh\">不</span>: ✗ <span class=\"zh\">门不开着</span>","examples":[{"zh":"KĐ：门开着。　PĐ：门没开着。　NV：门开着吗？","py":"Mén kāizhe.  Mén méi kāizhe.  Mén kāizhe ma?","vi":"Cửa đang mở. — Cửa không mở. — Cửa có đang mở không?"},{"zh":"KĐ：他们穿着红色的衣服。　PĐ：他们没穿着红色的衣服。　NV：他们穿着红色的衣服吗？","py":"Tāmen chuānzhe hóngsè de yīfu.  Tāmen méi chuānzhe hóngsè de yīfu.  Tāmen chuānzhe hóngsè de yīfu ma?","vi":"Họ đang mặc quần áo màu đỏ. — Họ không mặc quần áo màu đỏ. — Họ có đang mặc quần áo màu đỏ không?"},{"zh":"KĐ：（她）拿着铅笔。　PĐ：（她）没拿着铅笔。　NV：（她）拿着铅笔吗？","py":"(Tā) názhe qiānbǐ.  (Tā) méi názhe qiānbǐ.  (Tā) názhe qiānbǐ ma?","vi":"(Cô ấy) đang cầm bút chì. — (Cô ấy) không cầm bút chì. — (Cô ấy) có đang cầm bút chì không?"}],"exercises":[]},{"title":"Câu phản vấn \"不是……吗？\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b><small>chủ ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>不是</b><small>chẳng phải</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>谓语</b><small>vị ngữ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？</b><small>…sao?</small></span></div>","summary":"<p class=\"gr-lead\">Hỏi ngược để khẳng định</p><ul><li>Đây là <b>câu hỏi phản vấn</b>: hình thức là câu hỏi nhưng thực chất để <b>khẳng định</b> điều người nói vốn đã tin, không phải để lấy thông tin mới.</li><li>Sắc thái thường là <b>ngạc nhiên</b> hoặc <b>nhắc lại</b> điều đã biết: <span class=\"zh\">你不是有女朋友吗？</span> (Chẳng phải cậu có bạn gái rồi mà?).</li><li><span class=\"zh\">不</span> đứng trước <span class=\"zh\">是</span> (thanh 4) nên <b>biến điệu sang thanh 2</b>: đọc <span class=\"zh\">bú shì</span>, không đọc bù shì.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">她不是有男朋友吗？</span> = Chẳng phải cô ấy có bạn trai rồi sao? — người nói <b>tin là CÓ</b>.</p>","note":"<b>Lưu ý:</b> Nghĩa <b>ngược với hình thức</b>: có chữ <span class=\"zh\">不</span> nhưng câu mang ý <b>khẳng định</b> — đừng dịch thành câu phủ định.","examples":[{"zh":"不是说今天有雨吗？怎么还没下？","py":"Bú shì shuō jīntiān yǒu yǔ ma? Zěnme hái méi xià?","vi":"Chẳng phải nói hôm nay có mưa sao? Sao vẫn chưa mưa?"},{"zh":"你不是北京人吗？怎么不会说北京话？","py":"Nǐ bú shì Běijīng rén ma? Zěnme bú huì shuō Běijīnghuà?","vi":"Chẳng phải bạn là người Bắc Kinh sao? Sao lại không biết nói tiếng Bắc Kinh?"},{"zh":"（她是你的女朋友？）她不是有男朋友了吗？","py":"(Tā shì nǐ de nǚ péngyou?) Tā bú shì yǒu nán péngyou le ma?","vi":"(Cô ấy là bạn gái của cậu à?) Chẳng phải cô ấy có bạn trai rồi sao?"}],"exercises":[]},{"title":"Giới từ 往 (về phía…)","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>往</b><small>về phía</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>方位词</b><small>từ chỉ hướng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b><small>động từ</small></span></div>","summary":"<p class=\"gr-lead\">Chỉ hướng đi về phía nào</p><ul><li>Nối tiếp dãy giới từ đã học: bài 7 <span class=\"zh\">离</span> (khoảng cách), bài 9 <span class=\"zh\">从</span> (điểm xuất phát), bài 10 <span class=\"zh\">对</span> (đối tượng) — nay <span class=\"zh\">往</span> nêu <b>hướng</b> của động tác.</li><li>Cụm <span class=\"zh\">往 + 方位词</span> luôn đứng <b>trước động từ</b>: <span class=\"zh\">往前走</span>, <span class=\"zh\">往右走</span>.</li><li>Chỉ đường hay dùng khuôn đầy đủ <span class=\"zh\">从……一直往……走</span>: <span class=\"zh\">从这儿一直往前走</span> (từ đây cứ đi thẳng về phía trước).</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">往前走　·　往右走　·　往左走</span> = đi về phía trước · rẽ phải · rẽ trái</p>","note":"<b>Lưu ý:</b> Tiếng Việt nói \"đi <b>về phía trước</b>\" — động từ đứng trước; tiếng Trung <b>ngược lại</b>, hướng đứng trước động từ: <span class=\"zh\">走往前</span> ✗.","examples":[{"zh":"从这儿往前走，就是我们学校。","py":"Cóng zhèr wǎng qián zǒu, jiù shì wǒmen xuéxiào.","vi":"Từ đây đi về phía trước là trường của chúng tôi."},{"zh":"你看，往左走是医院，往右走是银行。","py":"Nǐ kàn, wǎng zuǒ zǒu shì yīyuàn, wǎng yòu zǒu shì yínháng.","vi":"Bạn xem, đi về bên trái là bệnh viện, đi về bên phải là ngân hàng."},{"zh":"从这儿一直往前走，到了前面的路口再往右走。","py":"Cóng zhèr yìzhí wǎng qián zǒu, dàole qiánmiàn de lùkǒu zài wǎng yòu zǒu.","vi":"Từ đây cứ đi thẳng, đến ngã tư phía trước thì rẽ phải."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在办公室","titleVi":"Ở văn phòng — khách tới tìm người","lines":[{"speaker":"甲","name":"Bạn A","zh":"门开着呢，请进。","py":"Mén kāi zhe ne, qǐng jìn.","vi":"Cửa đang mở kìa, mời vào."},{"speaker":"乙","name":"Bạn B","zh":"请问，张先生在吗？","py":"Qǐngwèn, Zhāng xiānsheng zài ma?","vi":"Cho hỏi, ông Trương có ở đây không ạ?"},{"speaker":"甲","name":"Bạn A","zh":"他出去了。你下午再来吧？","py":"Tā chūqù le. Nǐ xiàwǔ zài lái ba?","vi":"Anh ấy ra ngoài rồi. Chiều bạn quay lại nhé?"},{"speaker":"乙","name":"Bạn B","zh":"好的，谢谢！","py":"Hǎo de, xièxie!","vi":"Vâng ạ, cảm ơn!"}]},{"titleZh":"课文二 · 办公室","titleVi":"Ở văn phòng — hỏi tên hai cô gái","lines":[{"speaker":"甲","name":"Bạn A","zh":"那个正在说话的女孩是谁？","py":"Nà ge zhèngzài shuōhuà de nǚhái shì shéi?","vi":"Cô gái đang nói chuyện kia là ai vậy?"},{"speaker":"乙","name":"Bạn B","zh":"我知道他的名字，她姓杨，叫笑笑，她姐姐是我同学。","py":"Wǒ zhīdào tā de míngzi, tā xìng Yáng, jiào Xiàoxiao, tā jiějie shì wǒ tóngxué.","vi":"Mình biết tên cô ấy, cô ấy họ Dương, tên là Tiếu Tiếu, chị cô ấy là bạn học của mình."},{"speaker":"甲","name":"Bạn A","zh":"那个手里拿着铅笔的呢？","py":"Nà ge shǒu lǐ ná zhe qiānbǐ de ne?","vi":"Thế còn người đang cầm bút chì trong tay thì sao?"},{"speaker":"乙","name":"Bạn B","zh":"我不认识。","py":"Wǒ bú rènshi.","vi":"Người này thì mình không quen."}]},{"titleZh":"课文三 · 在运动场","titleVi":"Ở sân vận động — chuyện bạn gái","lines":[{"speaker":"甲","name":"Bạn A","zh":"听说你有女朋友了？我认识他吗？","py":"Tīngshuō nǐ yǒu nǚ péngyou le? Wǒ rènshi tā ma?","vi":"Nghe nói cậu có bạn gái rồi à? Mình có quen cô ấy không?"},{"speaker":"乙","name":"Bạn B","zh":"就是我们班那个长着两个大眼睛，非常爱笑的女孩。","py":"Jiù shì wǒmen bān nà ge zhǎng zhe liǎng ge dà yǎnjing, fēicháng ài xiào de nǚhái.","vi":"Chính là cô gái có đôi mắt to, rất hay cười ở lớp mình đấy."},{"speaker":"甲","name":"Bạn A","zh":"她不是有男朋友吗？","py":"Tā bú shì yǒu nán péngyou ma?","vi":"Chẳng phải cô ấy có bạn trai rồi sao?"},{"speaker":"乙","name":"Bạn B","zh":"那个已经是她的前男友了。","py":"Nà ge yǐjīng shì tā de qián nányǒu le.","vi":"Người đó thành bạn trai cũ của cô ấy rồi."}]},{"titleZh":"课文四 · 在路上","titleVi":"Trên đường — hỏi lối tới khách sạn","lines":[{"speaker":"甲","name":"Bạn A","zh":"请问这儿离新京宾馆远吗？","py":"Qǐngwèn zhèr lí Xīnjīng Bīnguǎn yuǎn ma?","vi":"Cho hỏi từ đây tới khách sạn Tân Kinh có xa không ạ?"},{"speaker":"乙","name":"Bạn B","zh":"不远，走路20分钟就到。","py":"Bù yuǎn, zǒu lù èrshí fēnzhōng jiù dào.","vi":"Không xa đâu, đi bộ 20 phút là tới."},{"speaker":"甲","name":"Bạn A","zh":"你能告诉我怎么走吗？","py":"Nǐ néng gàosu wǒ zěnme zǒu ma?","vi":"Bạn chỉ giúp mình đường đi được không?"},{"speaker":"乙","name":"Bạn B","zh":"从这儿一直往前走，到了前面的路口再往右走。","py":"Cóng zhèr yìzhí wǎng qián zǒu, dào le qiánmiàn de lùkǒu zài wǎng yòu zǒu.","vi":"Từ đây cứ đi thẳng về phía trước, tới ngã tư phía trước thì rẽ phải."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu của câu cầu khiến","introZh":"语气委婉时，全句音高较低，第一个分句末尾语调略升，全句末尾语调缓降。","introVi":"Khi được nói bằng giọng nhẹ nhàng, câu cầu khiến có cao độ tương đối thấp. Để nói đúng ngữ điệu, ta lên giọng một chút ở cuối mệnh đề thứ nhất và xuống giọng ở cuối câu.","zh":"祈使句的句调","py":"qíshǐjù de jùdiào","tag":"Ngữ điệu","vi":"Giọng nhẹ nhàng · cuối câu xuống ↘","listZh":"祈使句的句调","listVi":"Câu cầu khiến (吧) — giọng thấp, nhẹ nhàng; cuối vế đầu hơi lên ↗, cuối câu xuống từ từ ↘","descZh":"语气委婉时，全句音高较低，第一个分句末尾语调略升，全句末尾语调缓降。","descVi":"Khi được nói bằng giọng nhẹ nhàng, câu cầu khiến có cao độ tương đối thấp. Để nói đúng ngữ điệu, ta lên giọng một chút ở cuối mệnh đề thứ nhất và xuống giọng ở cuối câu.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"第一个分句","s":"cuối vế thứ nhất"},{"l":"略升 ↗","s":"hơi lên giọng"}],[{"l":"全句末尾","s":"cuối câu (吧)"},{"l":"缓降 ↘","s":"xuống giọng từ từ","dn":true}]],"tip":"Cả câu nói <b>giọng thấp, nhẹ nhàng</b> (lời mời, lời đề nghị): cuối vế đầu (<span class=\"zh\">让 · 快点儿 · 请</span>) <b>hơi lên giọng</b>, đến <span class=\"zh\">吧</span> cuối câu <b>xuống giọng từ từ ↘</b>.","readLbl":"Luyện đọc · giọng nhẹ nhàng · ↘ xuống giọng từ từ cuối câu","sents":[{"tone":"down","w":[{"hz":"让","py":"Ràng"},{"hz":"我们","py":"wǒmen"},{"hz":"休息","py":"xiūxi","j":true},{"hz":"休息","py":"xiūxi","j":true},{"hz":"吧。","py":"ba.","j":true}],"vi":"Để chúng ta nghỉ ngơi một chút đi."},{"tone":"down","w":[{"hz":"快点儿","py":"Kuàidiǎnr"},{"hz":"下课","py":"xià kè"},{"hz":"吧。","py":"ba.","j":true}],"vi":"Mau tan học đi."},{"tone":"down","w":[{"hz":"请","py":"Qǐng"},{"hz":"坐","py":"zuò"},{"hz":"吧。","py":"ba.","j":true}],"vi":"Mời ngồi."}]}],"activity":{"act":[{"tag":"Hoạt động","mean":"Hỏi đường · Chỉ đường","q":{"zh":"两人一组：一个人问路，一个人指路。","py":"Liǎng rén yì zǔ: yí ge rén wèn lù, yí ge rén zhǐ lù.","vi":"Hai người một nhóm: một người hỏi đường, một người chỉ đường."},"items":[{"zh":"从……出来，往左走 / 往右走","py":"cóng … chūlai, wǎng zuǒ zǒu / wǎng yòu zǒu","vi":"Từ … đi ra, đi về bên trái / bên phải"},{"zh":"一直往前走","py":"yìzhí wǎng qián zǒu","vi":"Cứ đi thẳng về phía trước"},{"zh":"到了第……个路口，再往左拐 / 往右拐","py":"dàole dì … ge lùkǒu, zài wǎng zuǒ guǎi / wǎng yòu guǎi","vi":"Đến ngã tư thứ … thì rẽ trái / rẽ phải"},{"zh":"走……米就到……了","py":"zǒu … mǐ jiù dào … le","vi":"Đi … mét là đến …"},{"zh":"……在你的左边 / 右边","py":"… zài nǐ de zuǒbian / yòubian","vi":"… ở bên trái / bên phải bạn"}],"pattern":{"ask":{"zh":"请问，从……到……怎么走？","py":"Qǐngwèn, cóng …… dào …… zěnme zǒu?","vi":"Cho hỏi, từ … đến … đi thế nào?"}},"banks":[{"lbl":"Địa điểm","zh":"地点","items":[{"zh":"学校","py":"xuéxiào","vi":"trường học"},{"zh":"银行","py":"yínháng","vi":"ngân hàng"},{"zh":"火车站","py":"huǒchēzhàn","vi":"ga tàu hoả"},{"zh":"商店","py":"shāngdiàn","vi":"cửa hàng"},{"zh":"医院","py":"yīyuàn","vi":"bệnh viện"},{"zh":"饭馆","py":"fànguǎn","vi":"quán ăn"},{"zh":"宾馆","py":"bīnguǎn","vi":"khách sạn"},{"zh":"公司","py":"gōngsī","vi":"công ty"},{"zh":"咖啡馆","py":"kāfēiguǎn","vi":"quán cà phê"},{"zh":"我家","py":"wǒ jiā","vi":"nhà tôi"},{"zh":"超市","py":"chāoshì","vi":"siêu thị"},{"zh":"公园","py":"gōngyuán","vi":"công viên"}]}],"tasks":["从我家到学校","从宾馆到火车站","从学校到医院","从咖啡馆到银行","从超市到饭馆","从公司到机场"]}],"speak":[]}},{"id":"k2v2-b14","courseId":"k2v2","order":14,"title":"Cậu đã từng xem phim đó chưa?","titleZh":"你看过那个电影吗？","titlePy":"nǐ kàn guo nà ge diànyǐng ma","vocab":[{"stt":1,"hanzi":"意思","pinyin":"yìsi","hanviet":"Ý tứ","pos":"Danh từ","meaning":"ý, ý nghĩa; sự thú vị","comps":"有意思 (thú vị), 什么意思 (nghĩa là gì)","example":{"zh":"这个电影很有意思。","py":"Zhège diànyǐng hěn yǒu yìsi.","vi":"Bộ phim này rất thú vị."}},{"stt":2,"hanzi":"但是","pinyin":"dànshì","hanviet":"Đãn thị","pos":"Liên từ","meaning":"nhưng, nhưng mà","comps":"但是很冷 (nhưng rất lạnh), 但是我想去 (nhưng mình muốn đi)","example":{"zh":"我喜欢，但是有点儿贵。","py":"Wǒ xǐhuan, dànshì yǒudiǎnr guì.","vi":"Mình thích, nhưng hơi đắt."}},{"stt":3,"hanzi":"虽然","pinyin":"suīrán","hanviet":"Tuy nhiên","pos":"Liên từ","meaning":"tuy, mặc dù","comps":"虽然……但是…… (tuy…nhưng…), 虽然很贵 (tuy rất đắt)","example":{"zh":"虽然是晴天，但是很冷。","py":"Suīrán shì qíngtiān, dànshì hěn lěng.","vi":"Tuy là trời nắng nhưng rất lạnh."}},{"stt":4,"hanzi":"次","pinyin":"cì","hanviet":"Thứ","pos":"Lượng từ","meaning":"lần, lượt","comps":"一次 (một lần), 好几次 (mấy lần liền)","example":{"zh":"我去过好几次。","py":"Wǒ qù guo hǎo jǐ cì.","vi":"Mình đã đi mấy lần rồi."}},{"stt":5,"hanzi":"玩儿","pinyin":"wánr","hanviet":"Ngoạn","pos":"Động từ","meaning":"chơi, đi chơi","comps":"去玩儿 (đi chơi), 玩儿玩儿 (chơi một chút)","example":{"zh":"我想再去玩儿。","py":"Wǒ xiǎng zài qù wánr.","vi":"Mình muốn đi chơi lần nữa."}},{"stt":6,"hanzi":"晴","pinyin":"qíng","hanviet":"Tình","pos":"Tính từ","meaning":"trời nắng, quang đãng","comps":"晴天 (trời nắng), 天晴了 (trời hửng nắng)","example":{"zh":"今天是晴天。","py":"Jīntiān shì qíngtiān.","vi":"Hôm nay là ngày nắng."}},{"stt":7,"hanzi":"百","pinyin":"bǎi","hanviet":"Bách","pos":"Số từ","meaning":"trăm (100)","comps":"一百 (một trăm), 两百块 (hai trăm tệ)","example":{"zh":"这件衣服两百块。","py":"Zhè jiàn yīfu liǎng bǎi kuài.","vi":"Chiếc áo này hai trăm tệ."}}],"hanzi":[{"char":"意思","pinyin":"yìsi","hanviet":"Ý tứ","chars":["意","思"],"story":"意 gồm 音 (âm thanh) ở trên và 心 (trái tim) ở dưới — tiếng nói phát ra từ trong lòng, tức \"ý nghĩ\". 思 gồm 田 (vốn là 囟, chỉ cái đầu) và 心 (tim): người xưa cho rằng suy nghĩ là việc của cả đầu lẫn tim. Ghép lại 意思 là \"điều trong lòng nghĩ ra\" — ý nghĩa."},{"char":"但是","pinyin":"dànshì","hanviet":"Đãn thị","chars":["但","是"],"story":"但 gồm bộ Nhân đứng 亻 (người) và 旦 (mặt trời nhô lên khỏi đường chân trời) chỉ âm. 是 nghĩa gốc là \"đúng, phải\". Ghép lại 但是 dùng để xoay chiều câu chuyện: \"chỉ có điều là…\", tức \"nhưng\"."},{"char":"虽然","pinyin":"suīrán","hanviet":"Tuy nhiên","chars":["虽","然"],"story":"虽 (dạng phồn thể 雖) gồm 虫 (côn trùng) và 隹 (chim đuôi ngắn) chỉ âm. 然 gồm 月 (thịt), 犬 (con chó) và 灬 (lửa) — nghĩa gốc là \"đốt\", nay dùng như \"như thế\". Ghép lại 虽然 nghĩa là \"tuy rằng như thế\", mở đầu vế nhượng bộ."},{"char":"次","pinyin":"cì","hanviet":"Thứ","chars":["次"],"story":"次 gồm 冫 (vốn là 二 — số hai) và 欠 (người há miệng thở ra). Nghĩa gốc là \"thứ hai, kế tiếp\", từ đó thành lượng từ đếm số lần một động tác lặp lại: 一次, 两次, 好几次."},{"char":"玩儿","pinyin":"wánr","hanviet":"Ngoạn","chars":["玩","儿"],"story":"玩 gồm bộ Ngọc 王 (viết tắt của 玉 — viên ngọc) chỉ nghĩa và 元 chỉ âm: cầm viên ngọc trong tay mà ngắm nghía, đùa nghịch. 儿 thêm sau là âm uốn lưỡi của tiếng Bắc Kinh, đọc dính lại thành wánr."},{"char":"晴","pinyin":"qíng","hanviet":"Tình","chars":["晴"],"story":"晴 gồm bộ Nhật 日 (mặt trời) chỉ nghĩa và 青 qīng (màu xanh) chỉ âm — mặt trời hiện ra, bầu trời xanh trong. Cùng gốc âm 青 còn có 请 (mời), 清 (trong), 情 (tình cảm) — nhớ một chữ là suy ra được cả nhóm."},{"char":"百","pinyin":"bǎi","hanviet":"Bách","chars":["百"],"story":"百 gồm 一 (một) ở trên và 白 bái (trắng) chỉ âm ở dưới: \"một\" lần trăm. Người xưa còn dùng 百 để chỉ số nhiều nói chung — 百姓 nghĩa đen là \"trăm họ\", tức toàn thể dân chúng."}],"grammar":[{"title":"Trợ từ động thái 过","formula":"<div class=\"fx-lbl\">Khẳng định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span></div><div class=\"fx-ex zh\">我去过中国。</div><div class=\"fx-lbl\">Phủ định</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>没(有)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span></div><div class=\"fx-ex zh\">我没去过中国。</div><div class=\"fx-lbl\">Nghi vấn</div><div class=\"fx-row\"><span class=\"fx-p\"><b>主语</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>过</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(宾语)</b></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>吗？/ 没有？</b></span></div><div class=\"fx-ex zh\">你去过中国吗？</div>","summary":"<p class=\"gr-lead\">Từng làm việc gì đó</p><ul><li><b>Cách dùng:</b> chỉ một <b>trải nghiệm từng có</b>, hoặc hành động đã xảy ra trong quá khứ nhưng <b>không kéo dài đến hiện tại</b></li><li><b>Vị trí:</b> ngay <b>sau động từ</b>, đọc thanh nhẹ <i>guo</i>　·　<b>Phủ định:</b> <span class=\"zh\">没(有)</span> và <b>vẫn giữ</b> <span class=\"zh\">过</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">动态助词 着 · 了 · 过</span> · Tổng hợp</h4><p>Ba trợ từ động thái đã học</p></div><div class=\"gr-sub\"><h4><span class=\"zh\">\"了\" 和 \"过\"</span> · Phân biệt</h4><p>Hoàn thành ↔ từng trải qua</p><div class=\"ct-box\"><div class=\"ct-cap\">Phân biệt · 了 ↔ 过</div><div class=\"ct-intro\"><span class=\"ct-lg k\">了</span>động tác <b>đã hoàn thành</b> (kết quả có thể còn)　·　<span class=\"ct-lg k\">过</span><b>đã từng</b> làm — nay không còn, nhấn <b>kinh nghiệm</b></div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>动词 + 了<small>đã hoàn thành</small></th><th>动词 + 过<small>đã từng · kinh nghiệm</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-b\"><b class=\"zh\">去</b><small>qù</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了</b><small>le</small></span><span class=\"ct-w c-\"><b class=\"zh\">北京。</b><small>Běijīng.</small></span></div><div class=\"ct-vi\">Anh ấy đi Bắc Kinh rồi (đang ở đó).</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他</b><small>Tā</small></span><span class=\"ct-w c-b\"><b class=\"zh\">去</b><small>qù</small></span><span class=\"ct-w c-k\"><b class=\"zh\">过</b><small>guo</small></span><span class=\"ct-w c-\"><b class=\"zh\">北京。</b><small>Běijīng.</small></span></div><div class=\"ct-vi\">Anh ấy từng đến Bắc Kinh (nay không ở đó).</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">吃</b><small>chī</small></span><span class=\"ct-w c-k\"><b class=\"zh\">了</b><small>le</small></span><span class=\"ct-w c-\"><b class=\"zh\">早饭。</b><small>zǎofàn.</small></span></div><div class=\"ct-vi\">Tôi ăn sáng rồi.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">吃</b><small>chī</small></span><span class=\"ct-w c-k\"><b class=\"zh\">过</b><small>guo</small></span><span class=\"ct-w c-\"><b class=\"zh\">中国菜。</b><small>Zhōngguó cài.</small></span></div><div class=\"ct-vi\">Tôi từng ăn món Trung Quốc.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">没</b><small>méi</small></span><span class=\"ct-w c-b\"><b class=\"zh\">看</b><small>kàn</small></span><span class=\"ct-w c-\"><b class=\"zh\">那个电影。</b><small>nà ge diànyǐng.</small></span></div><div class=\"ct-vi\">Tôi (đã) không xem phim đó.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">没</b><small>méi</small></span><span class=\"ct-w c-b\"><b class=\"zh\">看</b><small>kàn</small></span><span class=\"ct-w c-k\"><b class=\"zh\">过</b><small>guo</small></span><span class=\"ct-w c-\"><b class=\"zh\">那个电影。</b><small>nà ge diànyǐng.</small></span></div><div class=\"ct-vi\">Tôi chưa từng xem phim đó.</div></td></tr></tbody></table></div></div></div>","note":"<b>Lưu ý:</b> ✗ <span class=\"zh\">我不去过中国。</span> → ✓ <span class=\"zh\">我没去过中国。</span>","examples":[{"zh":"KĐ：他们来过我家。　PĐ：他们没来过我家。　NV：他们来过你家吗？","py":"Tāmen lái guo wǒ jiā.  Tāmen méi lái guo wǒ jiā.  Tāmen lái guo nǐ jiā ma?","vi":"Họ đã từng đến nhà tôi. — Họ chưa từng đến nhà tôi. — Họ đã từng đến nhà bạn chưa?"},{"zh":"KĐ：我看过那个电影。　PĐ：我没看过那个电影。　NV：你看过那个电影吗？","py":"Wǒ kàn guo nà ge diànyǐng.  Wǒ méi kàn guo nà ge diànyǐng.  Nǐ kàn guo nà ge diànyǐng ma?","vi":"Tôi đã từng xem bộ phim đó. — Tôi chưa từng xem bộ phim đó. — Bạn đã từng xem bộ phim đó chưa?"},{"zh":"KĐ：我去过中国。　PĐ：我没去过中国。　NV：你去过中国吗？","py":"Wǒ qù guo Zhōngguó.  Wǒ méi qù guo Zhōngguó.  Nǐ qù guo Zhōngguó ma?","vi":"Tôi đã từng đi Trung Quốc. — Tôi chưa từng đi Trung Quốc. — Bạn đã từng đi Trung Quốc chưa?"}],"exercises":[]},{"title":"Cặp liên từ 虽然……，但是……","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>虽然</b><small>tuy, mặc dù</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>分句1</b><small>vế 1</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>但是</b><small>nhưng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>分句2</b><small>vế 2</small></span></div>","summary":"<p class=\"gr-lead\">Tuy … nhưng …</p><ul><li>Nối tiếp bài 6 <span class=\"zh\">因为……，所以……</span> (nguyên nhân – kết quả); cặp này nối <b>hai ý ngược nhau</b>, và <b>vế sau</b> mới là điều người nói muốn nhấn.</li><li>Tiếng Trung <b>dùng đủ cả cặp</b>, khác tiếng Việt chỉ cần một chữ \"nhưng\". Có thể lược <span class=\"zh\">虽然</span>, nhưng rất hiếm khi lược <span class=\"zh\">但是</span>.</li><li><span class=\"zh\">虽然</span> đứng đầu vế 1, có thể <b>trước hoặc sau chủ ngữ</b>: <span class=\"zh\">我虽然去过好几次</span> = <span class=\"zh\">虽然我去过好几次</span>.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">虽然是晴天，但是很冷。</span> = Tuy là trời nắng <b>nhưng</b> rất lạnh.</p>","note":"<b>Lưu ý:</b> Đừng bỏ mất vế sau: <span class=\"zh\">虽然很贵，我喜欢</span> ✗ — phải có <span class=\"zh\">但是</span> mới thành câu.","examples":[{"zh":"虽然外面很冷，但是房间里很热。","py":"Suīrán wàimiàn hěn lěng, dànshì fángjiān lǐ hěn rè.","vi":"Tuy bên ngoài rất lạnh nhưng trong phòng rất nóng."},{"zh":"虽然汉字很难，但是我很喜欢写汉字。","py":"Suīrán Hànzì hěn nán, dànshì wǒ hěn xǐhuan xiě Hànzì.","vi":"Tuy chữ Hán rất khó nhưng tôi rất thích viết chữ Hán."},{"zh":"虽然是晴天，但是很冷。","py":"Suīrán shì qíngtiān, dànshì hěn lěng.","vi":"Tuy là trời nắng nhưng rất lạnh."}],"exercises":[]},{"title":"Bổ ngữ động lượng 次","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>动词</b><small>động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(过 / 了)</b><small>thể</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>数词</b><small>số từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>次</b><small>lần</small></span></div>","summary":"<p class=\"gr-lead\">Đếm số lần làm việc</p><ul><li><b>Cách dùng:</b> đặt <b>sau động từ</b>, biểu thị <b>số lần</b> xảy ra của động tác　·　hay đi cùng <span class=\"zh\">过 / 了</span>: <span class=\"zh\">去过三次</span></li></ul><div class=\"gr-sub\"><h4><span class=\"zh\">次 · 宾语是地点</span> · Trường hợp 1</h4><p>次 trước hay sau đều được</p><div class=\"ct-box\"><div class=\"ct-cap\">Tân ngữ chỉ địa điểm</div><div class=\"ct-intro\"><b>Công thức:</b> <span class=\"ct-lg b\">Động từ</span>过 + <span class=\"ct-lg k\">数词 + 次</span><span class=\"ct-lg a\">Địa điểm</span>　=　<span class=\"ct-lg b\">Động từ</span>过 + <span class=\"ct-lg a\">Địa điểm</span><span class=\"ct-lg k\">数词 + 次</span></div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>次 trước tân ngữ<small>V + 过 + 数词次 + 地点</small></th><th>次 sau tân ngữ<small>V + 过 + 地点 + 数词次</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">去过</b><small>qù guo</small></span><span class=\"ct-w c-k\"><b class=\"zh\">三次</b><small>sān cì</small></span><span class=\"ct-w c-a\"><b class=\"zh\">北京。</b><small>Běijīng.</small></span></div><div class=\"ct-vi\">Tôi đã đi Bắc Kinh ba lần.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">去过</b><small>qù guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">北京</b><small>Běijīng</small></span><span class=\"ct-w c-k\"><b class=\"zh\">三次。</b><small>sān cì.</small></span></div><div class=\"ct-vi\">Tôi đã đi Bắc Kinh ba lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他们</b><small>Tāmen</small></span><span class=\"ct-w c-b\"><b class=\"zh\">来过</b><small>lái guo</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次</b><small>yí cì</small></span><span class=\"ct-w c-a\"><b class=\"zh\">中国。</b><small>Zhōngguó.</small></span></div><div class=\"ct-vi\">Họ đã đến Trung Quốc một lần.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他们</b><small>Tāmen</small></span><span class=\"ct-w c-b\"><b class=\"zh\">来过</b><small>lái guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">中国</b><small>Zhōngguó</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次。</b><small>yí cì.</small></span></div><div class=\"ct-vi\">Họ đã đến Trung Quốc một lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">去过</b><small>qù guo</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次</b><small>yí cì</small></span><span class=\"ct-w c-a\"><b class=\"zh\">医院。</b><small>yīyuàn.</small></span></div><div class=\"ct-vi\">Tôi đã đi bệnh viện một lần.</div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">去过</b><small>qù guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">医院</b><small>yīyuàn</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次。</b><small>yí cì.</small></span></div><div class=\"ct-vi\">Tôi đã đi bệnh viện một lần.</div></td></tr></tbody></table></div></div></div><div class=\"gr-sub\"><h4><span class=\"zh\">次 · 宾语是人称代词</span> · Trường hợp 2</h4><p>次 đặt sau tân ngữ</p><div class=\"ct-box\"><div class=\"ct-cap\">Tân ngữ là đại từ nhân xưng</div><div class=\"ct-intro\"><b>Công thức:</b> <span class=\"ct-lg b\">Động từ</span>过 + <span class=\"ct-lg a\">Đại từ</span><span class=\"ct-lg k\">数词 + 次</span>　→ <span class=\"zh\">次</span> đứng <b>sau</b> tân ngữ</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>V + 过 + 代词 + 数词次<small>ví dụ</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我们</b><small>Wǒmen</small></span><span class=\"ct-w c-b\"><b class=\"zh\">找过</b><small>zhǎo guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">他</b><small>tā</small></span><span class=\"ct-w c-k\"><b class=\"zh\">三次。</b><small>sān cì.</small></span></div><div class=\"ct-vi\">Chúng tôi đã tìm anh ấy ba lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他们</b><small>Tāmen</small></span><span class=\"ct-w c-b\"><b class=\"zh\">看过</b><small>kàn guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">我</b><small>wǒ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次。</b><small>yí cì.</small></span></div><div class=\"ct-vi\">Họ đã đến thăm tôi một lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">老师</b><small>Lǎoshī</small></span><span class=\"ct-w c-b\"><b class=\"zh\">叫过</b><small>jiào guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">我</b><small>wǒ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">两次。</b><small>liǎng cì.</small></span></div><div class=\"ct-vi\">Thầy giáo đã gọi tôi hai lần.</div></td></tr></tbody></table></div></div></div><div class=\"gr-sub\"><h4><span class=\"zh\">次 · 其他宾语</span> · Trường hợp 3</h4><p>次 đặt trước tân ngữ</p><div class=\"ct-box\"><div class=\"ct-cap\">Tân ngữ còn lại (sự vật …)</div><div class=\"ct-intro\"><b>Công thức:</b> <span class=\"ct-lg b\">Động từ</span>过 + <span class=\"ct-lg k\">数词 + 次</span><span class=\"ct-lg a\">Tân ngữ</span>　→ <span class=\"zh\">次</span> đứng <b>trước</b> tân ngữ</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>V + 过 + 数词次 + 宾语<small>ví dụ</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">看过</b><small>kàn guo</small></span><span class=\"ct-w c-k\"><b class=\"zh\">三次</b><small>sān cì</small></span><span class=\"ct-w c-a\"><b class=\"zh\">这部电影。</b><small>zhè bù diànyǐng.</small></span></div><div class=\"ct-vi\">Tôi đã xem bộ phim này ba lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他们</b><small>Tāmen</small></span><span class=\"ct-w c-b\"><b class=\"zh\">坐过</b><small>zuò guo</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次</b><small>yí cì</small></span><span class=\"ct-w c-a\"><b class=\"zh\">飞机。</b><small>fēijī.</small></span></div><div class=\"ct-vi\">Họ đã đi máy bay một lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">买过</b><small>mǎi guo</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次</b><small>yí cì</small></span><span class=\"ct-w c-a\"><b class=\"zh\">这个东西。</b><small>zhège dōngxi.</small></span></div><div class=\"ct-vi\">Tôi đã mua thứ này một lần.</div></td></tr></tbody></table></div></div></div><div class=\"gr-sub\"><h4><span class=\"zh\">次 · 总结</span> · Học thuộc</h4><p>3 câu mẫu để nhớ vị trí của 次</p><div class=\"ct-box\"><div class=\"ct-cap\">Tổng hợp · học thuộc 3 câu mẫu</div><div class=\"tbl-scroll\"><table class=\"ct-tbl\"><thead><tr><th>Tân ngữ → vị trí 次<small>trường hợp</small></th><th>Câu mẫu<small>mỗi trường hợp nhớ 1 câu</small></th></tr></thead><tbody><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\">Địa điểm</span><span class=\"ct-w c-\">→ trước / sau đều được</span></div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">我</b><small>Wǒ</small></span><span class=\"ct-w c-b\"><b class=\"zh\">去过</b><small>qù guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">北京</b><small>Běijīng</small></span><span class=\"ct-w c-k\"><b class=\"zh\">三次。</b><small>sān cì.</small></span></div><div class=\"ct-vi\">Tôi đã đi Bắc Kinh ba lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\">Đại từ nhân xưng</span><span class=\"ct-w c-\">→ sau</span></div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">老师</b><small>Lǎoshī</small></span><span class=\"ct-w c-b\"><b class=\"zh\">叫过</b><small>jiào guo</small></span><span class=\"ct-w c-a\"><b class=\"zh\">我</b><small>wǒ</small></span><span class=\"ct-w c-k\"><b class=\"zh\">两次。</b><small>liǎng cì.</small></span></div><div class=\"ct-vi\">Thầy giáo đã gọi tôi hai lần.</div></td></tr><tr><td><div class=\"ct-ws\"><span class=\"ct-w c-a\">Tân ngữ còn lại</span><span class=\"ct-w c-\">→ trước</span></div></td><td><div class=\"ct-ws\"><span class=\"ct-w c-\"><b class=\"zh\">他们</b><small>Tāmen</small></span><span class=\"ct-w c-b\"><b class=\"zh\">坐过</b><small>zuò guo</small></span><span class=\"ct-w c-k\"><b class=\"zh\">一次</b><small>yí cì</small></span><span class=\"ct-w c-a\"><b class=\"zh\">飞机。</b><small>fēijī.</small></span></div><div class=\"ct-vi\">Họ đã đi máy bay một lần.</div></td></tr></tbody></table></div></div></div>","note":"","examples":[{"zh":"我去过三次北京。","py":"Wǒ qù guo sān cì Běijīng.","vi":"Tôi đã đi Bắc Kinh ba lần."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在教室","titleVi":"Trong lớp — rủ nhau đi xem phim","lines":[{"speaker":"甲","name":"Bạn A","zh":"你看过那个电影没有？","py":"Nǐ kàn guo nà ge diànyǐng méiyǒu?","vi":"Bạn xem bộ phim đó chưa?"},{"speaker":"乙","name":"Bạn B","zh":"没看过，听说很有意思。","py":"Méi kàn guo, tīngshuō hěn yǒu yìsi.","vi":"Chưa xem, nghe nói hay lắm."},{"speaker":"甲","name":"Bạn A","zh":"那我们下个星期一起去看吧？","py":"Nà wǒmen xià ge xīngqī yìqǐ qù kàn ba?","vi":"Vậy tuần sau mình cùng đi xem nhé?"},{"speaker":"乙","name":"Bạn B","zh":"可以，但是我女朋友也想去。","py":"Kěyǐ, dànshì wǒ nǚ péngyou yě xiǎng qù.","vi":"Được thôi, nhưng bạn gái mình cũng muốn đi."}]},{"titleZh":"课文二 · 在办公室","titleVi":"Ở văn phòng — hẹn cùng đi du lịch","lines":[{"speaker":"甲","name":"Bạn A","zh":"听说你去过中国，还想去吗？","py":"Tīngshuō nǐ qù guo Zhōngguó, hái xiǎng qù ma?","vi":"Nghe nói bạn từng đi Trung Quốc, còn muốn đi nữa không?"},{"speaker":"乙","name":"Bạn B","zh":"我虽然去过好几次，但是还想再去玩玩儿。","py":"Wǒ suīrán qù guo hǎo jǐ cì, dànshì hái xiǎng zài qù wánwanr.","vi":"Tuy mình đã đi mấy lần rồi nhưng vẫn muốn đi chơi thêm lần nữa."},{"speaker":"甲","name":"Bạn A","zh":"那我们一起去吧。","py":"Nà wǒmen yìqǐ qù ba.","vi":"Vậy mình đi cùng nhau nhé."},{"speaker":"乙","name":"Bạn B","zh":"好啊，到时候我给你打电话。","py":"Hǎo a, dào shíhou wǒ gěi nǐ dǎ diànhuà.","vi":"Được thôi, đến lúc đó mình gọi điện cho bạn."}]},{"titleZh":"课文三 · 在房间","titleVi":"Ở trong phòng — hỏi thời tiết","lines":[{"speaker":"甲","name":"Bạn A","zh":"明天天气怎么样？","py":"Míngtiān tiānqì zěnmeyàng?","vi":"Thời tiết ngày mai thế nào?"},{"speaker":"乙","name":"Bạn B","zh":"虽然是晴天，但是很冷。","py":"Suīrán shì qíngtiān, dànshì hěn lěng.","vi":"Tuy là trời nắng nhưng rất lạnh."},{"speaker":"甲","name":"Bạn A","zh":"那还能去跑步吗？","py":"Nà hái néng qù pǎobù ma?","vi":"Vậy vẫn đi chạy bộ được chứ?"},{"speaker":"乙","name":"Bạn B","zh":"可以，但是你自己去吧，我还有很多事情要做。","py":"Kěyǐ, dànshì nǐ zìjǐ qù ba, wǒ hái yǒu hěn duō shìqing yào zuò.","vi":"Được, nhưng bạn tự đi nhé, mình còn nhiều việc phải làm."}]},{"titleZh":"课文四 · 在商店","titleVi":"Trong cửa hàng — chọn mua áo","lines":[{"speaker":"甲","name":"Bạn A","zh":"你在这个商店买过东西没有？","py":"Nǐ zài zhè ge shāngdiàn mǎi guo dōngxi méiyǒu?","vi":"Bạn từng mua đồ ở cửa hàng này chưa?"},{"speaker":"乙","name":"Bạn B","zh":"买过一次，这儿的东西还可以，就是不便宜。","py":"Mǎi guo yí cì, zhèr de dōngxi hái kěyǐ, jiù shì bù piányi.","vi":"Mua một lần rồi, đồ ở đây cũng được, chỉ mỗi tội không rẻ."},{"speaker":"甲","name":"Bạn A","zh":"我喜欢这件衣服，但是觉得有点儿贵。","py":"Wǒ xǐhuan zhè jiàn yīfu, dànshì juéde yǒudiǎnr guì.","vi":"Mình thích chiếc áo này, nhưng thấy hơi đắt."},{"speaker":"乙","name":"Bạn B","zh":"200块还可以，喜欢就买吧。","py":"Èrbǎi kuài hái kěyǐ, xǐhuan jiù mǎi ba.","vi":"Hai trăm tệ cũng được mà, thích thì mua đi."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu của câu cảm thán","introZh":"汉语感叹句的句调一般为降调。","introVi":"Trong tiếng Trung Quốc, câu cảm thán thường được đọc xuống giọng.","zh":"感叹句的句调","py":"gǎntànjù de jùdiào","tag":"Ngữ điệu","vi":"Câu cảm thán · xuống giọng ↘","listZh":"感叹句的句调","listVi":"Câu cảm thán (真……啊！ · 太……了！) — thường đọc xuống giọng ↘","descZh":"汉语感叹句的句调一般为降调。","descVi":"Trong tiếng Trung Quốc, câu cảm thán thường được đọc xuống giọng.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"真 / 太 + 形容词","s":"nói mạnh, rõ"},{"l":"啊！/ 了！","s":"cuối câu đọc nhẹ"}],[{"l":"感叹句","s":"câu cảm thán"},{"l":"降调 ↘","s":"xuống giọng","dn":true}]],"tip":"Câu cảm thán hay có <span class=\"zh\">真……啊！</span> hoặc <span class=\"zh\">太……了！</span>: nói <b>mạnh, rõ</b> ở <span class=\"zh\">真 / 太</span> + tính từ, đến cuối câu <b>xuống giọng ↘</b> — <span class=\"zh\">啊 / 了</span> đọc nhẹ.","readLbl":"Luyện đọc · cuối câu xuống giọng ↘","sents":[{"tone":"down","w":[{"hz":"今天","py":"Jīntiān"},{"hz":"天气","py":"tiānqì"},{"hz":"真","py":"zhēn"},{"hz":"好啊！","py":"hǎo a!"}],"vi":"Hôm nay thời tiết đẹp quá!"},{"tone":"down","w":[{"hz":"这个","py":"Zhège"},{"hz":"汉字","py":"Hànzì"},{"hz":"真","py":"zhēn"},{"hz":"难","py":"nán"},{"hz":"写啊！","py":"xiě a!"}],"vi":"Chữ Hán này khó viết quá!"},{"tone":"down","w":[{"hz":"这","py":"Zhè"},{"hz":"件衣服","py":"jiàn yīfu"},{"hz":"太","py":"tài","j":true},{"hz":"漂亮","py":"piàoliang"},{"hz":"了！","py":"le!"}],"vi":"Chiếc áo này đẹp quá!"}]}],"activity":{"act":[],"speak":[{"tag":"Hoạt động nhóm","mean":"Xây khung · Kể chuyện","q":{"zh":"说一说你的一次旅游。","py":"Shuō yi shuō nǐ de yí cì lǚyóu.","vi":"Hãy kể lại một chuyến du lịch của bạn."},"prep":3,"talk":2,"frame":[{"lbl":"开头","zh":"我去过……次……。","py":"","vi":"Mở bài","ex":null},{"lbl":"中间","zh":"我是……的时候和……一起去的，我们是坐……去的。","py":"","vi":"Thân bài · 1","ex":null},{"lbl":"中间","zh":"那儿虽然……，但是……。","py":"","vi":"Thân bài · 2","ex":null},{"lbl":"结尾","zh":"那儿真……啊！我还想再去一次。","py":"","vi":"Kết bài","ex":null}]}]}},{"id":"k2v2-b15","courseId":"k2v2","order":15,"title":"Năm mới sắp đến rồi","titleZh":"新年就要到了","titlePy":"xīnnián jiù yào dào le","vocab":[{"stt":1,"hanzi":"日","pinyin":"rì","hanviet":"Nhật","pos":"Danh từ","meaning":"ngày; mặt trời","comps":"日期 (ngày tháng), 生日 (sinh nhật)","example":{"zh":"今天是十二月二十日。","py":"Jīntiān shì shí'èr yuè èrshí rì.","vi":"Hôm nay là ngày 20 tháng 12."}},{"stt":2,"hanzi":"新年","pinyin":"xīnnián","hanviet":"Tân niên","pos":"Danh từ","meaning":"năm mới, Tết","comps":"过新年 (đón năm mới), 新年好 (chúc mừng năm mới)","example":{"zh":"新年就要到了。","py":"Xīnnián jiù yào dào le.","vi":"Năm mới sắp đến rồi."}},{"stt":3,"hanzi":"票","pinyin":"piào","hanviet":"Phiếu","pos":"Danh từ","meaning":"vé, phiếu","comps":"买票 (mua vé), 火车票 (vé tàu hoả)","example":{"zh":"我明天去买票。","py":"Wǒ míngtiān qù mǎi piào.","vi":"Ngày mai mình đi mua vé."}},{"stt":4,"hanzi":"火车站","pinyin":"huǒchēzhàn","hanviet":"Hoả xa trạm","pos":"Danh từ","meaning":"ga tàu hoả","comps":"去火车站 (ra ga tàu), 火车票 (vé tàu hoả)","example":{"zh":"我去火车站买票。","py":"Wǒ qù huǒchēzhàn mǎi piào.","vi":"Mình ra ga tàu mua vé."}},{"stt":5,"hanzi":"大家","pinyin":"dàjiā","hanviet":"Đại gia","pos":"Đại từ","meaning":"mọi người, tất cả","comps":"谢谢大家 (cảm ơn mọi người), 大家好 (chào mọi người)","example":{"zh":"谢谢大家的帮助。","py":"Xièxie dàjiā de bāngzhù.","vi":"Cảm ơn sự giúp đỡ của mọi người."}},{"stt":6,"hanzi":"更","pinyin":"gèng","hanviet":"Cánh","pos":"Phó từ","meaning":"càng, hơn nữa","comps":"更好 (tốt hơn), 更多 (nhiều hơn)","example":{"zh":"希望明年更好！","py":"Xīwàng míngnián gèng hǎo!","vi":"Mong sang năm còn tốt hơn nữa!"}},{"stt":7,"hanzi":"妹妹","pinyin":"mèimei","hanviet":"Muội muội","pos":"Danh từ","meaning":"em gái","comps":"我妹妹 (em gái tôi), 姐姐和妹妹 (chị và em gái)","example":{"zh":"我妹妹还没来。","py":"Wǒ mèimei hái méi lái.","vi":"Em gái mình vẫn chưa tới."}},{"stt":8,"hanzi":"阴","pinyin":"yīn","hanviet":"Âm","pos":"Tính từ","meaning":"âm u, nhiều mây","comps":"阴天 (trời âm u), 天阴了 (trời tối sầm lại)","example":{"zh":"今天是阴天。","py":"Jīntiān shì yīntiān.","vi":"Hôm nay trời âm u."}}],"hanzi":[{"char":"日","pinyin":"rì","hanviet":"Nhật","chars":["日"],"story":"日 là chữ tượng hình vẽ mặt trời: vòng tròn bao ngoài, chấm ở giữa là vệt đen trên mặt trời; viết vuông lại thành 日 như hôm nay. Mặt trời mọc rồi lặn một vòng là một ngày, nên 日 còn nghĩa là \"ngày\" — dùng trong văn viết, còn khẩu ngữ thì nói 号."},{"char":"新年","pinyin":"xīnnián","hanviet":"Tân niên","chars":["新","年"],"story":"新 gồm 亲 chỉ âm và 斤 (cái rìu) — nghĩa gốc là đốn cây, khúc gỗ vừa đẽo ra thì tươi mới. 年 vốn vẽ người vác bó lúa chín trên lưng: gặt xong một mùa lúa là hết một năm. Ghép lại 新年 là \"năm mới\"."},{"char":"票","pinyin":"piào","hanviet":"Phiếu","chars":["票"],"story":"票 gồm phần trên 覀 và phần dưới 示 (cái bàn thờ, chỉ dấu hiệu, bằng chứng). Ngày nay 票 là tờ giấy làm bằng chứng cho một quyền lợi — tấm vé, lá phiếu: 车票 (vé xe), 电影票 (vé xem phim), 发票 (hoá đơn)."},{"char":"火车站","pinyin":"huǒchēzhàn","hanviet":"Hoả xa trạm","chars":["火","车","站"],"story":"火 vẽ ngọn lửa đang bốc cháy; 车 vẽ chiếc xe nhìn từ trên xuống, nét sổ dọc là trục, hai nét ngang là bánh xe. 火车 nghĩa đen là \"xe chạy bằng lửa\" — tàu hoả chạy hơi nước ngày trước. 站 gồm 立 (đứng) và 占 chỉ âm: chỗ dừng lại đứng chờ. Ghép cả ba là \"ga tàu hoả\"."},{"char":"大家","pinyin":"dàjiā","hanviet":"Đại gia","chars":["大","家"],"story":"大 vẽ một người dang rộng hai tay hai chân, nghĩa là \"to lớn\". 家 gồm 宀 (mái nhà) và 豕 (con lợn) — nhà người xưa nuôi lợn ngay dưới sàn. 大家 vốn nghĩa \"cả nhà lớn\", nay dùng để gọi chung tất cả những người có mặt: \"mọi người\"."},{"char":"更","pinyin":"gèng","hanviet":"Cánh","chars":["更"],"story":"更 có hai âm: đọc gēng nghĩa gốc là \"thay đổi, đổi mới\" (更换 — thay thế); đọc gèng thì thành phó từ \"càng, hơn nữa\" — từ ý \"đổi sang một mức khác\" mà ra. Nhớ 更好 (tốt hơn nữa), 更多 (nhiều hơn nữa)."},{"char":"妹妹","pinyin":"mèimei","hanviet":"Muội muội","chars":["妹","妹"],"story":"妹 gồm bộ Nữ 女 (con gái) chỉ nghĩa và 未 wèi chỉ âm — 未 nghĩa là \"chưa\", gợi đúng hình ảnh người con gái sinh sau, chưa lớn bằng chị. Lặp lại thành 妹妹 nghe thân mật, giống 姐姐, 哥哥, 弟弟."},{"char":"阴","pinyin":"yīn","hanviet":"Âm","chars":["阴"],"story":"阴 gồm bộ 阝 (gò núi) bên trái và 月 (mặt trăng) bên phải: sườn núi khuất nắng, chỉ có ánh trăng — chỗ râm mát, u ám. Nhớ theo cặp đối lập: 阴 (có 月) ↔ 阳 (có 日), và trái nghĩa với 晴 vừa học ở bài 14."}],"grammar":[{"title":"Trạng thái động tác \"要……了\"","formula":"<div class=\"fx-row\"><span class=\"fx-p\"><b>(就 / 快)</b><small>sắp ngay</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>要</b><small>sắp</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>动词短语</b><small>cụm động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>rồi</small></span></div>","summary":"<p class=\"gr-lead\">Việc sắp xảy ra</p><ul><li>Khuôn <span class=\"zh\">要……了</span> báo việc <b>sắp xảy ra ngay</b>: <span class=\"zh\">新年就要到了</span> (năm mới sắp đến rồi). Chữ <span class=\"zh\">了</span> cuối câu <b>không được thiếu</b>.</li><li>Ba biến thể cùng nghĩa, chỉ khác mức độ gấp: <span class=\"zh\">要……了</span> · <span class=\"zh\">就要……了</span> (rất gần) · <span class=\"zh\">快要……了</span> (nhanh tới nơi).</li><li>Khác <span class=\"zh\">要</span> động từ năng nguyện (bài 1: \"muốn, cần\"): ở đây <span class=\"zh\">要</span> là <b>phó từ báo thời gian</b>, không mang nghĩa muốn.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">新年就要到了。</span>　·　<span class=\"zh\">快要下雨了。</span>　·　<span class=\"zh\">我要回去了。</span></p>","note":"<b>Lưu ý:</b> Chỉ <span class=\"zh\">就要……了</span> mới đi được với <b>từ chỉ thời gian</b>: <span class=\"zh\">明天就要到了</span> ✓ · <span class=\"zh\">明天快要到了</span> ✗.","examples":[{"zh":"火车快要来了。","py":"Huǒchē kuài yào lái le.","vi":"Tàu hoả sắp đến rồi."},{"zh":"要下雨了。","py":"Yào xià yǔ le.","vi":"Sắp mưa rồi."},{"zh":"新的一年快要到了。","py":"Xīn de yì nián kuài yào dào le.","vi":"Năm mới sắp đến rồi."},{"zh":"下个月我们就要回国了。","py":"Xià ge yuè wǒmen jiù yào huí guó le.","vi":"Tháng sau chúng tôi sắp về nước rồi."},{"zh":"明天姐姐就要走了。","py":"Míngtiān jiějie jiù yào zǒu le.","vi":"Ngày mai chị gái sắp đi rồi."},{"zh":"下个星期我们就要考试了。","py":"Xià ge xīngqī wǒmen jiù yào kǎoshì le.","vi":"Tuần sau chúng tôi sắp thi rồi."}],"exercises":[]},{"title":"Cách nói nhấn mạnh 都……了","formula":"<div class=\"fx-row\"><span class=\"fx-p key\"><b>都</b><small>đã… tận</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>(动词短语)</b><small>cụm động từ</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p\"><b>时间 / 数量</b><small>thời gian, số lượng</small></span><i class=\"fx-plus\">+</i><span class=\"fx-p key\"><b>了</b><small>rồi</small></span></div>","summary":"<p class=\"gr-lead\">Nhấn: đã … rồi đấy</p><ul><li><span class=\"zh\">都</span> ở đây <b>không phải</b> nghĩa \"đều\" (bài 14 HSK1) mà là <b>phó từ nhấn mạnh</b> — gần nghĩa <span class=\"zh\">已经</span> nhưng giàu cảm xúc hơn nhiều.</li><li>Thường đi kèm <b>thời gian hoặc số lượng</b> để than rằng đã <b>muộn quá, nhiều quá</b>: <span class=\"zh\">都8:40了</span>, <span class=\"zh\">都等她半个小时了</span>.</li><li>Cuối câu <b>bắt buộc có</b> <span class=\"zh\">了</span>, giọng đọc sốt ruột, thường kèm dấu chấm than.</li></ul><p class=\"gr-key\"><b>Ghi nhớ:</b> <span class=\"zh\">都8:40了！</span> = Đã 8 giờ 40 rồi!　·　<span class=\"zh\">都等她半个小时了！</span> = Đợi tận nửa tiếng rồi!</p>","note":"<b>Lưu ý:</b> Đừng dịch thành \"đều\": <span class=\"zh\">都8:40了</span> = \"đã 8 giờ 40 rồi cơ\" chứ không phải \"đều 8:40\".","examples":[{"zh":"都8点了，快点儿起床吧。","py":"Dōu bā diǎn le, kuài diǎnr qǐchuáng ba.","vi":"Đã 8 giờ rồi, mau dậy đi."},{"zh":"你都十岁了，可以自己洗衣服了。","py":"Nǐ dōu shí suì le, kěyǐ zìjǐ xǐ yīfu le.","vi":"Con đã mười tuổi rồi, có thể tự giặt quần áo được rồi."},{"zh":"都等她半个小时了。","py":"Dōu děng tā bàn ge xiǎoshí le.","vi":"Đã đợi cô ấy nửa tiếng rồi."}],"exercises":[]}],"text":{"title":"课文 · Bài khoá","blocks":[{"titleZh":"课文一 · 在朋友家","titleVi":"Ở nhà bạn — bàn chuyện đi chơi Tết","lines":[{"speaker":"甲","name":"Bạn A","zh":"今天是12月20日，新年就要到了。","py":"Jīntiān shì shí'èr yuè èrshí rì, xīnnián jiù yào dào le.","vi":"Hôm nay là ngày 20 tháng 12, năm mới sắp đến rồi."},{"speaker":"乙","name":"Bạn B","zh":"新年你准备做什么？","py":"Xīnnián nǐ zhǔnbèi zuò shénme?","vi":"Tết bạn định làm gì?"},{"speaker":"甲","name":"Bạn A","zh":"我想去北京旅游，北京很不错，我去过一次。","py":"Wǒ xiǎng qù Běijīng lǚyóu, Běijīng hěn búcuò, wǒ qù guo yí cì.","vi":"Mình muốn đi du lịch Bắc Kinh, Bắc Kinh hay lắm, mình từng đi một lần rồi."},{"speaker":"乙","name":"Bạn B","zh":"你买票了吗？","py":"Nǐ mǎi piào le ma?","vi":"Bạn mua vé chưa?"},{"speaker":"甲","name":"Bạn A","zh":"还没有呢，明天就去火车站买票。","py":"Hái méiyǒu ne, míngtiān jiù qù huǒchēzhàn mǎi piào.","vi":"Vẫn chưa, mai mình ra ga mua vé luôn."}]},{"titleZh":"课文二 · 在公司","titleVi":"Ở công ty — tổng kết cuối năm","lines":[{"speaker":"甲","name":"Bạn A","zh":"时间过得真快，新的一年快要到了！","py":"Shíjiān guò de zhēn kuài, xīn de yì nián kuài yào dào le!","vi":"Thời gian trôi nhanh thật, một năm mới sắp đến rồi!"},{"speaker":"乙","name":"Bạn B","zh":"是啊，谢谢大家这一年对我的帮助！","py":"Shì a, xièxie dàjiā zhè yì nián duì wǒ de bāngzhù!","vi":"Đúng vậy, cảm ơn mọi người đã giúp đỡ tôi suốt năm qua!"},{"speaker":"甲","name":"Bạn A","zh":"希望我们的公司明年更好！","py":"Xīwàng wǒmen de gōngsī míngnián gèng hǎo!","vi":"Mong công ty mình sang năm còn tốt hơn nữa!"}]},{"titleZh":"课文三 · 在车站","titleVi":"Ở nhà ga — sốt ruột đợi em gái","lines":[{"speaker":"甲","name":"Bạn A","zh":"你妹妹怎么还没来？都8:40了！","py":"Nǐ mèimei zěnme hái méi lái? Dōu bā diǎn sìshí le!","vi":"Em gái bạn sao vẫn chưa tới? Đã 8 giờ 40 rồi!"},{"speaker":"乙","name":"Bạn B","zh":"我们再等她几分钟吧？","py":"Wǒmen zài děng tā jǐ fēnzhōng ba?","vi":"Mình đợi cô ấy thêm mấy phút nữa nhé?"},{"speaker":"甲","name":"Bạn A","zh":"都等她半个小时了！","py":"Dōu děng tā bàn ge xiǎoshí le!","vi":"Đợi cô ấy tận nửa tiếng rồi đấy!"},{"speaker":"乙","name":"Bạn B","zh":"她来了，我听见她说话了。","py":"Tā lái le, wǒ tīngjiàn tā shuōhuà le.","vi":"Cô ấy tới rồi kìa, mình nghe thấy tiếng cô ấy nói rồi."}]},{"titleZh":"课文四 · 在咖啡馆门口","titleVi":"Trước quán cà phê — trời sắp mưa","lines":[{"speaker":"甲","name":"Bạn A","zh":"天阴了，我要回去了。","py":"Tiān yīn le, wǒ yào huíqù le.","vi":"Trời tối sầm rồi, mình phải về đây."},{"speaker":"乙","name":"Bạn B","zh":"好的。快要下雨了，你路上慢点。","py":"Hǎo de. Kuài yào xià yǔ le, nǐ lù shang màn diǎn.","vi":"Được. Sắp mưa rồi đấy, đi đường cẩn thận nhé."},{"speaker":"甲","name":"Bạn A","zh":"没关系，我坐公共汽车。","py":"Méi guānxi, wǒ zuò gōnggòng qìchē.","vi":"Không sao đâu, mình đi xe buýt."},{"speaker":"乙","name":"Bạn B","zh":"好的。再见。","py":"Hǎo de. Zàijiàn.","vi":"Ừ. Tạm biệt nhé."}]}]},"extra":[],"phon":[{"id":"pa-01","grp":"句调","grpVi":"Ngữ điệu của câu hỏi có từ 吧 và 吗","introZh":"用“吧”构成的疑问句的句调为降调，用“吗”构成的疑问句的句调为升调。","introVi":"Câu hỏi có từ 吧 được đọc xuống giọng còn câu hỏi có từ 吗 được đọc lên giọng.","zh":"“吧”和“吗”疑问句的句调","py":"ba hé ma yíwènjù de jùdiào","tag":"Ngữ điệu","vi":"吧 xuống ↘ · 吗 lên ↗","listZh":"用“吧”和“吗”构成的疑问句的句调","listVi":"Câu hỏi có 吧 đọc xuống giọng ↘ · câu hỏi có 吗 đọc lên giọng ↗","descZh":"用“吧”构成的疑问句的句调为降调，用“吗”构成的疑问句的句调为升调。","descVi":"Câu hỏi có từ 吧 được đọc xuống giọng còn câu hỏi có từ 吗 được đọc lên giọng.","patLbl":"Sơ đồ ngữ điệu","patRows":[[{"l":"……吧？","s":"đã đoán, muốn xác nhận"},{"l":"降调 ↘","s":"xuống giọng","dn":true}],[{"l":"……吗？","s":"chưa biết, hỏi thật"},{"l":"升调 ↗","s":"lên giọng","st":true}]],"readLbl":"Luyện đọc · 吧 xuống giọng ↘ · 吗 lên giọng ↗","sents":[{"pair":[{"tone":"down","w":[{"hz":"这","py":"Zhè"},{"hz":"本","py":"běn"},{"hz":"书","py":"shū"},{"hz":"是你的吧？","py":"shì nǐ de ba?"}],"vi":"Cuốn sách này là của bạn nhỉ?"},{"tone":"up","w":[{"hz":"这","py":"Zhè"},{"hz":"本","py":"běn"},{"hz":"书","py":"shū"},{"hz":"是你的吗？","py":"shì nǐ de ma?"}],"vi":"Cuốn sách này là của bạn à?"}]},{"pair":[{"tone":"down","w":[{"hz":"明天","py":"Míngtiān"},{"hz":"是","py":"shì"},{"hz":"星期","py":"xīngqī"},{"hz":"二","py":"èr"},{"hz":"吧？","py":"ba?"}],"vi":"Ngày mai là thứ Ba nhỉ?"},{"tone":"up","w":[{"hz":"明天","py":"Míngtiān"},{"hz":"是","py":"shì"},{"hz":"星期","py":"xīngqī"},{"hz":"二","py":"èr"},{"hz":"吗？","py":"ma?"}],"vi":"Ngày mai là thứ Ba à?"}]},{"pair":[{"tone":"down","w":[{"hz":"你","py":"Nǐ"},{"hz":"买","py":"mǎi"},{"hz":"票","py":"piào"},{"hz":"了吧？","py":"le ba?"}],"vi":"Bạn mua vé rồi nhỉ?"},{"tone":"up","w":[{"hz":"你","py":"Nǐ"},{"hz":"买","py":"mǎi"},{"hz":"票","py":"piào"},{"hz":"了吗？","py":"le ma?"}],"vi":"Bạn mua vé chưa?"}]}]}]}];
